import { GoogleGenAI, Modality, GenerateContentResponse } from "@google/genai";

const API_KEY = process.env.API_KEY;
if (!API_KEY) {
    throw new Error("API_KEY is not defined in environment variables");
}

const ai = new GoogleGenAI({ apiKey: API_KEY });

type ClothingType = 'Áo' | 'Quần' | 'Cả bộ' | 'Váy' | 'Phụ kiện';
type Gender = 'Nam' | 'Nữ';
export type ModelPose = 'Dáng đứng' | 'Dáng đi' | 'Giới thiệu (Cầm móc)' | 'Giới thiệu (Chỉ mặc)';
export type AspectRatio = '9:16' | '1:1' | '4:5' | '16:9';
export type ProductDisplayMode = 'hanger' | 'flatlay';

export type ScriptType = 'Review sản phẩm' | 'Quảng cáo sản phẩm' | 'Chào hàng (Sale)';
export type VoiceGender = 'Nam' | 'Nữ';
export type RegionalAccent = 'Miền Bắc' | 'Miền Nam'; // New type for accents
export type VoiceoverStyle = 'Năng động' | 'Trang trọng' | 'Thân thiện';

export interface ReviewScriptOptions {
    productInfo: string;
    scriptType: ScriptType;
    accent: RegionalAccent; // Changed from voiceGender
}

export interface ReviewScriptResult {
    hook: string;
    body: string;
    cta: string;
}

export interface VideoPromptOptions {
    productInfo: string;
    targetAudience: string;
    videoStyle: string;
}

export interface ModelOptions {
    clothingType: ClothingType;
    gender: Gender;
    age: string; // e.g., '18-25'
    background: string;
    numberOfImages: number;
    pose: ModelPose;
    aspectRatio: AspectRatio;
}

export interface LookbookOptions {
    clothingType: ClothingType;
    gender: Gender;
    age: string;
    theme: string;
    additionalPrompt?: string;
    numberOfImages: number;
    pose: ModelPose;
    aspectRatio: AspectRatio;
}

export interface LookbookResult {
    imageUrl: string;
    videoPrompt: string;
}

export interface ModelResult {
    imageUrl: string;
    videoPrompt?: string;
}


export interface EnhanceOptions {
    upscale: boolean;
    sharpen: boolean;
    removeWatermark: boolean;
}

const getClothingPhrase = (type: ClothingType) => {
    switch (type) {
        case 'Áo':
            return 'chiếc áo';
        case 'Quần':
            return 'chiếc quần';
        case 'Váy':
            return 'chiếc váy';
        case 'Cả bộ':
            return 'bộ trang phục';
        case 'Phụ kiện':
            return 'món phụ kiện thời trang';
    }
};

const getAspectRatioPhrase = (ratio: AspectRatio) => {
    switch (ratio) {
        case '9:16':
            return 'tỉ lệ 9:16 (dọc)';
        case '1:1':
            return 'tỉ lệ 1:1 (vuông)';
        case '4:5':
            return 'tỉ lệ 4:5 (dọc)';
        case '16:9':
            return 'tỉ lệ 16:9 (ngang)';
    }
};

const callGeminiApiForImage = async (imagePart: object, textPart: object): Promise<string> => {
     const response: GenerateContentResponse = await ai.models.generateContent({
            model: 'gemini-2.5-flash-image',
            contents: {
                parts: [imagePart, textPart],
            },
            config: {
                responseModalities: [Modality.IMAGE],
            },
        });

    for (const part of response.candidates?.[0]?.content?.parts || []) {
        if (part.inlineData) {
            return part.inlineData.data;
        }
    }

    throw new Error("Không tìm thấy dữ liệu hình ảnh trong phản hồi của AI.");
}


export const generateStyledImage = async (base64Image: string, mimeType: string, clothingType: ClothingType, aspectRatio: AspectRatio, displayMode: ProductDisplayMode = 'hanger'): Promise<string> => {
    try {
        const imagePart = {
            inlineData: {
                data: base64Image,
                mimeType: mimeType,
            },
        };

        const clothingItem = getClothingPhrase(clothingType);
        const ratioPhrase = getAspectRatioPhrase(aspectRatio);

        // Logic prompt dựa trên cách trình bày (Display Mode)
        let presentationInstruction = "";

        if (displayMode === 'flatlay') {
            presentationInstruction = `Trong hình ảnh mới, ${clothingItem} này phải được đặt trải phẳng (flatlay) một cách tự nhiên và gọn gàng trên một tấm thảm lông (fur rug) mềm mại, sang trọng. Màu của thảm nên trung tính (như trắng kem, xám nhạt hoặc be) để làm nổi bật sản phẩm. Góc chụp từ trên cao xuống (top-down view) để thấy rõ kiểu dáng. Ánh sáng tự nhiên, dịu nhẹ, tạo cảm giác ấm cúng và cao cấp.`;
        } else {
            // Default: Hanger logic (Treo móc)
            // Logic prompt khác biệt cho Phụ kiện (đặt trên bàn) vs Quần áo (treo móc)
            if (clothingType === 'Phụ kiện') {
                presentationInstruction = `Trong hình ảnh mới, ${clothingItem} này phải được đặt một cách tinh tế và nghệ thuật trên một bề mặt bàn sang trọng (ví dụ: gỗ vân đẹp, đá cẩm thạch trắng, hoặc bục trưng bày sản phẩm). Nó có thể được bài trí theo phong cách Flatlay hoặc chụp góc nghiêng nhẹ để thấy rõ chi tiết.`;
            } else {
                presentationInstruction = `Trong hình ảnh mới, ${clothingItem} này phải được treo trên một chiếc móc treo bằng gỗ hoặc kim loại sang trọng, phù hợp với kiểu dáng của nó. Bối cảnh xung quanh phải là một không gian đẹp, tối giản và trang nhã, có ánh sáng tự nhiên dịu nhẹ, giống như một phòng trưng bày thời trang cao cấp.`;
            }
        }

        const textPart = {
            text: `Từ hình ảnh ${clothingItem} được cung cấp, hãy tạo ra một hình ảnh mới, chất lượng cao, độ phân giải 2K, với ${ratioPhrase}. Quan trọng: Nếu hình ảnh gốc có viền đen ở trên hoặc dưới (letterboxing), hãy bỏ qua các viền đen đó và đảm bảo hình ảnh kết quả lấp đầy toàn bộ khung hình, chỉ tập trung vào sản phẩm. ${presentationInstruction} Không có người hoặc ma-nơ-canh trong ảnh. Hình ảnh cuối cùng phải có độ sắc nét cực cao, chi tiết, chất lượng cao, và có tính thẩm mỹ cao, như thể được chụp bằng máy ảnh kỹ thuật số chuyên nghiệp.`,
        };

        return await callGeminiApiForImage(imagePart, textPart);

    } catch (error) {
        console.error("Lỗi khi gọi Gemini API cho ảnh sản phẩm:", error);
        throw new Error("AI không thể tạo ảnh sản phẩm. Vui lòng thử lại.");
    }
};

// Helper function to create the specific static video prompt
const generateStaticIntroVideoPrompt = async (clothingType: string, background: string) => {
    // We construct this prompt directly or use AI if we want more variety. 
    // Given the user's strict requirements, a template with AI filling might be safer, 
    // but let's use AI to ensure the clothing description matches the vibe.

    const prompt = `Create a video generation prompt in English.
    Context: A fashion model is standing still in a ${background}, wearing a ${clothingType}.
    Action: The model is also holding a hanger with the EXACT SAME ${clothingType} on it, holding it up to chest level to show it to the viewer.
    Camera: Static camera (Tripod shot). No movement.
    Requirement: The prompt must specify "Dialogue: [Insert Dialogue Here]".

    Output ONLY the prompt text.`;

    // Since we don't have the image context inside this helper easily without passing base64 again (which is heavy),
    // we will use a high-quality template string which is faster and follows the strict rule.

    return `Static camera shot, tripod view. A professional model stands completely still in a ${background}, wearing the outfit. Simultaneously, the model holds a hanger with the exact same outfit on it, raising it to chest level to display it clearly to the audience. The model looks directly at the camera with a friendly expression. High resolution, photorealistic. Dialogue: [Insert Dialogue Here]`;
};

export const generateModelImage = async (base64Image: string, mimeType: string, options: ModelOptions): Promise<ModelResult[]> => {
    try {
        const { clothingType, gender, age, background, numberOfImages, pose, aspectRatio } = options;

        const imagePart = {
            inlineData: {
                data: base64Image,
                mimeType: mimeType,
            },
        };

        const clothingItem = getClothingPhrase(clothingType);
        const ratioPhrase = getAspectRatioPhrase(aspectRatio);

        let modelDescription: string;
        if (age === '5-10') {
            const childGenderText = gender === 'Nam' ? 'bé trai' : 'bé gái';
            modelDescription = `Một ${childGenderText} người Việt Nam, đáng yêu, xinh xắn, trong độ tuổi từ 5 đến 10,`;
        } else {
            const genderText = gender === 'Nam' ? 'nam' : 'nữ';
            let modelSpecifics = "";
            if (gender === 'Nam') {
                modelSpecifics = "có làn da trắng sáng, đẹp trai, tươi tắn, trẻ trung, ";
            }
            modelDescription = `Một người mẫu ${genderText} người Việt Nam, ${modelSpecifics}trong độ tuổi ${age},`;
        }

        const subject = age === '5-10' ? 'Bé' : 'Người mẫu';
        const subjectPronoun = age === '5-10' ? 'bé' : 'người mẫu';

        let poseSpecifics = '';
        let videoPromptTemplate = '';

        switch (pose) {
            case 'Dáng đi':
                poseSpecifics = `${subject} đang tạo dáng trong tư thế đang đi một cách tự nhiên và phong cách`;
                break;
            case 'Giới thiệu (Cầm móc)':
                 if (clothingType === 'Phụ kiện') {
                    poseSpecifics = `${subject} đang cầm ${clothingItem} trên tay đưa về phía trước để giới thiệu. ${subject} nhìn thẳng vào máy ảnh.`;
                    videoPromptTemplate = `Static camera shot. The model stands strictly still in a ${background}, holding the accessory up to the camera to introduce it. The model looks at the camera. High quality, 4k. Dialogue: [Insert Dialogue Here]`;
                 } else {
                    // Updated specific prompt for "Giới thiệu trang phục"
                    poseSpecifics = `${subject} đang mặc ${clothingItem}. ĐIỀU QUAN TRỌNG: Đồng thời, hai tay ${subject} đang cầm một chiếc móc treo quần áo, trên móc treo đó có treo MỘT CHIẾC ${clothingItem} Y HỆT (bản sao của cái đang mặc). ${subject} giơ chiếc móc treo đó lên ngang ngực để giới thiệu sản phẩm cho người xem. ${subject} nhìn thẳng vào máy ảnh, mỉm cười thân thiện.`;
                    videoPromptTemplate = `Static camera shot. The model stands strictly still in a ${background}, wearing the outfit and holding up a hanger with the exact same outfit to chest level to introduce it. The model looks at the camera. High quality, 4k. Dialogue: [Insert Dialogue Here]`;
                 }
                break;
            case 'Giới thiệu (Chỉ mặc)':
                 if (clothingType === 'Phụ kiện') {
                    poseSpecifics = `${subject} đang đeo/sử dụng ${clothingItem}. ${subject} nhìn thẳng vào máy ảnh, tay chỉ nhẹ vào sản phẩm để giới thiệu.`;
                    videoPromptTemplate = `Static camera shot. The model stands strictly still in a ${background}, wearing/using the accessory. The model looks at the camera and points to the product to introduce it. High quality, 4k. Dialogue: [Insert Dialogue Here]`;
                 } else {
                    poseSpecifics = `${subject} đang mặc ${clothingItem}. ${subject} đứng yên đối diện camera, hai tay buông lỏng tự nhiên hoặc đặt nhẹ lên hông, mỉm cười và nhìn thẳng vào ống kính để giới thiệu bộ trang phục mình đang mặc. Phong cách trình bày sản phẩm trực diện.`;
                    videoPromptTemplate = `Static camera shot. The model stands strictly still in a ${background}, wearing the outfit. The model looks directly at the camera, smiling and presenting the outfit with open body language. No hanger, just the model wearing the clothes. High quality, 4k. Dialogue: [Insert Dialogue Here]`;
                 }
                break;
            case 'Dáng đứng':
            default:
                poseSpecifics = `${subject} đang tạo dáng trong tư thế đứng một cách tự nhiên và phong cách`;
                break;
        }

        const wearingVerb = clothingType === 'Phụ kiện' ? 'đeo/sử dụng' : 'mặc';

        const textPart = {
            text: `Tạo một hình ảnh chân thực, chất lượng nhiếp ảnh chuyên nghiệp, độ phân giải 2K, ${ratioPhrase}. ${modelDescription} đang ${wearingVerb} ${clothingItem} từ hình ảnh được cung cấp. Quan trọng: Nếu hình ảnh sản phẩm gốc có viền đen ở trên hoặc dưới, hãy bỏ qua nó. Hình ảnh lấp đầy khung hình. ${subject} phải có ngoại hình tự nhiên, khuôn mặt vui tươi, mỉm cười. ${poseSpecifics} trong bối cảnh sau: "${background}". Ánh sáng trong ảnh phải đẹp và làm nổi bật cả ${subjectPronoun} lẫn trang phục. Hình ảnh cuối cùng phải có độ sắc nét cực cao, chi tiết.`,
        };


        const results: ModelResult[] = [];
        for (let i = 0; i < numberOfImages; i++) {
            const generatedImageBase64 = await callGeminiApiForImage(imagePart, textPart);

            let videoPrompt = undefined;
            if (videoPromptTemplate) {
                 videoPrompt = videoPromptTemplate;
            }

            results.push({
                imageUrl: `data:image/jpeg;base64,${generatedImageBase64}`,
                videoPrompt: videoPrompt
            });
        }

        return results;

    } catch (error) {
        console.error("Lỗi khi gọi Gemini API cho ảnh người mẫu:", error);
        throw new Error("AI không thể tạo ảnh người mẫu. Vui lòng thử lại.");
    }
};

export const generateLookbookVideoPrompt = async (base64Image: string, mimeType: string, options: LookbookOptions): Promise<string> => {
    try {
        const { clothingType, theme, pose, gender } = options;
        const clothingItem = getClothingPhrase(clothingType);

        // Xác định hành động trong video dựa trên dáng người mẫu
        let actionInstruction = "Describe a simple, elegant, and fluid action for the model that complements the outfit and theme.";

        if (pose === 'Dáng đứng') {
            if (gender === 'Nữ') {
                // Kịch bản riêng cho Nữ - Dáng đứng: Đứng yên, đung đưa, cười duyên, vuốt tóc, không zoom, cam tĩnh
                actionInstruction = "The model stands strictly in one place without walking. She gently sways her body to a rhythm, smiling charmingly directly at the lens. She gracefully touches her hair. The camera is completely static (tripod shot), NO zoom, NO camera movement, NO cuts.";
            } else {
                 // Kịch bản mặc định cho Nam hoặc các trường hợp khác
                 actionInstruction = "The model should be STANDING in place (not walking). The action involves the model striking a few subtle, elegant poses, shifting weight, placing hands on hips/pockets, or turning slightly to show off different angles of the outfit and highlight its beauty. The goal is to display the outfit through professional static posing.";
            }
        } else if (pose === 'Dáng đi') {
             actionInstruction = "The model should be WALKING confidently through the environment. Focus on how the fabric moves and flows with the model's steps.";
        }

        const imagePart = {
            inlineData: {
                data: base64Image,
                mimeType: mimeType,
            },
        };

        const textPart = {
            text: `Based on the provided image of a model wearing ${clothingItem} in the theme of "${theme}", create a concise video prompt in **English** for a text-to-video AI.

            **Crucial Requirements:**
            1.  **One-Shot:** The entire video must be a single, continuous shot with no cuts (a "one-shot" or "oner").
            2.  **Full Outfit Visibility:** The primary goal is to showcase the outfit. The model and their complete outfit **must become fully visible** and remain the focus. If the source image is a close-up or medium shot, the prompt should describe a camera movement (like a pull-back) that reveals the full look early in the shot.
            3.  **Grounded in Image:** The action, model's pose, and environment in the video should start from or be inspired by the provided image.
            4.  **Action:** ${actionInstruction}
            5.  **Output:** Provide ONLY the prompt text. Do not include labels, headings, or any other explanations.

            **Example:** "A continuous one-shot video. Starts with a medium shot of a model smiling, then the camera smoothly pulls back to reveal her full-length outfit as she [performs the specific action], highlighting the fabric and design. The full outfit remains in frame."

            Now, generate the prompt based on the user's image.`,
        };

        const response = await ai.models.generateContent({
            model: 'gemini-2.5-flash',
            contents: { parts: [imagePart, textPart] },
        });

        return response.text || "";

    } catch (error) {
        console.error("Lỗi khi gọi Gemini API để tạo prompt video lookbook:", error);
        throw new Error("AI không thể tạo prompt video. Vui lòng thử lại.");
    }
};


export const generateLookbookImages = async (base64Image: string, mimeType: string, options: LookbookOptions): Promise<LookbookResult[]> => {
    try {
        const { clothingType, gender, age, theme, additionalPrompt, numberOfImages, pose, aspectRatio } = options;

        const imagePart = {
            inlineData: {
                data: base64Image,
                mimeType: mimeType,
            },
        };

        const clothingItem = getClothingPhrase(clothingType);
        const ratioPhrase = getAspectRatioPhrase(aspectRatio);

        let modelDescription: string;
        const genderText = gender === 'Nam' ? 'nam' : 'nữ';
        if (age === '5-10') {
            const childGenderText = gender === 'Nam' ? 'bé trai' : 'bé gái';
            modelDescription = `Một ${childGenderText} người Việt Nam, đáng yêu, xinh xắn, trong độ tuổi từ 5 đến 10,`;
        } else {
            let modelSpecifics = "";
            if (gender === 'Nam') {
                modelSpecifics = "có làn da trắng sáng, đẹp trai, tươi tắn, trẻ trung, ";
            } else {
                 modelSpecifics = "có làn da trắng sáng, xinh gái, tươi tắn, trẻ trung, ";
            }
            modelDescription = `Một người mẫu ${genderText} người Việt Nam, ${modelSpecifics}trong độ tuổi ${age},`;
        }

        const textPartBase = `Tạo MỘT hình ảnh thời trang chuyên nghiệp đẳng cấp cao (High-end Fashion Photography), độ phân giải 4K, với ${ratioPhrase}.

            **Yêu cầu kỹ thuật nhiếp ảnh (QUAN TRỌNG):**
            1.  **Chất lượng hình ảnh:** Ảnh phải trông như được chụp bằng máy ảnh DSLR Full-frame chuyên nghiệp (như Sony Alpha a7R IV hoặc Canon EOS R5) với ống kính chân dung 85mm f/1.8.
            2.  **Ánh sáng:** Sử dụng ánh sáng tự nhiên, rực rỡ và trong trẻo (Bright, Airy, Natural Lighting). Ánh sáng phải làm nổi bật sản phẩm và người mẫu một cách mềm mại. Tuyệt đối tránh ánh sáng tối, u ám hoặc nhân tạo quá đà.
            3.  **Màu sắc:** Tông màu ảnh phải trắng sáng, thanh lịch và tự nhiên (Clean, Bright, Natural Tones). Cân bằng trắng hoàn hảo. Màu da (skin tone) của người mẫu phải hồng hào, tự nhiên và chân thực.
            4.  **Độ nét:** Độ sắc nét cực cao (Ultra-Sharp), hiển thị rõ chi tiết chất liệu vải và kết cấu da tự nhiên (Realistic Skin Texture). Không bị bệt màu hay nhiễu hạt (No noise, no artifacts).

            **Nội dung hình ảnh:**
            1.  **Sản phẩm:** ${modelDescription} đang mặc ${clothingItem} từ hình ảnh được cung cấp.
            2.  **Chủ đề:** "${theme}".
            3.  **Bối cảnh & Dáng:** Dáng '${pose}' nhưng tự nhiên. Bối cảnh phải có ánh sáng tốt, không gian thoáng đãng phù hợp với phong cách "trắng sáng tự nhiên".
            4.  **Gợi ý thêm:** ${additionalPrompt || "Không có"}

            Nếu hình ảnh sản phẩm gốc có viền đen, hãy bỏ qua và đảm bảo hình ảnh kết quả lấp đầy toàn bộ khung hình. Người mẫu phải có biểu cảm vui tươi, tự tin, thần thái cuốn hút.`;

        const results: LookbookResult[] = [];

        for (let i = 0; i < numberOfImages; i++) {
            // Step 1: Generate the image with instructions for variety
             const textPartForImage = { text: `${textPartBase}\n\n**Chỉ dẫn tạo sự đa dạng:** Đây là ảnh thứ ${i + 1} trên tổng số ${numberOfImages}. Hãy thay đổi nhẹ về góc chụp (cận cảnh, trung cảnh, toàn cảnh) hoặc hướng nhìn/tương tác của người mẫu để tạo sự phong phú cho lookbook, nhưng vẫn giữ thống nhất về tone màu và phong cách.` };
            const generatedImageBase64 = await callGeminiApiForImage(imagePart, textPartForImage);

            // Step 2: Generate the video prompt for the newly created image
            const videoPrompt = await generateLookbookVideoPrompt(generatedImageBase64, 'image/jpeg', options);

            results.push({
                imageUrl: `data:image/jpeg;base64,${generatedImageBase64}`,
                videoPrompt: videoPrompt.trim()
            });
        }

        return results;

    } catch (error) {
        console.error("Lỗi khi gọi Gemini API cho lookbook:", error);
        throw new Error("AI không thể tạo lookbook. Vui lòng thử lại.");
    }
};

export const enhanceImage = async (base64Image: string, mimeType: string, options: EnhanceOptions): Promise<string> => {
    try {
        const { upscale, sharpen, removeWatermark } = options;

        const imagePart = {
            inlineData: {
                data: base64Image,
                mimeType: mimeType,
            },
        };

        let mainTask: string;
        const enhancementDetails: string[] = [];

        if (removeWatermark) {
            mainTask = "Nhiệm vụ của bạn là một chuyên gia phục chế ảnh. Từ hình ảnh được cung cấp, hãy xóa bỏ hoàn toàn mọi dấu watermark, logo, hoặc văn bản phủ lên. Hãy tái tạo lại các vùng bị che khuất một cách chân thực và liền mạch nhất có thể, sao cho không ai nhận ra đã từng có chi tiết đó ở đó. Giữ nguyên chất lượng, màu sắc, và các chi tiết gốc của hình ảnh.";
        } else {
            mainTask = "Từ hình ảnh được cung cấp, hãy tạo ra một phiên bản mới đã được cải thiện, giữ nguyên bố cục và chủ thể của ảnh gốc.";
        }

        if (upscale) {
            enhancementDetails.push("tăng đáng kể độ phân giải và chất lượng tổng thể");
        }
        if (sharpen) {
            enhancementDetails.push("làm nét các chi tiết");
        }

        let fullPrompt = mainTask;

        if (enhancementDetails.length > 0) {
            if (removeWatermark) {
                fullPrompt += ` Đồng thời, áp dụng các cải tiến sau: ${enhancementDetails.join(' và ')}.`;
            } else {
                fullPrompt += ` Áp dụng các cải tiến sau: ${enhancementDetails.join(' và ')}.`;
            }
        }

        fullPrompt += " Hình ảnh cuối cùng phải trông tự nhiên và có chất lượng chuyên nghiệp.";

        const textPart = {
            text: fullPrompt,
        };

        return await callGeminiApiForImage(imagePart, textPart);

    } catch (error) {
        console.error("Lỗi khi gọi Gemini API để nâng cấp ảnh:", error);
        throw new Error("AI không thể nâng cấp ảnh. Vui lòng thử lại.");
    }
};

