export const generateReviewScript = async (options: ReviewScriptOptions): Promise<ReviewScriptResult> => {
    try {
        const { productInfo, scriptType, accent } = options;

        // Cấu hình phong cách ngôn ngữ dựa trên vùng miền
        let accentInstruction = "";
        if (accent === 'Miền Bắc') {
            accentInstruction = `Sử dụng từ ngữ và giọng văn đặc trưng của người miền Bắc (ví dụ: "xịn sò", "cực phẩm", "nhé", "thế này", "ưng ý").`;
        } else {
            accentInstruction = `Sử dụng từ ngữ và giọng văn đặc trưng của người miền Nam (ví dụ: "nhức nách", "cưng xỉu", "nhen", "bao đẹp", "nghen").`;
        }

        const textPart = {
            text: `Hãy đóng vai một người sáng tạo nội dung TikTok/Reels chuyên nghiệp. Viết một kịch bản video ngắn 3 câu để review sản phẩm thời trang, dựa trên thông tin sau:

            - **Sản phẩm:** "${productInfo}"
            - **Loại nội dung:** ${scriptType}
            - **Phong cách giọng:** ${accent}

            **YÊU CẦU QUAN TRỌNG:**
            1.  **Cấu trúc 3 câu (BẮT BUỘC):**
                -   **Câu 1 (Hook):** Gây sự chú ý ngay lập tức, nêu vấn đề hoặc tạo sự tò mò. Ngắn gọn, đọc trong khoảng 10 giây.
                -   **Câu 2 (Body):** Review chân thực về chất liệu, form dáng hoặc trải nghiệm khi mặc. Khen ngợi một cách tự nhiên. Ngắn gọn, đọc trong khoảng 10 giây.
                -   **Câu 3 (CTA):** Kêu gọi hành động mua hàng, nhấn mạnh sự khẩn cấp hoặc ưu đãi. Ngắn gọn, đọc trong khoảng 10 giây.
            2.  **Ngôn ngữ:** ${accentInstruction} Lời thoại phải cực kỳ tự nhiên, giống như văn nói hàng ngày, không sáo rỗng.
            3.  **Định dạng đầu ra:** Trả về kết quả dưới dạng **JSON** thuần túy (không có Markdown \`\`\`json ... \`\`\`) với các trường sau:
                {
                    "hook": "Nội dung câu 1",
                    "body": "Nội dung câu 2",
                    "cta": "Nội dung câu 3"
                }
            `,
        };

        const response = await ai.models.generateContent({
            model: 'gemini-2.5-flash',
            contents: { parts: [textPart] },
            config: {
                responseMimeType: "application/json"
            }
        });

        const jsonString = response.text ? response.text.trim() : "";
        // Remove markdown code block if present (safety check)
        const cleanJson = jsonString.replace(/^```json\n|```$/g, '');

        return JSON.parse(cleanJson) as ReviewScriptResult;

    } catch (error) {
        console.error("Lỗi khi gọi Gemini API để tạo kịch bản review:", error);
        throw new Error("AI không thể tạo kịch bản. Vui lòng thử lại.");
    }
};

