import React, { useState, useCallback, useRef } from 'react';
import { generateStyledImage, generateModelImage, ModelPose, AspectRatio, generateBackgroundSuggestion, ProductDisplayMode } from './services/geminiService';
import { UploadIcon, SparklesIcon, LoadingSpinner, ErrorIcon, HangerIcon, UserIcon, ArrowLeftIcon, DownloadIcon, XIcon, RefreshIcon, WandIcon, ClipboardIcon, ClipboardCheckIcon } from './components/Icons';

type AppState = 'IDLE' | 'PROCESSING' | 'SUCCESS' | 'ERROR';
type ClothingType = 'Áo' | 'Quần' | 'Cả bộ' | 'Váy' | 'Phụ kiện';
type FeatureMode = 'product' | 'model';
type Gender = 'Nam' | 'Nữ';

interface ResultItem {
    url: string;
    videoPrompt?: string;
}

interface ProductStudioProps {
  onGoBack: () => void;
  onEnhanceImage: (imageUrl: string) => void;
}

const ProductStudio: React.FC<ProductStudioProps> = ({ onGoBack, onEnhanceImage }) => {
  // Core state
  const [originalImageFile, setOriginalImageFile] = useState<File | null>(null);
  const [originalImageUrl, setOriginalImageUrl] = useState<string | null>(null);
  const [generatedResults, setGeneratedResults] = useState<ResultItem[]>([]);
  const [appState, setAppState] = useState<AppState>('IDLE');
  const [error, setError] = useState<string | null>(null);

  // Feature selection state
  const [featureMode, setFeatureMode] = useState<FeatureMode | null>(null);
  const [clothingType, setClothingType] = useState<ClothingType | null>(null);
  const [aspectRatio, setAspectRatio] = useState<AspectRatio>('9:16');
  const [productDisplayMode, setProductDisplayMode] = useState<ProductDisplayMode>('hanger');

  // Model-specific state
  const [gender, setGender] = useState<Gender>('Nữ');
  const [age, setAge] = useState<string>('18-25');
  const [background, setBackground] = useState<string>('');
  const [numberOfImages, setNumberOfImages] = useState<number>(1);
  const [modelPose, setModelPose] = useState<ModelPose>('Dáng đứng');
  const [isGeneratingBackground, setIsGeneratingBackground] = useState<boolean>(false);
  const [copiedPromptIndex, setCopiedPromptIndex] = useState<number | null>(null);

  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFileChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (file) {
      if (!file.type.startsWith('image/')) {
        setError('Vui lòng chọn một tệp hình ảnh.');
        setAppState('ERROR');
        return;
      }
      // Reset only results, not settings
      setGeneratedResults([]);
      setError(null);
      setAppState('IDLE');

      setOriginalImageFile(file);
      setOriginalImageUrl(URL.createObjectURL(file));
    }
  };

  const handleRemoveImage = (e: React.MouseEvent) => {
    e.stopPropagation();
    // Only reset image and results, keep all other settings
    setOriginalImageFile(null);
    setOriginalImageUrl(null);
    setGeneratedResults([]);
    setError(null);
    setAppState('IDLE');
    if (fileInputRef.current) {
        fileInputRef.current.value = "";
    }
  };

  const handleGenerateBackground = async () => {
    if (!originalImageFile || !clothingType) return;

    setIsGeneratingBackground(true);
    setError(null);

    const reader = new FileReader();
    reader.readAsDataURL(originalImageFile);
    reader.onloadend = async () => {
        try {
            const base64String = (reader.result as string).split(',')[1];
            if (!base64String) {
              throw new Error('Không thể chuyển đổi hình ảnh.');
            }
            const suggestion = await generateBackgroundSuggestion(base64String, originalImageFile.type, clothingType);
            setBackground(suggestion.trim().replace(/^"|"$/g, '')); // Remove quotes if API returns them
        } catch (err: any) {
          console.error(err);
          setError(err.message || 'Không thể tạo bối cảnh. Vui lòng thử lại.');
          setAppState('ERROR');
        } finally {
            setIsGeneratingBackground(false);
        }
    };
    reader.onerror = () => {
       setError('Lỗi khi đọc tệp hình ảnh.');
       setAppState('ERROR');
       setIsGeneratingBackground(false);
    }
  };

  const handleGenerateClick = useCallback(async () => {
    if (!originalImageFile || !clothingType || !featureMode) return;

    if(featureMode === 'model' && !background.trim()){
        setError('Vui lòng nhập mô tả bối cảnh.');
        setAppState('ERROR');
        return;
    }

    setAppState('PROCESSING');
    setError(null);
    setGeneratedResults([]);


    try {
      const reader = new FileReader();
      reader.readAsDataURL(originalImageFile);
      reader.onloadend = async () => {
        const base64String = (reader.result as string).split(',')[1];
        if (!base64String) {
          throw new Error('Không thể chuyển đổi hình ảnh.');
        }

        if (featureMode === 'product') {
            const generatedImage = await generateStyledImage(base64String, originalImageFile.type, clothingType, aspectRatio, productDisplayMode);
            setGeneratedResults([{ url: `data:image/jpeg;base64,${generatedImage}` }]);
        } else { // featureMode === 'model'
            const generatedImages = await generateModelImage(base64String, originalImageFile.type, {
                clothingType,
                gender,
                age,
                background,
                numberOfImages,
                pose: modelPose,
                aspectRatio,
            });
            setGeneratedResults(generatedImages.map(item => ({
                url: item.imageUrl,
                videoPrompt: item.videoPrompt
            })));
        }

        setAppState('SUCCESS');
      };
      reader.onerror = () => {
         throw new Error('Lỗi khi đọc tệp hình ảnh.');
      }
    } catch (err: any) {
      console.error(err);
      setError(err.message || 'Đã xảy ra lỗi không mong muốn. Vui lòng thử lại.');
      setAppState('ERROR');
    }
  }, [originalImageFile, featureMode, clothingType, gender, age, background, numberOfImages, modelPose, aspectRatio, productDisplayMode]);

  const triggerFileInput = () => {
    fileInputRef.current?.click();
  };

  const resetState = () => {
    setOriginalImageFile(null);
    setOriginalImageUrl(null);
    setGeneratedResults([]);
    setError(null);
    setClothingType(null);
    setFeatureMode(null);
    setAspectRatio('9:16');
    setGender('Nữ');
    setAge('18-25');
    setBackground('');
    setNumberOfImages(1);
    setModelPose('Dáng đứng');
    setProductDisplayMode('hanger');
    setIsGeneratingBackground(false);
    setAppState('IDLE');
    if(fileInputRef.current) {
        fileInputRef.current.value = "";
    }
  };

  const handleCopyToClipboard = (textToCopy: string, index: number) => {
    navigator.clipboard.writeText(textToCopy);
    setCopiedPromptIndex(index);
    setTimeout(() => setCopiedPromptIndex(null), 2000);
  };

  const isGenerateButtonDisabled = () => {
    if (appState === 'PROCESSING' || !originalImageFile || !featureMode || !clothingType) {
        return true;
    }
    if (featureMode === 'model' && !background.trim()) {
        return true;
    }
    return false;
  }

  return (
    <div className="bg-gray-50 min-h-screen text-gray-800 font-sans">
      <div className="container mx-auto px-4 py-8">
        <header className="text-center mb-8 md:mb-12 relative">
            <button onClick={onGoBack} className="absolute left-0 top-1/2 -translate-y-1/2 flex items-center text-gray-500 hover:text-indigo-600 transition-colors group">
                <ArrowLeftIcon className="w-6 h-6 mr-2 transform group-hover:-translate-x-1 transition-transform"/>
                <span className="font-semibold">Trang chủ</span>
            </button>
          <h1 className="text-4xl md:text-5xl font-bold text-gray-900 tracking-tight">
            Studio Sản phẩm AI
          </h1>
          <p className="mt-4 text-lg text-gray-600 max-w-2xl mx-auto">
            Biến hình ảnh trang phục của bạn thành ảnh sản phẩm chuyên nghiệp hoặc ảnh người mẫu ảo.
          </p>
        </header>

        <main className="bg-white rounded-2xl shadow-xl p-6 md:p-10">
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 lg:gap-12 items-start">
            {/* Input Section */}
            <div className="flex flex-col items-center justify-center space-y-6">
              <h2 className="text-2xl font-semibold text-gray-700">1. Tải lên & Tùy chỉnh</h2>
              <input
                type="file"
                ref={fileInputRef}
                onChange={handleFileChange}
                accept="image/*"
                className="hidden"
              />
              <div
                onClick={!originalImageUrl ? triggerFileInput : undefined}
                className="relative w-full max-w-sm mx-auto aspect-square border-2 border-dashed border-gray-300 rounded-lg flex flex-col justify-center items-center text-center cursor-pointer hover:border-indigo-500 hover:bg-indigo-50 transition-colors duration-300"
              >
                {originalImageUrl ? (
                  <>
                    <img src={originalImageUrl} alt="Original Upload" className="max-h-full max-w-full object-contain rounded-md p-2" />
                    <button
                      onClick={handleRemoveImage}
                      className="absolute top-2 right-2 bg-gray-900/50 text-white rounded-full p-1.5 hover:bg-gray-900/75 transition-colors z-10"
                      aria-label="Xóa ảnh"
                    >
                      <XIcon className="w-4 h-4" />
                    </button>
                  </>
                ) : (
                  <>
                    <UploadIcon className="w-12 h-12 text-gray-400" />
                    <p className="mt-2 text-gray-500">Nhấp hoặc kéo và thả ảnh vào đây</p>
                    <p className="text-xs text-gray-400 mt-1">PNG, JPG, WEBP</p>
                  </>
                )}
              </div>

            <div className={`w-full max-w-md mx-auto space-y-6 transition-opacity duration-300 ${!originalImageFile ? 'opacity-50 pointer-events-none' : ''}`}>
                {/* Feature Mode Selection */}
                <div>
                    <p className="font-semibold text-center text-gray-600 mb-3">Chọn chế độ tạo ảnh:</p>
                    <div className="grid grid-cols-2 gap-4">
                        <button onClick={() => setFeatureMode('product')} className={`flex flex-col items-center justify-center p-4 rounded-lg border-2 transition-all duration-200 ${featureMode === 'product' ? 'border-indigo-500 bg-indigo-50 text-indigo-700' : 'border-gray-300 bg-gray-50 text-gray-600 hover:border-gray-400'}`}>
                            <HangerIcon className="w-8 h-8 mb-2"/>
                            <span className="font-semibold">Ảnh Sản Phẩm</span>
                        </button>
                         <button onClick={() => setFeatureMode('model')} className={`flex flex-col items-center justify-center p-4 rounded-lg border-2 transition-all duration-200 ${featureMode === 'model' ? 'border-indigo-500 bg-indigo-50 text-indigo-700' : 'border-gray-300 bg-gray-50 text-gray-600 hover:border-gray-400'}`}>
                            <UserIcon className="w-8 h-8 mb-2"/>
                            <span className="font-semibold">Người Mẫu Ảo</span>
                        </button>
                    </div>
                </div>

                {featureMode && (
                    <>
                        <div>
                            <p className="font-semibold text-center text-gray-600 mb-3">Loại sản phẩm:</p>
                            <div className="grid grid-cols-2 sm:grid-cols-3 gap-3">
                                {(['Áo', 'Quần', 'Cả bộ', 'Váy', 'Phụ kiện'] as ClothingType[]).map((type) => (
                                    <button
                                        key={type}
                                        onClick={() => setClothingType(type)}
                                        className={`px-4 py-2 rounded-lg text-sm font-semibold transition-all duration-200 transform focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-indigo-500 ${
                                            clothingType === type
                                                ? 'bg-indigo-600 text-white shadow-md scale-105'
                                                : 'bg-gray-200 text-gray-700 hover:bg-gray-300'
                                        }`}
                                    >
                                        {type}
                                    </button>
                                ))}
                            </div>
                        </div>
                        <div>
                            <p className="font-semibold text-center text-gray-600 my-3">Tỉ lệ ảnh:</p>
                            <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
                                {(['9:16', '1:1', '4:5', '16:9'] as AspectRatio[]).map((ratio) => (
                                    <button
                                        key={ratio}
                                        onClick={() => setAspectRatio(ratio)}
                                        className={`px-4 py-2 rounded-lg text-sm font-semibold transition-all duration-200 transform focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-indigo-500 ${
                                            aspectRatio === ratio
                                                ? 'bg-indigo-600 text-white shadow-md scale-105'
                                                : 'bg-gray-200 text-gray-700 hover:bg-gray-300'
                                        }`}
                                    >
                                        {ratio}
                                    </button>
                                ))}
                            </div>
                        </div>
                    </>
                )}

                {featureMode === 'product' && (
                     <div>
                        <p className="font-semibold text-center text-gray-600 my-3">Cách trình bày:</p>
                        <div className="grid grid-cols-2 gap-3">
                            <button
                                onClick={() => setProductDisplayMode('hanger')}
                                className={`px-4 py-2 rounded-lg text-sm font-semibold transition-all duration-200 transform focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-indigo-500 ${
                                    productDisplayMode === 'hanger'
                                        ? 'bg-indigo-600 text-white shadow-md scale-105'
                                        : 'bg-gray-200 text-gray-700 hover:bg-gray-300'
                                }`}
                            >
                                Treo móc / Kệ
                            </button>
                             <button
                                onClick={() => setProductDisplayMode('flatlay')}
                                className={`px-4 py-2 rounded-lg text-sm font-semibold transition-all duration-200 transform focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-indigo-500 ${
                                    productDisplayMode === 'flatlay'
                                        ? 'bg-indigo-600 text-white shadow-md scale-105'
                                        : 'bg-gray-200 text-gray-700 hover:bg-gray-300'
                                }`}
                            >
                                Trải sàn (Thảm lông)
                            </button>
                        </div>
                    </div>
                )}

                {featureMode === 'model' && (
                    <div className="space-y-4 p-4 bg-gray-100 rounded-lg">
                         <p className="font-semibold text-center text-gray-600 mb-4">Tùy chọn người mẫu:</p>

                         <div>
                            <label className="block text-sm font-medium text-gray-700 mb-1">Dáng người mẫu</label>
                            <div className="grid grid-cols-2 gap-2">
                                <button onClick={() => setModelPose('Dáng đứng')} className={`py-2 px-3 rounded-md font-semibold text-sm transition-all ${modelPose === 'Dáng đứng' ? 'bg-indigo-600 text-white shadow' : 'bg-white text-gray-700 hover:bg-gray-200 border border-gray-300'}`}>
                                    Dáng đứng
                                </button>
                                <button onClick={() => setModelPose('Dáng đi')} className={`py-2 px-3 rounded-md font-semibold text-sm transition-all ${modelPose === 'Dáng đi' ? 'bg-indigo-600 text-white shadow' : 'bg-white text-gray-700 hover:bg-gray-200 border border-gray-300'}`}>
                                    Dáng đi
                                </button>
                                <button onClick={() => setModelPose('Giới thiệu (Cầm móc)')} className={`py-2 px-3 rounded-md font-semibold text-sm transition-all ${modelPose === 'Giới thiệu (Cầm móc)' ? 'bg-indigo-600 text-white shadow' : 'bg-white text-gray-700 hover:bg-gray-200 border border-gray-300'}`}>
                                    Giới thiệu (Cầm đồ)
                                </button>
                                <button onClick={() => setModelPose('Giới thiệu (Chỉ mặc)')} className={`py-2 px-3 rounded-md font-semibold text-sm transition-all ${modelPose === 'Giới thiệu (Chỉ mặc)' ? 'bg-indigo-600 text-white shadow' : 'bg-white text-gray-700 hover:bg-gray-200 border border-gray-300'}`}>
                                    Giới thiệu (Chỉ mặc)
                                </button>
                            </div>
                         </div>

                         <div className="grid grid-cols-2 gap-4">
                            <div>
                                <label className="block text-sm font-medium text-gray-700 mb-1">Giới tính</label>
                                <select value={gender} onChange={(e) => setGender(e.target.value as Gender)} className="w-full p-2 border border-gray-300 rounded-md focus:ring-indigo-500 focus:border-indigo-500">
                                    <option value="Nữ">Nữ</option>
                                    <option value="Nam">Nam</option>
                                </select>
                            </div>
                            <div>
                                <label className="block text-sm font-medium text-gray-700 mb-1">Độ tuổi</label>
                                <select value={age} onChange={(e) => setAge(e.target.value)} className="w-full p-2 border border-gray-300 rounded-md focus:ring-indigo-500 focus:border-indigo-500">
                                    <option value="5-10">5-10 (Bé)</option>
                                    <option value="18-25">18-25</option>
                                    <option value="26-35">26-35</option>
                                    <option value="36-45">36-45</option>
                                </select>
                            </div>
                         </div>
                         <div>
                            <label className="block text-sm font-medium text-gray-700 mb-1">Số lượng ảnh (1-9)</label>
                            <select value={numberOfImages} onChange={(e) => setNumberOfImages(Number(e.target.value))} className="w-full p-2 border border-gray-300 rounded-md focus:ring-indigo-500 focus:border-indigo-500">
                                {[...Array(9)].map((_, i) => (
                                    <option key={i + 1} value={i + 1}>{i + 1}</option>
                                ))}
                            </select>
                         </div>
                         <div>
                             <label htmlFor="background-input" className="block text-sm font-medium text-gray-700 mb-1">Bối cảnh</label>
                             <input 
                                id="background-input"
                                type="text"
                                value={background}
                                onChange={(e) => setBackground(e.target.value)}
                                placeholder="VD: Đường phố Sài Gòn ban đêm"
                                className="w-full p-2 border border-gray-300 rounded-md focus:ring-indigo-500 focus:border-indigo-500"
                            />
                            <div className="mt-2">
                                {!background.trim() && clothingType && (
                                    <button
                                        onClick={handleGenerateBackground}
                                        disabled={isGeneratingBackground}
                                        className="w-full flex items-center justify-center px-4 py-2 text-sm font-semibold text-indigo-700 bg-indigo-100 rounded-md hover:bg-indigo-200 disabled:bg-indigo-50 disabled:cursor-wait transition-colors"
                                    >
                                        {isGeneratingBackground ? (
                                            <>
                                                <LoadingSpinner className="w-5 h-5 mr-2" />
                                                Đang tìm ý tưởng...
                                            </>
                                        ) : (
                                            <>
                                                <SparklesIcon className="w-5 h-5 mr-2" />
                                                Tạo bối cảnh tự động
                                            </>
                                        )}
                                    </button>
                                )}
                                {background.trim() && clothingType && (
                                     <button
                                        onClick={handleGenerateBackground}
                                        disabled={isGeneratingBackground}
                                        className="w-full flex items-center justify-center px-4 py-2 text-sm font-semibold text-indigo-700 bg-indigo-100 rounded-md hover:bg-indigo-200 disabled:bg-indigo-50 disabled:cursor-wait transition-colors"
                                     >
                                        {isGeneratingBackground ? (
                                            <>
                                                <LoadingSpinner className="w-5 h-5 mr-2" />
                                                Đang đổi...
                                            </>
                                        ) : (
                                            <>
                                                <RefreshIcon className="w-5 h-5 mr-2" />
                                                Thay đổi bối cảnh khác
                                            </>
                                        )}
                                     </button>
                                )}
                            </div>
                         </div>
                    </div>
                )}
            </div>

              <div className="w-full flex justify-center space-x-4 pt-4">
                  <button
                    onClick={handleGenerateClick}
                    disabled={isGenerateButtonDisabled()}
                    className="flex items-center justify-center w-full max-w-xs px-6 py-3 bg-indigo-600 text-white font-semibold rounded-lg shadow-md hover:bg-indigo-700 disabled:bg-indigo-300 disabled:cursor-not-allowed focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-indigo-500 transition-all duration-300 transform hover:scale-105"
                  >
                    {appState === 'PROCESSING' ? (
                      <>
                        <LoadingSpinner className="w-5 h-5 mr-3" />
                        Đang xử lý...
                      </>
                    ) : (
                      <>
                        <SparklesIcon className="w-5 h-5 mr-3" />
                        Tạo ảnh
                      </>
                    )}
                  </button>
                  {originalImageFile && (
                    <button
                        onClick={resetState}
                        className="px-6 py-3 bg-gray-200 text-gray-700 font-semibold rounded-lg hover:bg-gray-300 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-gray-400 transition-colors"
                    >
                        Làm lại
                    </button>
                  )}
              </div>
            </div>

            {/* Output Section */}
            <div className="flex flex-col items-center justify-center space-y-6">
                 <h2 className="text-2xl font-semibold text-gray-700">2. Kết quả từ AI</h2>
                <div className="w-full max-w-sm mx-auto">
                    {appState === 'PROCESSING' && (
                        <div className="aspect-[9/16] bg-gray-100 rounded-lg flex flex-col justify-center items-center text-center text-gray-500">
                           <LoadingSpinner className="w-12 h-12 mx-auto" />
                           <p className="mt-4 animate-pulse">AI đang sáng tạo...</p>
                        </div>
                    )}
                    {(appState === 'ERROR' && error) && (
                        <div className="aspect-[9/16] bg-gray-100 rounded-lg flex flex-col justify-center items-center text-center text-red-500 p-4">
                            <ErrorIcon className="w-12 h-12 mx-auto"/>
                            <p className="mt-4 font-semibold">Lỗi!</p>
                            <p className="text-sm">{error}</p>
                        </div>
                    )}
                    {appState === 'SUCCESS' && generatedResults.length > 0 && (
                        <div className={`grid gap-4 ${generatedResults.length > 1 ? 'grid-cols-2' : 'grid-cols-1'}`}>
                            {generatedResults.map((item, index) => (
                                <div key={index} className="flex flex-col gap-3">
                                    <div className="relative group rounded-lg overflow-hidden shadow-md">
                                        <img src={item.url} alt={`AI Generated ${index + 1}`} className="w-full h-auto block" />
                                        <a
                                            href={item.url}
                                            download={`ai-generated-image-${index + 1}.jpg`}
                                            className="absolute bottom-2 right-2 bg-black/50 text-white p-2 rounded-full hover:bg-black/80 transition-colors opacity-0 group-hover:opacity-100"
                                            aria-label="Tải ảnh xuống"
                                        >
                                            <DownloadIcon className="w-5 h-5"/>
                                        </a>
                                    </div>
                                    {featureMode === 'product' && (
                                        <button
                                            onClick={() => onEnhanceImage(item.url)}
                                            className="flex items-center justify-center w-full px-4 py-2 bg-sky-100 text-sky-700 font-semibold rounded-lg hover:bg-sky-200 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-sky-500 transition-all duration-300"
                                        >
                                            <WandIcon className="w-5 h-5 mr-2" />
                                            Nâng cấp ảnh này
                                        </button>
                                    )}
                                    {item.videoPrompt && (
                                         <div className="bg-gray-100 p-3 rounded-lg">
                                            <p className="text-xs text-gray-500 font-semibold mb-2">GỢI Ý VIDEO:</p>
                                            <p className="text-sm text-gray-800 leading-relaxed max-h-32 overflow-y-auto">{item.videoPrompt}</p>
                                            <button 
                                                onClick={() => handleCopyToClipboard(item.videoPrompt!, index)}
                                                className="mt-3 w-full flex items-center justify-center px-3 py-2 text-sm font-semibold text-indigo-700 bg-indigo-100 rounded-md hover:bg-indigo-200 transition-colors"
                                            >
                                                {copiedPromptIndex === index ? (
                                                    <>
                                                        <ClipboardCheckIcon className="w-4 h-4 mr-2 text-green-600"/> Đã sao chép!
                                                    </>
                                                ) : (
                                                    <>
                                                        <ClipboardIcon className="w-4 h-4 mr-2"/> Sao chép
                                                    </>
                                                )}
                                            </button>
                                        </div>
                                    )}
                                </div>
                            ))}
                        </div>
                    )}
                    {(appState === 'IDLE' || (appState === 'SUCCESS' && generatedResults.length === 0)) && (
                       <div className="aspect-[9/16] bg-gray-100 rounded-lg flex flex-col justify-center items-center text-center text-gray-400 p-4">
                          <p>Hình ảnh được tạo bởi AI sẽ xuất hiện ở đây.</p>
                       </div>
                    )}
                </div>
            </div>
          </div>
        </main>
      </div>
    </div>
  );
};

