        let modelDescription: string;
        if (age === '5-10') {
            const childGenderText = gender === 'Nam' ? 'bé trai' : 'bé gái';
            modelDescription = `${childGenderText} khoảng 5-10 tuổi`;
        } else {
             modelDescription = `người mẫu ${gender === 'Nam' ? 'nam' : 'nữ'} trẻ, độ tuổi ${age}`;
        }

        const results: ModelResult[] = [];
        for (let i = 0; i < numberOfImages; i++) {
             const textPart = {
                text: `Hãy tạo một hình ảnh thời trang chuyên nghiệp.
                Sản phẩm: ${clothingItem} trong hình ảnh đính kèm.
                Người mẫu: Một ${modelDescription}.
                Trang phục: Người mẫu đang mặc ${clothingItem} này. Đảm bảo giữ nguyên màu sắc, họa tiết và kiểu dáng của sản phẩm gốc.
                Tư thế: ${pose}.
                Bối cảnh: ${background}.
                Tỉ lệ: ${ratioPhrase}.
                Chất lượng: Ảnh chụp studio chất lượng cao, độ phân giải 2K, ánh sáng đẹp.
                Lưu ý: Khuôn mặt người mẫu phải tự nhiên, đẹp.
                ${i > 0 ? `Biến thể thứ ${i+1}: Thay đổi nhẹ về góc mặt hoặc ánh sáng.` : ''}
                `
            };

            const generatedImage = await callGeminiApiForImage(imagePart, textPart);
            const videoPrompt = await generateStaticIntroVideoPrompt(clothingType, background);

            results.push({
                imageUrl: `data:image/jpeg;base64,${generatedImage}`,
                videoPrompt
            });
        }
        return results;

    } catch (error) {
        console.error("Lỗi khi gọi Gemini API cho ảnh người mẫu:", error);
        throw new Error("AI không thể tạo ảnh người mẫu. Vui lòng thử lại.");
    }
};

