export const enhanceImage = async (base64Image: string, mimeType: string, options: EnhanceOptions): Promise<string> => {
    try {
        const instructions = [];
        if (options.upscale) instructions.push("tăng độ phân giải lên 4K, chi tiết cực cao");
        if (options.sharpen) instructions.push("làm nét hình ảnh, giảm nhiễu, làm rõ các chi tiết bị mờ");
        if (options.removeWatermark) instructions.push("loại bỏ các chữ, logo hoặc watermark mờ trên ảnh nếu có");

        const prompt = `Đây là hình ảnh gốc. Hãy tạo ra phiên bản chất lượng cao hơn (Remastered) của hình ảnh này.
        Yêu cầu cụ thể: ${instructions.join(', ')}.
        Quan trọng: Giữ nguyên nội dung chính, bố cục, màu sắc và ánh sáng của ảnh gốc. Chỉ cải thiện chất lượng kỹ thuật. Ảnh kết quả phải trông sắc nét và chuyên nghiệp.`;

        const imagePart = { inlineData: { data: base64Image, mimeType: mimeType } };
        const textPart = { text: prompt };

        return await callGeminiApiForImage(imagePart, textPart);
    } catch (error) {
         throw new Error("Không thể nâng cấp ảnh.");
    }
}

