export const generateReviewScript = async (options: ReviewScriptOptions): Promise<ReviewScriptResult> => {
    try {
        const prompt = `
            Bạn là một KOC/Reviewer nổi tiếng trên TikTok. Hãy viết kịch bản video ngắn (30s) về sản phẩm: ${options.productInfo}.
            Loại nội dung: ${options.scriptType}.
            Giọng điệu/Từ ngữ: ${options.accent === 'Miền Bắc' ? 'Chuẩn miền Bắc, gãy gọn' : 'Chuẩn miền Nam, thân thiện, dễ thương'}.

            Yêu cầu output JSON (không markdown):
            {
                "hook": "Câu mở đầu (Hook) cực cuốn trong 3-5 giây đầu",
                "body": "Phần thân bài review chi tiết, nêu bật USP (15-20s)",
                "cta": "Lời kêu gọi hành động (CTA) dứt khoát (5s)"
            }
        `;

        const response = await ai.models.generateContent({
            model: 'gemini-2.5-flash',
            contents: prompt,
            config: {
                responseMimeType: "application/json",
                responseSchema: {
                    type: Type.OBJECT,
                    properties: {
                        hook: { type: Type.STRING },
                        body: { type: Type.STRING },
                        cta: { type: Type.STRING }
                    },
                    required: ["hook", "body", "cta"]
                }
            }
        });

        if (response.text) {
             return JSON.parse(response.text) as ReviewScriptResult;
        }
        throw new Error("Empty response");
    } catch (e) {
        console.error(e);
        throw new Error("Không thể tạo kịch bản review.");
    }
}

export const generateLookbookImages = async (base64Image: string, mimeType: string, options: LookbookOptions): Promise<LookbookResult[]> => {
    try {
        const results: LookbookResult[] = [];
        const { clothingType, numberOfImages, theme, gender, age, pose, additionalPrompt } = options;

        const imagePart = { inlineData: { data: base64Image, mimeType: mimeType } };
        const clothingItem = getClothingPhrase(clothingType);

        for(let i=0; i<numberOfImages; i++) {
            const prompt = `Tạo ảnh lookbook thời trang.
            Sản phẩm chính: ${clothingItem} (như trong ảnh đính kèm).
            Chủ đề bộ ảnh: ${theme}.
            Người mẫu: ${gender === 'Nam' ? 'Nam' : 'Nữ'}, độ tuổi ${age}.
            Tạo dáng: ${pose}.
            Chi tiết bổ sung: ${additionalPrompt || 'Không có'}.
            Yêu cầu: Ảnh toàn thân hoặc 3/4, thấy rõ sản phẩm, background phù hợp với chủ đề. Độ phân giải 2K, phong cách tạp chí thời trang.
            ${i > 0 ? `Biến thể ${i+1}: Thay đổi góc máy hoặc hướng nhìn của người mẫu.` : ''}
            `;

            const generatedImage = await callGeminiApiForImage(imagePart, { text: prompt });
            const videoPrompt = await generateStaticIntroVideoPrompt(clothingType, theme);

            results.push({
                imageUrl: `data:image/jpeg;base64,${generatedImage}`,
                videoPrompt
            });
        }
        return results;
    } catch (e) {
        throw new Error("Không thể tạo lookbook.");
    }
};

