                responseModalities: [Modality.IMAGE],
            },
        });

    for (const part of response.candidates?.[0]?.content?.parts || []) {
        if (part.inlineData) {
            return part.inlineData.data;
        }
    }

    throw new Error("Không tìm thấy dữ liệu hình ảnh trong phản hồi của AI.");
}


export const generateStyledImage = async (base64Image: string, mimeType: string, clothingType: ClothingType, aspectRatio: AspectRatio, displayMode: ProductDisplayMode = 'hanger', numberOfImages: number = 1): Promise<string[]> => {
    try {
        const imagePart = {
            inlineData: {
                data: base64Image,
                mimeType: mimeType,
            },
        };

        const clothingItem = getClothingPhrase(clothingType);
        const ratioPhrase = getAspectRatioPhrase(aspectRatio);

        // Randomization arrays for Flatlay
        const rugShapes = ['hình trái tim (heart-shaped)', 'hình tròn (circular)', 'hình chữ nhật bo góc (soft rectangular)'];
        const pastelColors = ['màu hồng phấn pastel (pastel pink)', 'màu xanh mint pastel (mint green)', 'màu kem bơ (butter cream)', 'màu tím lavender nhạt (light lavender)'];
        const decorItems = ['một vài cành hoa nhỏ tinh tế (small flowers)', 'một chiếc túi xách mini thời trang (tiny handbag)', 'một chú gấu bông nhỏ xinh xắn (small teddy bear)'];

        const results: string[] = [];

        for (let i = 0; i < numberOfImages; i++) {
            let presentationInstruction = "";

            if (displayMode === 'flatlay') {
                // Pick random elements for variety in each iteration
                const shape = rugShapes[i % rugShapes.length]; // Rotate shapes or random
                const color = pastelColors[Math.floor(Math.random() * pastelColors.length)];
                const decor = decorItems[Math.floor(Math.random() * decorItems.length)];

                presentationInstruction = `Trong hình ảnh mới, ${clothingItem} này phải được đặt trải phẳng (flatlay) một cách tự nhiên và gọn gàng trên một tấm thảm lông (fur rug) ${shape}. Thảm lông có màu ${color} nhẹ nhàng và có họa tiết chìm tinh tế. Để bức ảnh thêm sinh động, hãy đặt thêm ${decor} ở góc thảm hoặc bên cạnh trang phục. QUAN TRỌNG: Các vật trang trí (hoa, túi, gấu bông) PHẢI nằm tách biệt, TUYỆT ĐỐI KHÔNG ĐƯỢC đè lên hoặc che khuất bất kỳ phần nào của trang phục. Góc chụp từ trên cao xuống (top-down view). Ánh sáng tự nhiên, dịu nhẹ, tạo cảm giác ấm cúng, dễ thương.`;
            } else {
                if (clothingType === 'Phụ kiện') {
                    presentationInstruction = `Trong hình ảnh mới, ${clothingItem} này phải được đặt một cách tinh tế và nghệ thuật trên một bề mặt bàn sang trọng (ví dụ: gỗ vân đẹp, đá cẩm thạch trắng, hoặc bục trưng bày sản phẩm). Nó có thể được bài trí theo phong cách Flatlay hoặc chụp góc nghiêng nhẹ để thấy rõ chi tiết.`;
                } else {
                    presentationInstruction = `Trong hình ảnh mới, ${clothingItem} này phải được treo trên một chiếc móc treo bằng gỗ hoặc kim loại sang trọng, phù hợp với kiểu dáng của nó. Bối cảnh xung quanh phải là một không gian đẹp, tối giản và trang nhã, có ánh sáng tự nhiên dịu nhẹ, giống như một phòng trưng bày thời trang cao cấp.`;
                }

                if (numberOfImages > 1) {
                    presentationInstruction += ` Đây là biến thể thứ ${i + 1}, hãy thay đổi nhẹ về góc chiếu sáng hoặc bố cục nền để tạo sự khác biệt nhỏ.`;
                }
            }

            const textPart = {
                text: `Từ hình ảnh ${clothingItem} được cung cấp, hãy tạo ra một hình ảnh mới, chất lượng cao, độ phân giải 2K, với ${ratioPhrase}. Quan trọng: Nếu hình ảnh gốc có viền đen ở trên hoặc dưới (letterboxing), hãy bỏ qua các viền đen đó và đảm bảo hình ảnh kết quả lấp đầy toàn bộ khung hình, chỉ tập trung vào sản phẩm. ${presentationInstruction} Không có người hoặc ma-nơ-canh trong ảnh. Hình ảnh cuối cùng phải có độ sắc nét cực cao, chi tiết, chất lượng cao, và có tính thẩm mỹ cao, như thể được chụp bằng máy ảnh kỹ thuật số chuyên nghiệp.`,
            };

            const generatedImageBase64 = await callGeminiApiForImage(imagePart, textPart);
            results.push(generatedImageBase64);
        }

        return results;

    } catch (error) {
        console.error("Lỗi khi gọi Gemini API cho ảnh sản phẩm:", error);
        throw new Error("AI không thể tạo ảnh sản phẩm. Vui lòng thử lại.");
    }
};

