import React, { useState, useCallback, useRef } from 'react';
import { generateStyledImage, generateModelImage, ModelPose, AspectRatio, generateBackgroundSuggestion, ProductDisplayMode } from './services/geminiService';
import { UploadIcon, SparklesIcon, LoadingSpinner, ErrorIcon, HangerIcon, UserIcon, ArrowLeftIcon, DownloadIcon, XIcon, RefreshIcon, WandIcon, ClipboardIcon, ClipboardCheckIcon } from './components/Icons';

type AppState = 'IDLE' | 'PROCESSING' | 'SUCCESS' | 'ERROR';
type ClothingType = 'Áo' | 'Quần' | 'Cả bộ' | 'Váy' | 'Phụ kiện';
type FeatureMode = 'product' | 'model';
type Gender = 'Nam' | 'Nữ';

interface ResultItem {
    url: string;
    videoPrompt?: string;
}

interface ProductStudioProps {
  onGoBack: () => void;
  onEnhanceImage: (imageUrl: string) => void;
}

const ProductStudio: React.FC<ProductStudioProps> = ({ onGoBack, onEnhanceImage }) => {
  // Core state
  const [originalImageFile, setOriginalImageFile] = useState<File | null>(null);
  const [originalImageUrl, setOriginalImageUrl] = useState<string | null>(null);
  const [generatedResults, setGeneratedResults] = useState<ResultItem[]>([]);
  const [appState, setAppState] = useState<AppState>('IDLE');
  const [error, setError] = useState<string | null>(null);

  // Feature selection state
  const [featureMode, setFeatureMode] = useState<FeatureMode | null>(null);
  const [clothingType, setClothingType] = useState<ClothingType | null>(null);
  const [aspectRatio, setAspectRatio] = useState<AspectRatio>('9:16');
  const [productDisplayMode, setProductDisplayMode] = useState<ProductDisplayMode>('hanger');

  // Model-specific state
  const [gender, setGender] = useState<Gender>('Nữ');
  const [age, setAge] = useState<string>('18-25');
  const [background, setBackground] = useState<string>('');
  const [numberOfImages, setNumberOfImages] = useState<number>(1);
  const [modelPose, setModelPose] = useState<ModelPose>('Dáng đứng');
  const [isGeneratingBackground, setIsGeneratingBackground] = useState<boolean>(false);
  const [copiedPromptIndex, setCopiedPromptIndex] = useState<number | null>(null);

  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFileChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (file) {
      if (!file.type.startsWith('image/')) {
        setError('Vui lòng chọn một tệp hình ảnh.');
        setAppState('ERROR');
        return;
      }
      // Reset only results, not settings
      setGeneratedResults([]);
      setError(null);
      setAppState('IDLE');

      setOriginalImageFile(file);
      setOriginalImageUrl(URL.createObjectURL(file));
    }
  };

  const handleRemoveImage = (e: React.MouseEvent) => {
    e.stopPropagation();
    // Only reset image and results, keep all other settings
    setOriginalImageFile(null);
    setOriginalImageUrl(null);
    setGeneratedResults([]);
    setError(null);
    setAppState('IDLE');
    if (fileInputRef.current) {
        fileInputRef.current.value = "";
    }
  };

  const handleGenerateBackground = async () => {
    if (!originalImageFile || !clothingType) return;

    setIsGeneratingBackground(true);
    setError(null);

    const reader = new FileReader();
    reader.readAsDataURL(originalImageFile);
    reader.onloadend = async () => {
        try {
            const base64String = (reader.result as string).split(',')[1];
            if (!base64String) {
              throw new Error('Không thể chuyển đổi hình ảnh.');
            }
            const suggestion = await generateBackgroundSuggestion(base64String, originalImageFile.type, clothingType);
            setBackground(suggestion.trim().replace(/^"|"$/g, '')); // Remove quotes if API returns them
        } catch (err: any) {
          console.error(err);
          setError(err.message || 'Không thể tạo bối cảnh. Vui lòng thử lại.');
          setAppState('ERROR');
        } finally {
            setIsGeneratingBackground(false);
        }
    };
    reader.onerror = () => {
       setError('Lỗi khi đọc tệp hình ảnh.');
       setAppState('ERROR');
       setIsGeneratingBackground(false);
    }
  };

  const handleGenerateClick = useCallback(async () => {
    if (!originalImageFile || !clothingType || !featureMode) return;

    if(featureMode === 'model' && !background.trim()){
        setError('Vui lòng nhập mô tả bối cảnh.');
        setAppState('ERROR');
        return;
    }

    setAppState('PROCESSING');
    setError(null);
    setGeneratedResults([]);


    try {
      const reader = new FileReader();
      reader.readAsDataURL(originalImageFile);
      reader.onloadend = async () => {
        const base64String = (reader.result as string).split(',')[1];
        if (!base64String) {
          throw new Error('Không thể chuyển đổi hình ảnh.');
        }

        if (featureMode === 'product') {
            const generatedImages = await generateStyledImage(base64String, originalImageFile.type, clothingType, aspectRatio, productDisplayMode, numberOfImages);
            setGeneratedResults(generatedImages.map(url => ({ url: `data:image/jpeg;base64,${url}` })));
        } else { // featureMode === 'model'
            const generatedImages = await generateModelImage(base64String, originalImageFile.type, {
                clothingType,
                gender,
                age,
                background,
                numberOfImages,
                pose: modelPose,
                aspectRatio,
            });
            setGeneratedResults(generatedImages.map(item => ({
                url: item.imageUrl,
                videoPrompt: item.videoPrompt
            })));
        }

        setAppState('SUCCESS');
      };
      reader.onerror = () => {
         throw new Error('Lỗi khi đọc tệp hình ảnh.');
      }
    } catch (err: any) {
      console.error(err);
      setError(err.message || 'Đã xảy ra lỗi không mong muốn. Vui lòng thử lại.');
      setAppState('ERROR');
    }
  }, [originalImageFile, featureMode, clothingType, gender, age, background, numberOfImages, modelPose, aspectRatio, productDisplayMode]);

  const triggerFileInput = () => {
    fileInputRef.current?.click();
  };

  const resetState = () => {
    setOriginalImageFile(null);
    setOriginalImageUrl(null);
    setGeneratedResults([]);
    setError(null);
    setClothingType(null);
    setFeatureMode(null);
    setAspectRatio('9:16');
    setGender('Nữ');
    setAge('18-25');
    setBackground('');
    setNumberOfImages(1);
    setModelPose('Dáng đứng');
    setProductDisplayMode('hanger');
    setIsGeneratingBackground(false);
    setAppState('IDLE');
    if(fileInputRef.current) {
        fileInputRef.current.value = "";
    }
  };

  const handleCopyToClipboard = (textToCopy: string, index: number) => {
    navigator.clipboard.writeText(textToCopy);
    setCopiedPromptIndex(index);
    setTimeout(() => setCopiedPromptIndex(null), 2000);
  };

  const isGenerateButtonDisabled = () => {
    if (appState === 'PROCESSING' || !originalImageFile || !featureMode || !clothingType) {
        return true;
    }
    if (featureMode === 'model' && !background.trim()) {
        return true;
    }
    return false;
  }

  return (
