export const generateReviewScript = async (options: ReviewScriptOptions): Promise<ReviewScriptResult> => {
    try {
         const prompt = `Bạn là một TikToker/Reviewer nổi tiếng chuyên review sản phẩm. Hãy viết kịch bản review ngắn cho sản phẩm sau: "${options.productInfo}".
         Loại kịch bản: ${options.scriptType}.
         Giọng điệu/Phương ngữ mục tiêu: ${options.accent}.

         Yêu cầu output JSON gồm 3 phần, mỗi phần tương ứng khoảng 10 giây nói:
         1. "hook": Câu mở đầu gây tò mò hoặc đánh vào nỗi đau khách hàng.
         2. "body": Giới thiệu tính năng nổi bật và lợi ích, cảm nhận thực tế.
         3. "cta": Lời kêu gọi hành động (mua ngay, click giỏ hàng) mạnh mẽ.

         Nội dung phải tự nhiên, đời thường, dùng từ ngữ trendy nếu phù hợp.`;

        const response = await ai.models.generateContent({
            model: 'gemini-2.5-flash',
            contents: prompt,
            config: {
                responseMimeType: 'application/json',
                responseSchema: {
                    type: Type.OBJECT,
                    properties: {
                        hook: { type: Type.STRING },
                        body: { type: Type.STRING },
                        cta: { type: Type.STRING },
                    },
                    required: ['hook', 'body', 'cta'],
                }
            }
        });

        const jsonStr = response.text;
        return JSON.parse(jsonStr) as ReviewScriptResult;

    } catch (error) {
        console.error("Error generating review script:", error);
        throw new Error("Không thể tạo kịch bản review.");
    }
};


