import { GoogleGenAI, GenerateContentResponse, Type } from "@google/genai";

const API_KEY = process.env.API_KEY;
if (!API_KEY) {
    throw new Error("API_KEY is not defined in environment variables");
}

const ai = new GoogleGenAI({ apiKey: API_KEY });

// Types
export type ClothingType = 'Áo' | 'Quần' | 'Cả bộ' | 'Váy' | 'Phụ kiện';
export type Gender = 'Nam' | 'Nữ';
export type ModelPose = 'Dáng đứng' | 'Dáng đi' | 'Giới thiệu (Cầm móc)' | 'Giới thiệu (Chỉ mặc)';
export type AspectRatio = '9:16' | '1:1' | '4:5' | '16:9';
export type ProductDisplayMode = 'hanger' | 'flatlay';

export interface ModelImageOptions {
    clothingType: ClothingType;
    gender: Gender;
    age: string;
    background: string;
    numberOfImages: number;
    pose: ModelPose;
    aspectRatio: AspectRatio;
}

export interface LookbookOptions {
    clothingType: ClothingType;
    gender: Gender;
    age: string;
    theme: string;
    additionalPrompt?: string;
    numberOfImages: number;
    pose: ModelPose;
    aspectRatio: AspectRatio;
    generateVideo: boolean;
}

export interface LookbookResult {
    imageUrl: string;
    videoPrompt?: string;
}

export interface EnhanceOptions {
    upscale: boolean;
    sharpen: boolean;
    removeWatermark: boolean;
}

export interface ReviewScriptOptions {
    productInfo: string;
    scriptType: string;
    accent: string;
}

export type ScriptType = 'Review sản phẩm' | 'Quảng cáo sản phẩm' | 'Chào hàng (Sale)';
export type RegionalAccent = 'Miền Bắc' | 'Miền Nam';

export interface ReviewScriptResult {
    hook: string;
    body: string;
    cta: string;
}

export interface VideoPromptOptions {
    productInfo: string;
    targetAudience: string;
    videoStyle: string;
}

export type VoiceoverStyle = 'Năng động' | 'Trang trọng' | 'Thân thiện';

// Helpers
const fileToPart = (base64String: string, mimeType: string) => {
    return {
        inlineData: {
            data: base64String,
            mimeType
        }
    };
};

// Implementations

export const generateBackgroundSuggestion = async (base64Image: string, mimeType: string, clothingType: string): Promise<string> => {
    try {
        const model = 'gemini-2.5-flash';
        const prompt = `Suggest a short, artistic background description (under 20 words) suitable for a fashion photo of this ${clothingType}. In Vietnamese.`;

        const response = await ai.models.generateContent({
            model,
            contents: {
                parts: [fileToPart(base64Image, mimeType), { text: prompt }]
            }
        });
        return response.text || "";
    } catch (e) {
        console.error("Generate Background Error", e);
        return "Phông nền studio chuyên nghiệp";
    }
}

export const generateStyledImage = async (base64Image: string, mimeType: string, clothingType: string, aspectRatio: AspectRatio, displayMode: ProductDisplayMode, count: number): Promise<string[]> => {
    const results: string[] = [];
    // Randomization arrays for Flatlay
    const rugShapes = ['hình trái tim', 'hình tròn', 'hình chữ nhật bo góc'];
    const pastelColors = ['màu hồng phấn pastel', 'màu xanh mint pastel', 'màu kem bơ', 'màu tím lavender nhạt'];
    const decorItems = ['một vài cành hoa nhỏ tinh tế', 'một chiếc túi xách mini', 'một chú gấu bông nhỏ'];

    for(let i=0; i<count; i++) {
        try {
            let prompt = `Generate a professional product photo of this ${clothingType}. `;

            if (displayMode === 'flatlay') {
                const shape = rugShapes[i % rugShapes.length];
                const color = pastelColors[Math.floor(Math.random() * pastelColors.length)];
                const decor = decorItems[Math.floor(Math.random() * decorItems.length)];
                prompt += `Placement: Flatlay on a ${shape} fur rug. Rug color: ${color}. Decoration: ${decor} placed near the item but NOT overlapping it. View: Top-down. Lighting: Soft, natural.`;
            } else {
                prompt += `Display mode: Hanging on a rack or shelf. Aspect Ratio: ${aspectRatio}. High quality studio lighting.`;
            }

            const response = await ai.models.generateContent({
                model: 'gemini-2.5-flash-image',
                contents: {
                    parts: [
                        fileToPart(base64Image, mimeType),
                        { text: prompt }
                    ]
                }
            });

            if(response.candidates?.[0]?.content?.parts) {
                for (const part of response.candidates[0].content.parts) {
                    if (part.inlineData && part.inlineData.data) {
                        results.push(part.inlineData.data);
                        break; 
                    }
                }
            }
        } catch (e) {
            console.error(`Error generating image ${i+1}:`, e);
            // Continue to next iteration if one fails
        }
    }

    if (results.length === 0) {
        throw new Error("Không thể tạo ảnh. Vui lòng thử lại sau.");
    }
    return results;
}

export const generateModelImage = async (base64Image: string, mimeType: string, options: ModelImageOptions): Promise<{imageUrl: string, videoPrompt: string}[]> => {
    const results: {imageUrl: string, videoPrompt: string}[] = [];

    for(let i=0; i<options.numberOfImages; i++) {
        try {
             const prompt = `Fashion photography. A ${options.age} year old ${options.gender} model wearing this ${options.clothingType}. Pose: ${options.pose}. Background: ${options.background}. Aspect Ratio: ${options.aspectRatio}. Photorealistic, 8k. Ensure the clothing looks exactly like the reference image.`;

             // Switched to 'gemini-2.5-flash-image' for better availability/stability
             const response = await ai.models.generateContent({
                model: 'gemini-2.5-flash-image', 
                contents: {
                    parts: [
                        fileToPart(base64Image, mimeType),
                        { text: prompt }
                    ]
                }
            });

            let imageUrl = "";
            if(response.candidates?.[0]?.content?.parts) {
                 for (const part of response.candidates[0].content.parts) {
                    if (part.inlineData && part.inlineData.data) {
                        imageUrl = `data:image/jpeg;base64,${part.inlineData.data}`;
                        break; 
                    }
                }
            }

            if(imageUrl) {
                 const videoPrompt = `Cinematic shot of ${options.gender} model in ${options.background}, wearing ${options.clothingType}, ${options.pose}, 4k resolution, slow motion.`;
                 results.push({ imageUrl, videoPrompt });
            }
        } catch (e) {
            console.error(`Error generating model image ${i+1}:`, e);
        }
    }

    if (results.length === 0) {
        throw new Error("Không thể tạo ảnh người mẫu. Vui lòng kiểm tra lại ảnh đầu vào.");
    }
    return results;
}

export const generateLookbookImages = async (base64Image: string, mimeType: string, options: LookbookOptions): Promise<LookbookResult[]> => {
    const results: LookbookResult[] = [];

    for(let i=0; i<options.numberOfImages; i++) {
        try {
            const prompt = `Lookbook fashion shot. ${options.theme}. A ${options.age} year old ${options.gender} model wearing this ${options.clothingType}. Pose: ${options.pose}. ${options.additionalPrompt || ''}. Aspect Ratio: ${options.aspectRatio}. Professional fashion photography.`;

            // Switched to 'gemini-2.5-flash-image' for better availability/stability
            const response = await ai.models.generateContent({
                model: 'gemini-2.5-flash-image',
                contents: {
                    parts: [
                         fileToPart(base64Image, mimeType),
                         { text: prompt }
                    ]
                }
            });

            let imageUrl = "";
            if(response.candidates?.[0]?.content?.parts) {
                 for (const part of response.candidates[0].content.parts) {
                    if (part.inlineData && part.inlineData.data) {
                        imageUrl = `data:image/jpeg;base64,${part.inlineData.data}`;
                        break; 
                    }
                }
            }

            let videoPrompt = "";
            if (imageUrl && options.generateVideo) {
                 const vpResponse = await ai.models.generateContent({
                    model: 'gemini-2.5-flash',
                    contents: {
                        parts: [
                            { text: `Create a high-quality text-to-video prompt (in English) for this image description: ${prompt}. The video should be cinematic and slow motion.` }
                        ]
                    }
                });
                videoPrompt = vpResponse.text || "";
            }

            if (imageUrl) {
                results.push({ imageUrl, videoPrompt });
            }
        } catch (e) {
            console.error(`Error generating lookbook image ${i+1}:`, e);
        }
    }

    if (results.length === 0) {
        throw new Error("Không thể tạo bộ Lookbook. Vui lòng thử lại.");
    }

    return results;
}

export const enhanceImage = async (base64Image: string, mimeType: string, options: EnhanceOptions): Promise<string> => {
    try {
        const prompt = `Enhance this image. ${options.upscale ? 'Upscale to 4K.' : ''} ${options.sharpen ? 'Sharpen details.' : ''} ${options.removeWatermark ? 'Remove any watermarks or text.' : ''} High fidelity, preserve original details.`;

        // Switched to 'gemini-2.5-flash-image' for better availability/stability
        const response = await ai.models.generateContent({
            model: 'gemini-2.5-flash-image',
             contents: {
                    parts: [
                         fileToPart(base64Image, mimeType),
                         { text: prompt }
                    ]
                }
        });

        if(response.candidates?.[0]?.content?.parts) {
            for (const part of response.candidates[0].content.parts) {
                if (part.inlineData && part.inlineData.data) {
                    return part.inlineData.data;
                }
            }
        }
    } catch (e) {
        console.error("Error enhancing image:", e);
    }
    throw new Error("Could not enhance image");
}

