export const generateReviewScript = async (options: ReviewScriptOptions): Promise<ReviewScriptResult> => {
    try {
        const prompt = `Write a 3-sentence short video script (TikTok/Reels style) for this product: ${options.productInfo}.
        Type: ${options.scriptType}. Accent/Dialect style: ${options.accent}.
        Format: JSON with keys "hook", "body", "cta".`;

        const response = await ai.models.generateContent({
            model: 'gemini-2.5-flash',
            contents: prompt,
            config: {
                responseMimeType: 'application/json'
            }
        });

        return JSON.parse(response.text || "{}");
    } catch (e) {
        console.error("Error generating review script:", e);
        return { hook: "Lỗi tạo kịch bản", body: "Vui lòng thử lại", cta: "Thử lại" };
    }
}

