import { GoogleGenAI, GenerateContentResponse, Type } from "@google/genai";

const API_KEY = process.env.API_KEY;
if (!API_KEY) {
    throw new Error("API_KEY is not defined in environment variables");
}

const ai = new GoogleGenAI({ apiKey: API_KEY });

// Types
export type ClothingType = 'Áo' | 'Quần' | 'Cả bộ' | 'Váy' | 'Phụ kiện';
export type Gender = 'Nam' | 'Nữ';
export type ModelPose = 'Dáng đứng' | 'Dáng đi' | 'Giới thiệu (Cầm móc)' | 'Giới thiệu (Chỉ mặc)';
export type AspectRatio = '9:16' | '1:1' | '4:5' | '16:9';
export type ProductDisplayMode = 'hanger' | 'flatlay';
export type Ethnicity = 'Việt Nam' | 'Hàn Quốc';

export interface ModelImageOptions {
    clothingType: ClothingType;
    gender: Gender;
    age: string;
    background: string;
    numberOfImages: number;
    pose: ModelPose;
    aspectRatio: AspectRatio;
}

export interface LookbookOptions {
    clothingType: ClothingType;
    gender: Gender;
    age: string;
    theme: string;
    additionalPrompt?: string;
    numberOfImages: number;
    pose: ModelPose;
    aspectRatio: AspectRatio;
    generateVideo: boolean;
    ethnicity: Ethnicity;
}

export interface LookbookResult {
    imageUrl: string;
    videoPrompt?: string;
}

export interface EnhanceOptions {
    upscale: boolean;
    sharpen: boolean;
    removeWatermark: boolean;
}

export interface ReviewScriptOptions {
    productInfo: string;
    scriptType: string;
    accent: string;
}

export type ScriptType = 'Review sản phẩm' | 'Quảng cáo sản phẩm' | 'Chào hàng (Sale)';
export type RegionalAccent = 'Miền Bắc' | 'Miền Nam';

export interface ReviewScriptResult {
    hook: string;
    body: string;
    cta: string;
}

export interface VideoPromptOptions {
    productInfo: string;
    targetAudience: string;
    videoStyle: string;
}

export type VoiceoverStyle = 'Năng động' | 'Trang trọng' | 'Thân thiện';

// Helpers
const fileToPart = (base64String: string, mimeType: string) => {
    return {
        inlineData: {
            data: base64String,
            mimeType
        }
    };
};

// Implementations

export const generateBackgroundSuggestion = async (base64Image: string, mimeType: string, clothingType: string): Promise<string> => {
    try {
        const model = 'gemini-2.5-flash';
        const prompt = `Suggest a short, artistic background description (under 20 words) suitable for a fashion photo of this ${clothingType}. In Vietnamese.`;

        const response = await ai.models.generateContent({
            model,
            contents: {
                parts: [fileToPart(base64Image, mimeType), { text: prompt }]
            }
        });
        return response.text || "";
    } catch (e) {
        console.error("Generate Background Error", e);
        return "Phông nền studio chuyên nghiệp";
    }
}

export const generateStyledImage = async (base64Image: string, mimeType: string, clothingType: string, aspectRatio: AspectRatio, displayMode: ProductDisplayMode, count: number): Promise<string[]> => {
    const results: string[] = [];
    // Randomization arrays for Flatlay
    const rugShapes = ['hình trái tim', 'hình tròn', 'hình chữ nhật bo góc'];
    const pastelColors = ['màu hồng phấn pastel', 'màu xanh mint pastel', 'màu kem bơ', 'màu tím lavender nhạt'];
    const decorItems = ['một vài cành hoa nhỏ tinh tế', 'một chiếc túi xách mini', 'một chú gấu bông nhỏ'];

    for(let i=0; i<count; i++) {
        try {
            let prompt = `Generate a professional product photo of this ${clothingType}. `;

            if (displayMode === 'flatlay') {
                const shape = rugShapes[i % rugShapes.length];
                const color = pastelColors[Math.floor(Math.random() * pastelColors.length)];
                const decor = decorItems[Math.floor(Math.random() * decorItems.length)];
                prompt += `Placement: Flatlay on a ${shape} fur rug. Rug color: ${color}. Decoration: ${decor} placed near the item but NOT overlapping it. View: Top-down. Lighting: Soft, natural.`;
            } else {
                prompt += `Display mode: Hanging on a rack or shelf. Aspect Ratio: ${aspectRatio}. High quality studio lighting.`;
            }

            const response = await ai.models.generateContent({
                model: 'gemini-2.5-flash-image',
                contents: {
                    parts: [
                        fileToPart(base64Image, mimeType),
                        { text: prompt }
                    ]
                }
            });

            if(response.candidates?.[0]?.content?.parts) {
                for (const part of response.candidates[0].content.parts) {
                    if (part.inlineData && part.inlineData.data) {
                        results.push(part.inlineData.data);
                        break; 
                    }
                }
            }
        } catch (e) {
            console.error(`Error generating image ${i+1}:`, e);
            // Continue to next iteration if one fails
        }
    }

    if (results.length === 0) {
        throw new Error("Không thể tạo ảnh. Vui lòng thử lại sau.");
    }
    return results;
}

