export const generateLookbookImages = async (base64Image: string, mimeType: string, options: LookbookOptions): Promise<LookbookResult[]> => {
    const results: LookbookResult[] = [];
    const genderEn = options.gender === 'Nam' ? 'male' : 'female';

    // Determine ethnicity specific prompt details
    let ethnicityPrompt = "";
    let stylePrompt = "";

    if (options.ethnicity === 'Hàn Quốc') {
        ethnicityPrompt = "Korean (K-pop idol aesthetic, fair skin, soft features, trendy hairstyle)";
        stylePrompt = "Korean fashion style, clean, minimalist or trendy streetwear aesthetics";
    } else {
        ethnicityPrompt = "Vietnamese (distinctive Vietnamese Asian facial features, natural beauty, black hair)";
        stylePrompt = "Modern Vietnamese fashion aesthetics, elegant and natural";
    }

    for(let i=0; i<options.numberOfImages; i++) {
        try {
            const prompt = `Lookbook fashion shot. ${options.theme}. A ${options.age} year old ${ethnicityPrompt} ${genderEn} model wearing this ${options.clothingType}. Style: ${stylePrompt}. Pose: ${options.pose}. ${options.additionalPrompt || ''}. Aspect Ratio: ${options.aspectRatio}. Professional fashion photography.`;

            const response = await ai.models.generateContent({
                model: 'gemini-2.5-flash-image',
                contents: {
                    parts: [
                         fileToPart(base64Image, mimeType),
                         { text: prompt }
                    ]
                }
            });

            let imageUrl = "";
            if(response.candidates?.[0]?.content?.parts) {
                 for (const part of response.candidates[0].content.parts) {
                    if (part.inlineData && part.inlineData.data) {
                        imageUrl = `data:image/jpeg;base64,${part.inlineData.data}`;
                        break; 
                    }
                }
            }

            let videoPrompt = "";
            if (imageUrl && options.generateVideo) {
                 const vpResponse = await ai.models.generateContent({
                    model: 'gemini-2.5-flash',
                    contents: {
                        parts: [
                            { text: `Create a high-quality text-to-video prompt (in English) for this image description: ${prompt}. The video should be cinematic and slow motion.` }
                        ]
                    }
                });
                videoPrompt = vpResponse.text || "";
            }

            if (imageUrl) {
                results.push({ imageUrl, videoPrompt });
            }
        } catch (e) {
            console.error(`Error generating lookbook image ${i+1}:`, e);
        }
    }

    if (results.length === 0) {
        throw new Error("Không thể tạo bộ Lookbook. Vui lòng thử lại.");
    }

    return results;
}

