export const generateLookbookImages = async (base64Image: string, mimeType: string, options: LookbookOptions): Promise<LookbookResult[]> => {
    const results: LookbookResult[] = [];
    const genderEn = options.gender === 'Nam' ? 'male' : 'female';

    // Determine ethnicity specific prompt details
    let ethnicityPrompt = "";
    let stylePrompt = "";

    if (options.ethnicity === 'Hàn Quốc') {
        ethnicityPrompt = "Korean (K-pop idol aesthetic, fair skin, soft features, trendy hairstyle)";
        stylePrompt = "Korean fashion style, clean, minimalist or trendy streetwear aesthetics";
    } else {
        ethnicityPrompt = "Vietnamese (distinctive Vietnamese Asian facial features, natural black hair, elegant)";
        stylePrompt = "Modern Vietnamese fashion style, elegant, sophisticated";
    }

    for(let i=0; i<options.numberOfImages; i++) {
        try {
            // Enhanced Lookbook Prompt
            const prompt = `Fashion Lookbook Photography. A ${options.age} year old ${ethnicityPrompt} ${genderEn} model wearing this ${options.clothingType}.
            Theme: ${options.theme}.
            Additional details: ${options.additionalPrompt || 'None'}.
            Style: ${stylePrompt}. Pose: ${options.pose}. Aspect Ratio: ${options.aspectRatio}.
            Quality: 2k resolution, ultra-sharp focus, highly detailed texture, natural skin texture (no plastic skin), natural lighting, cinematic color grading, photorealistic masterpiece, 8k uhd.`;

             const response = await ai.models.generateContent({
                model: 'gemini-2.5-flash-image',
                contents: {
                    parts: [
                        fileToPart(base64Image, mimeType),
                        { text: prompt }
                    ]
                }
            });

            let imageUrl = "";
            if(response.candidates?.[0]?.content?.parts) {
                for (const part of response.candidates[0].content.parts) {
                    if (part.inlineData && part.inlineData.data) {
                        imageUrl = `data:image/jpeg;base64,${part.inlineData.data}`;
                        break; 
                    }
                }
            }

            if (imageUrl) {
                 let videoPrompt = "";
                 if (options.generateVideo) {
                    // Optimized prompt for Veo 3.1
                     videoPrompt = `Cinematic video. A beautiful ${ethnicityPrompt} ${genderEn} model wearing ${options.clothingType}, standing in ${options.theme}. 
                     Action: Subtle movement, smiling gently at the camera, running hand through hair.
                     Style: ${stylePrompt}, high fashion, 4k resolution, shallow depth of field, slow motion, soft lighting.`;
                 }
                 results.push({ imageUrl, videoPrompt });
            }

        } catch (e) {
            console.error(`Error generating lookbook image ${i+1}:`, e);
        }
    }

    if (results.length === 0) {
        throw new Error("Không thể tạo ảnh Lookbook. Vui lòng thử lại.");
    }
    return results;
}

export const enhanceImage = async (base64Image: string, mimeType: string, options: EnhanceOptions): Promise<string> => {
    try {
        let promptInstructions = "";
        if (options.upscale) promptInstructions += "Upscale to high resolution (2K), improve clarity and definition. ";
        if (options.sharpen) promptInstructions += "Sharpen details, fix softness or blur, enhance focus. ";
        if (options.removeWatermark) promptInstructions += "Remove any watermarks, text, or logos overlaid on the image, filling the area naturally. ";

        const prompt = `Enhance this image based on the following instructions: ${promptInstructions}. 
        General Quality: 2k resolution, ultra-sharp focus, natural colors, photorealistic, high fidelity. Maintain the original subject identity and clothing details exactly.`;

        const response = await ai.models.generateContent({
            model: 'gemini-2.5-flash-image',
            contents: {
                parts: [
                    fileToPart(base64Image, mimeType),
                    { text: prompt }
                ]
            }
        });

        if(response.candidates?.[0]?.content?.parts) {
            for (const part of response.candidates[0].content.parts) {
                if (part.inlineData && part.inlineData.data) {
                    return part.inlineData.data;
                }
            }
        }
        throw new Error("No image returned from enhancement model.");
    } catch (e) {
        console.error("Enhance Image Error", e);
        throw new Error("Không thể nâng cấp ảnh. Vui lòng thử lại.");
    }
}

export const generateReviewScript = async (options: ReviewScriptOptions): Promise<ReviewScriptResult> => {
    try {
        const prompt = `Write a short, catchy 3-sentence video review script (TikTok/Shorts style) for this product.
        Product Info: ${options.productInfo}.
        Type: ${options.scriptType}.
        Accent/Regional Dialect: ${options.accent} (Use authentic local vocabulary: e.g., 'đỉnh chóp', 'nhức nách', 'chất lừ', 'giá rổ' for North; 'bao đẹp', 'xịn sò', 'cưng xỉu', 'giá hạt dẻ' for South).
        Structure:
        1. Hook (Capture attention in 2 seconds)
        2. Body (Key benefit/feature in 1 sentence)
        3. CTA (Call to action)

        Output JSON format: { "hook": "...", "body": "...", "cta": "..." }`;

        const response = await ai.models.generateContent({
            model: 'gemini-2.5-flash',
            contents: { text: prompt },
            config: {
                 responseMimeType: "application/json"
            }
        });

        const text = response.text || "{}";
        return JSON.parse(text) as ReviewScriptResult;

    } catch (e) {
        console.error("Generate Script Error", e);
        throw new Error("Không thể tạo kịch bản. Vui lòng thử lại.");
    }
}

