import ReviewScriptGenerator from './ReviewScriptGenerator';
import LookbookGenerator from './LookbookGenerator';

export type View = 'HOME' | 'PRODUCT_STUDIO' | 'IMAGE_ENHANCER' | 'REVIEW_SCRIPT_GENERATOR' | 'LOOKBOOK_GENERATOR';

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<View>('HOME');
  const [imageForEnhancement, setImageForEnhancement] = useState<string | null>(null);

  const handleSelectFeature = (view: View) => {
    setCurrentView(view);
  };

  const handleGoHome = () => {
    setCurrentView('HOME');
    setImageForEnhancement(null);
  };

  const handleEnhanceRequest = (imageUrl: string) => {
    setImageForEnhancement(imageUrl);
    setCurrentView('IMAGE_ENHANCER');
  };

  const renderView = () => {
    switch (currentView) {
      case 'PRODUCT_STUDIO':
        return <ProductStudio onGoBack={handleGoHome} onEnhanceImage={handleEnhanceRequest} />;
      case 'IMAGE_ENHANCER':
        return <ImageEnhancer onGoBack={handleGoHome} initialImageUrl={imageForEnhancement} />;
      case 'REVIEW_SCRIPT_GENERATOR':
        return <ReviewScriptGenerator onGoBack={handleGoHome} />;
      case 'LOOKBOOK_GENERATOR':
        return <LookbookGenerator onGoBack={handleGoHome} />;
      case 'HOME':
      default:
        return <HomePage onSelectFeature={handleSelectFeature} />;
    }
  };

  return (
    <div className="bg-slate-900 min-h-screen text-slate-100 font-sans selection:bg-indigo-500 selection:text-white">
      {renderView()}
