                                `}
                            >
                                <mode.icon className="w-5 h-5 mb-1" />
                                {mode.label}
                            </button>
                        ))}
                    </div>
                </div>

                {/* 3. Detailed Settings */}
                <div className={`space-y-6 transition-opacity duration-300 ${!originalImageFile ? 'opacity-50 pointer-events-none' : ''}`}>

                    {/* Clothing Type */}
                    <div className="space-y-2">
                        <label className="text-xs font-medium text-slate-400">Loại trang phục</label>
                        <div className="flex flex-wrap gap-2">
                            {(['Áo', 'Quần', 'Cả bộ', 'Váy', 'Phụ kiện'] as ClothingType[]).map((type) => (
                                <button
                                    key={type}
                                    onClick={() => setClothingType(type)}
                                    className={`px-3 py-1.5 rounded-full text-xs font-medium border transition-all
                                        ${clothingType === type ? 'bg-indigo-500/20 border-indigo-500 text-indigo-300' : 'bg-slate-800 border-slate-700 text-slate-400 hover:border-slate-500'}
                                    `}
                                >
                                    {type}
                                </button>
                            ))}
                        </div>
                    </div>

                    {/* Aspect Ratio */}
                     {featureMode !== 'selfie' && (
                        <div className="space-y-2">
                            <label className="text-xs font-medium text-slate-400">Tỉ lệ khung hình</label>
                            <div className="flex bg-slate-900 rounded-lg p-1">
                                {(['9:16', '1:1', '4:5', '16:9'] as AspectRatio[]).map((ratio) => (
                                    <button
                                        key={ratio}
                                        onClick={() => setAspectRatio(ratio)}
                                        className={`flex-1 py-1.5 rounded text-xs font-medium transition-all
                                            ${aspectRatio === ratio ? 'bg-slate-700 text-white shadow' : 'text-slate-500 hover:text-slate-300'}
                                        `}
                                    >
                                        {ratio}
                                    </button>
                                ))}
                            </div>
                        </div>
                    )}

                    {/* Feature Specific Settings */}
                    {featureMode === 'product' && (
                        <div className="space-y-4 p-4 bg-slate-900/50 rounded-xl border border-slate-700">
                             <div className="space-y-2">
                                <label className="text-xs font-medium text-slate-400">Cách trình bày</label>
                                <div className="grid grid-cols-2 gap-2">
                                    <button onClick={() => setProductDisplayMode('hanger')} className={`py-2 px-3 rounded-lg border text-xs font-medium ${productDisplayMode === 'hanger' ? 'bg-indigo-500/20 border-indigo-500 text-white' : 'bg-slate-800 border-slate-700 text-slate-400'}`}>Treo móc / Kệ</button>
                                    <button onClick={() => setProductDisplayMode('flatlay')} className={`py-2 px-3 rounded-lg border text-xs font-medium ${productDisplayMode === 'flatlay' ? 'bg-indigo-500/20 border-indigo-500 text-white' : 'bg-slate-800 border-slate-700 text-slate-400'}`}>Flatlay (Trải sàn)</button>
                                </div>
                            </div>
                        </div>
                    )}

                    {featureMode === 'model' && (
                        <div className="space-y-4 p-4 bg-slate-900/50 rounded-xl border border-slate-700">
                            <div className="grid grid-cols-2 gap-4">
                                <div>
                                    <label className="text-xs font-medium text-slate-400 block mb-1.5">Giới tính</label>
                                    <select value={gender} onChange={(e) => setGender(e.target.value as Gender)} className="w-full bg-slate-800 border border-slate-600 rounded-lg px-3 py-2 text-sm text-white focus:ring-1 focus:ring-indigo-500 focus:border-indigo-500 outline-none">
                                        <option value="Nữ">Nữ</option>
                                        <option value="Nam">Nam</option>
                                    </select>
                                </div>
                                <div>
                                    <label className="text-xs font-medium text-slate-400 block mb-1.5">Độ tuổi</label>
                                    <select value={age} onChange={(e) => setAge(e.target.value)} className="w-full bg-slate-800 border border-slate-600 rounded-lg px-3 py-2 text-sm text-white focus:ring-1 focus:ring-indigo-500 focus:border-indigo-500 outline-none">
                                        <option value="18-25">18-25</option>
                                        <option value="26-35">26-35</option>
                                    </select>
                                </div>
                            </div>
                            <div>
                                <label className="text-xs font-medium text-slate-400 block mb-1.5">Dáng Pose</label>
                                <select value={modelPose} onChange={(e) => setModelPose(e.target.value as ModelPose)} className="w-full bg-slate-800 border border-slate-600 rounded-lg px-3 py-2 text-sm text-white focus:ring-1 focus:ring-indigo-500 focus:border-indigo-500 outline-none">
                                    <option value="Dáng đứng">Dáng đứng</option>
                                    <option value="Dáng đi">Dáng đi</option>
                                    <option value="Giới thiệu (Cầm móc)">Cầm móc áo</option>
                                    <option value="Giới thiệu (Chỉ mặc)">Chỉ mặc & Tạo dáng</option>
                                </select>
                            </div>
                            <div className="space-y-2">
                                <label className="text-xs font-medium text-slate-400 block">Bối cảnh</label>
                                <div className="relative">
                                    <input 
                                        type="text" 
                                        value={background} 
                                        onChange={(e) => setBackground(e.target.value)} 
                                        placeholder="VD: Đường phố Sài Gòn, Studio..."
                                        className="w-full bg-slate-800 border border-slate-600 rounded-lg pl-3 pr-10 py-2 text-sm text-white focus:ring-1 focus:ring-indigo-500 outline-none"
                                    />
                                    <button 
                                        onClick={handleGenerateBackground}
                                        disabled={isGeneratingBackground || !clothingType}
                                        className="absolute right-1 top-1 p-1.5 text-indigo-400 hover:text-indigo-300 disabled:opacity-50"
                                        title="Tự động gợi ý"
                                    >
                                        {isGeneratingBackground ? <LoadingSpinner className="w-4 h-4" /> : <SparklesIcon className="w-4 h-4" />}
                                    </button>
                                </div>
                            </div>
                        </div>
                    )}

                    {/* Number of Images Slider */}
                     <div className="space-y-2">
                        <div className="flex justify-between">
                             <label className="text-xs font-medium text-slate-400">Số lượng ảnh</label>
                             <span className="text-xs font-bold text-indigo-400">{numberOfImages}</span>
                        </div>
                        <input 
                            type="range" 
                            min="1" max="4" 
                            value={numberOfImages} 
                            onChange={(e) => setNumberOfImages(Number(e.target.value))}
                            className="w-full h-2 bg-slate-700 rounded-lg appearance-none cursor-pointer accent-indigo-500"
                        />
                    </div>

                    {/* Action Button */}
                    <button
                        onClick={handleGenerateClick}
                        disabled={isGenerateButtonDisabled()}
                        className="w-full py-4 bg-gradient-to-r from-indigo-600 to-purple-600 hover:from-indigo-500 hover:to-purple-500 text-white font-bold rounded-xl shadow-lg shadow-indigo-500/20 disabled:opacity-50 disabled:cursor-not-allowed transition-all duration-300 transform hover:scale-[1.02] active:scale-[0.98] flex items-center justify-center space-x-2"
                    >
                         {appState === 'PROCESSING' ? (
                             <>
                                <LoadingSpinner className="w-5 h-5" />
                                <span>Đang xử lý...</span>
                             </>
                         ) : (
                             <>
                                <SparklesIcon className="w-5 h-5" />
                                <span>Tạo ảnh ngay</span>
                             </>
                         )}
                    </button>
                </div>
            </div>
        </div>

        {/* Right Content: Results Gallery */}
        <div className="flex-1 bg-slate-900 overflow-y-auto p-4 md:p-8 flex flex-col items-center">

            {appState === 'IDLE' && (
                <div className="flex flex-col items-center justify-center h-full text-slate-500 space-y-4 opacity-60">
                    <div className="p-6 rounded-full bg-slate-800 border border-slate-700">
                        <SparklesIcon className="w-12 h-12" />
                    </div>
                    <p className="text-lg font-medium">Kết quả AI sẽ hiển thị tại đây</p>
                </div>
            )}

            {appState === 'PROCESSING' && (
                <div className="flex flex-col items-center justify-center h-full space-y-6">
                    <div className="relative">
                        <div className="absolute inset-0 bg-indigo-500 blur-xl opacity-20 animate-pulse rounded-full"></div>
                        <LoadingSpinner className="w-16 h-16 text-indigo-500 relative z-10" />
                    </div>
                    <div className="text-center space-y-2">
                        <h3 className="text-xl font-bold text-white">Đang sáng tạo...</h3>
                        <p className="text-slate-400 max-w-xs mx-auto">AI đang phân tích trang phục và tạo ra những bức ảnh tuyệt đẹp.</p>
                    </div>
                </div>
            )}

            {appState === 'ERROR' && (
                <div className="flex flex-col items-center justify-center h-full text-red-400 space-y-4">
                     <ErrorIcon className="w-16 h-16" />
                     <p className="text-lg font-medium">{error}</p>
                </div>
            )}

            {appState === 'SUCCESS' && (
                <div className="w-full max-w-6xl space-y-8 animate-fade-in">
                    <div className="flex items-center justify-between">
                        <h2 className="text-2xl font-bold text-white">Kết quả ({generatedResults.length})</h2>
                        <button onClick={handleGenerateClick} className="flex items-center space-x-2 text-indigo-400 hover:text-indigo-300 text-sm font-medium">
                            <RefreshIcon className="w-4 h-4" />
                            <span>Tạo lại</span>
                        </button>
                    </div>

                    <div className={`grid gap-6 ${generatedResults.length === 1 ? 'grid-cols-1 max-w-md mx-auto' : 'grid-cols-1 md:grid-cols-2 xl:grid-cols-3'}`}>
                        {generatedResults.map((item, index) => (
                            <div key={index} className="bg-slate-800 rounded-2xl p-3 border border-slate-700 hover:border-slate-500 transition-all duration-300 shadow-xl flex flex-col h-full group">
                                <div className="relative rounded-xl overflow-hidden aspect-[3/4] bg-slate-900 mb-3">
                                    <img src={item.url} alt="Generated" className="w-full h-full object-cover transform group-hover:scale-105 transition-transform duration-700" />
                                    <div className="absolute inset-0 bg-gradient-to-t from-black/60 via-transparent to-transparent opacity-0 group-hover:opacity-100 transition-opacity duration-300 flex flex-col justify-end p-4">
                                        <div className="flex space-x-2 justify-end">
                                            <button onClick={() => onEnhanceImage(item.url)} className="p-2 bg-white/10 backdrop-blur-md rounded-lg text-white hover:bg-white/20 transition-colors" title="Nâng cấp ảnh">
                                                <WandIcon className="w-5 h-5" />
                                            </button>
                                            <a href={item.url} download={`ai-result-${index}.jpg`} className="p-2 bg-indigo-600 rounded-lg text-white hover:bg-indigo-700 transition-colors" title="Tải xuống">
                                                <DownloadIcon className="w-5 h-5" />
                                            </a>
                                        </div>
                                    </div>
                                </div>
                                {item.videoPrompt && (
                                    <div className="bg-slate-900/50 rounded-lg p-3 border border-slate-700/50 mt-auto">
                                        <div className="flex items-center justify-between mb-2">
                                            <span className="text-[10px] font-bold text-indigo-400 uppercase tracking-wider">Veo 3.1 Prompt</span>
                                            <button onClick={() => handleCopyToClipboard(item.videoPrompt!, index)} className="text-slate-400 hover:text-white">
                                                {copiedPromptIndex === index ? <ClipboardCheckIcon className="w-3 h-3 text-green-400" /> : <ClipboardIcon className="w-3 h-3" />}
                                            </button>
                                        </div>
                                        <p className="text-xs text-slate-400 line-clamp-2 hover:line-clamp-none transition-all cursor-pointer" title={item.videoPrompt}>
                                            {item.videoPrompt}
                                        </p>
                                    </div>
                                )}
                            </div>
                        ))}
                    </div>
                </div>
            )}

        </div>
      </div>
    </div>
  );
};

export default ProductStudio;

import React, { useState, useCallback, useRef } from 'react';
import { generateLookbookImages, LookbookOptions, ModelPose, AspectRatio, LookbookResult, Ethnicity } from './services/geminiService';
import { UploadIcon, SparklesIcon, LoadingSpinner, ErrorIcon, ArrowLeftIcon, DownloadIcon, XIcon, PhotoIcon, ClipboardIcon, ClipboardCheckIcon, FilmIcon } from './components/Icons';

type AppState = 'IDLE' | 'PROCESSING' | 'SUCCESS' | 'ERROR';
type ClothingType = 'Áo' | 'Quần' | 'Cả bộ' | 'Váy';
type Gender = 'Nam' | 'Nữ';

interface LookbookGeneratorProps {
  onGoBack: () => void;
}

const LookbookGenerator: React.FC<LookbookGeneratorProps> = ({ onGoBack }) => {
  const [originalImageFile, setOriginalImageFile] = useState<File | null>(null);
  const [originalImageUrl, setOriginalImageUrl] = useState<string | null>(null);
  const [generatedLookbookItems, setGeneratedLookbookItems] = useState<LookbookResult[]>([]);
  const [appState, setAppState] = useState<AppState>('IDLE');
  const [error, setError] = useState<string | null>(null);
  const [copiedPromptIndex, setCopiedPromptIndex] = useState<number | null>(null);

  // Settings
  const [clothingType, setClothingType] = useState<ClothingType>('Áo');
  const [aspectRatio, setAspectRatio] = useState<AspectRatio>('9:16');
  const [gender, setGender] = useState<Gender>('Nữ');
  const [ethnicity, setEthnicity] = useState<Ethnicity>('Việt Nam');
  const [age, setAge] = useState<string>('18-25');
  const [theme, setTheme] = useState<string>('');
  const [additionalPrompt, setAdditionalPrompt] = useState<string>('');
  const [numberOfImages, setNumberOfImages] = useState<number>(4);
  const [modelPose, setModelPose] = useState<ModelPose>('Dáng đứng');
  const [generateVideo, setGenerateVideo] = useState<boolean>(false);

  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFileChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (file) {
      if (!file.type.startsWith('image/')) {
        setError('Vui lòng chọn một tệp hình ảnh.');
        setAppState('ERROR');
        return;
      }
      setGeneratedLookbookItems([]);
      setError(null);
      setAppState('IDLE');
      setOriginalImageFile(file);
      setOriginalImageUrl(URL.createObjectURL(file));
    }
  };

  const handleRemoveImage = (e: React.MouseEvent) => {
    e.stopPropagation();
    setOriginalImageFile(null);
    setOriginalImageUrl(null);
    setGeneratedLookbookItems([]);
    setError(null);
    setAppState('IDLE');
    if (fileInputRef.current) {
        fileInputRef.current.value = "";
    }
  };

  const handleGenerateClick = useCallback(async () => {
    if (!originalImageFile || !theme.trim()) {
        setError('Vui lòng tải ảnh lên và nhập chủ đề.');
        setAppState('ERROR');
        return;
    }

    setAppState('PROCESSING');
    setError(null);
    setGeneratedLookbookItems([]);

    try {
      const reader = new FileReader();
      reader.readAsDataURL(originalImageFile);
      reader.onloadend = async () => {
        const base64String = (reader.result as string).split(',')[1];
        if (!base64String) throw new Error('Cannot process image');

        const options: LookbookOptions = {
            clothingType,
            gender,
            age,
            theme,
            additionalPrompt,
            numberOfImages,
            pose: modelPose,
            aspectRatio,
            generateVideo,
            ethnicity
        };
        const generatedItems = await generateLookbookImages(base64String, originalImageFile.type, options);
        setGeneratedLookbookItems(generatedItems);
        setAppState('SUCCESS');
      };
    } catch (err: any) {
      console.error(err);
      setError(err.message || 'Đã xảy ra lỗi.');
      setAppState('ERROR');
    }
  }, [originalImageFile, clothingType, gender, ethnicity, age, theme, additionalPrompt, numberOfImages, modelPose, aspectRatio, generateVideo]);

  const triggerFileInput = () => {
    fileInputRef.current?.click();
  };

  const handleCopyToClipboard = (textToCopy: string, index: number) => {
    navigator.clipboard.writeText(textToCopy);
    setCopiedPromptIndex(index);
    setTimeout(() => setCopiedPromptIndex(null), 2000);
  };

  const isGenerateButtonDisabled = () => {
    return appState === 'PROCESSING' || !originalImageFile || !theme.trim();
  }

  return (
    <div className="flex flex-col h-screen overflow-hidden bg-slate-900 text-slate-200">
       <header className="flex-none h-16 border-b border-slate-700 bg-slate-800/50 backdrop-blur-md flex items-center px-6 justify-between z-20">
        <div className="flex items-center">
            <button onClick={onGoBack} className="flex items-center text-slate-400 hover:text-white transition-colors mr-4">
                <ArrowLeftIcon className="w-5 h-5 mr-2"/>
                <span className="font-medium">Trang chủ</span>
            </button>
            <div className="h-6 w-px bg-slate-700 mx-4"></div>
            <h1 className="text-lg font-bold text-white tracking-tight">Lookbook Generator</h1>
        </div>
      </header>

      <div className="flex-1 flex overflow-hidden">
        {/* Left Sidebar */}
        <div className="w-full md:w-[400px] lg:w-[450px] flex-none border-r border-slate-700 bg-slate-800/50 overflow-y-auto custom-scrollbar">
             <div className="p-6 space-y-8">
                {/* Image Upload */}
                <div className="space-y-3">
                    <h2 className="text-sm font-bold text-slate-400 uppercase tracking-wider">1. Sản phẩm</h2>
                    <input type="file" ref={fileInputRef} onChange={handleFileChange} accept="image/*" className="hidden" />
                    <div 
                        onClick={!originalImageUrl ? triggerFileInput : undefined}
                        className={`relative aspect-[3/4] w-full rounded-xl border-2 border-dashed transition-all duration-300 flex flex-col items-center justify-center overflow-hidden cursor-pointer
                            ${originalImageUrl ? 'border-pink-500 bg-slate-800' : 'border-slate-600 bg-slate-800/50 hover:border-pink-400 hover:bg-slate-700'}
                        `}
                    >
                        {originalImageUrl ? (
                            <>
                                <img src={originalImageUrl} alt="Upload" className="w-full h-full object-contain" />
                                <button onClick={handleRemoveImage} className="absolute top-2 right-2 bg-slate-900/80 text-white p-2 rounded-full hover:bg-red-500 transition-colors">
                                    <XIcon className="w-4 h-4" />
                                </button>
                            </>
                        ) : (
                            <div className="text-center p-6">
                                <UploadIcon className="w-10 h-10 text-slate-500 mx-auto mb-3" />
                                <p className="text-slate-300 font-medium">Tải ảnh sản phẩm</p>
                            </div>
                        )}
                    </div>
                     <div className="flex flex-wrap gap-2 mt-2">
                        {(['Áo', 'Quần', 'Cả bộ', 'Váy'] as ClothingType[]).map((type) => (
                            <button key={type} onClick={() => setClothingType(type)} className={`px-3 py-1.5 rounded-full text-xs font-medium border transition-all ${clothingType === type ? 'bg-pink-500/20 border-pink-500 text-pink-300' : 'bg-slate-800 border-slate-700 text-slate-400'}`}>
                                {type}
                            </button>
                        ))}
                    </div>
                </div>

                {/* Settings */}
                <div className={`space-y-6 transition-opacity duration-300 ${!originalImageFile ? 'opacity-50 pointer-events-none' : ''}`}>
                    <h2 className="text-sm font-bold text-slate-400 uppercase tracking-wider">2. Cấu hình Lookbook</h2>

                    <div className="space-y-4 p-5 bg-slate-900/50 rounded-xl border border-slate-700">
                        {/* Theme Input */}
                        <div>
                             <label className="text-xs font-bold text-pink-400 block mb-2 uppercase">Chủ đề (Concept) *</label>
                             <textarea 
                                value={theme}
                                onChange={(e) => setTheme(e.target.value)}
                                placeholder="VD: Dạo phố mùa thu lãng mạn, tone màu be, ánh nắng nhẹ..."
                                rows={3}
                                className="w-full bg-slate-800 border border-slate-600 rounded-lg p-3 text-sm text-white focus:ring-1 focus:ring-pink-500 outline-none"
                            />
                        </div>

                         <div className="grid grid-cols-2 gap-4">
                            <div>
                                <label className="text-xs font-medium text-slate-400 block mb-1.5">Quốc tịch Model</label>
                                <select value={ethnicity} onChange={(e) => setEthnicity(e.target.value as Ethnicity)} className="w-full bg-slate-800 border border-slate-600 rounded-lg px-3 py-2 text-sm text-white focus:ring-1 focus:ring-pink-500 outline-none">
                                    <option value="Việt Nam">Việt Nam</option>
                                    <option value="Hàn Quốc">Hàn Quốc</option>
                                </select>
                            </div>
                             <div>
                                <label className="text-xs font-medium text-slate-400 block mb-1.5">Độ tuổi</label>
                                <select value={age} onChange={(e) => setAge(e.target.value)} className="w-full bg-slate-800 border border-slate-600 rounded-lg px-3 py-2 text-sm text-white focus:ring-1 focus:ring-pink-500 outline-none">
                                    <option value="18-25">18-25</option>
                                    <option value="26-35">26-35</option>
                                </select>
                            </div>
                         </div>

                         <div>
                            <label className="flex items-center space-x-3 cursor-pointer p-3 rounded-lg bg-slate-800 border border-slate-700 hover:border-pink-500/50 transition-colors">
                                <input 
                                    type="checkbox" 
                                    checked={generateVideo} 
                                    onChange={(e) => setGenerateVideo(e.target.checked)}
                                    className="h-5 w-5 rounded border-slate-500 text-pink-600 focus:ring-pink-500 bg-slate-900"
                                />
                                <div className="flex flex-col">
                                    <span className="text-sm font-medium text-white flex items-center">
                                        <FilmIcon className="w-4 h-4 mr-2 text-pink-500" />
                                        Tạo kèm Video Prompt
                                    </span>
                                    <span className="text-[10px] text-slate-500">Tối ưu cho Google Veo 3.1</span>
                                </div>
                            </label>
                        </div>
                    </div>

                    <button
                        onClick={handleGenerateClick}
                        disabled={isGenerateButtonDisabled()}
                        className="w-full py-4 bg-gradient-to-r from-pink-600 to-rose-600 hover:from-pink-500 hover:to-rose-500 text-white font-bold rounded-xl shadow-lg shadow-pink-500/20 disabled:opacity-50 disabled:cursor-not-allowed transition-all duration-300 transform hover:scale-[1.02] flex items-center justify-center space-x-2"
                    >
                         {appState === 'PROCESSING' ? (
                             <>
                                <LoadingSpinner className="w-5 h-5" />
                                <span>Đang sáng tạo...</span>
                             </>
                         ) : (
                             <>
                                <PhotoIcon className="w-5 h-5" />
                                <span>Tạo Collection</span>
                             </>
                         )}
                    </button>
                </div>
             </div>
        </div>

        {/* Right Content */}
        <div className="flex-1 bg-slate-900 overflow-y-auto p-4 md:p-8 flex flex-col items-center">
            {appState === 'SUCCESS' && generatedLookbookItems.length > 0 ? (
                <div className="w-full max-w-6xl space-y-6 animate-fade-in">
                    <h2 className="text-2xl font-bold text-white mb-6">Bộ sưu tập Lookbook</h2>
                    <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-4 gap-4">
                        {generatedLookbookItems.map((item, index) => (
                            <div key={index} className="bg-slate-800 rounded-xl overflow-hidden shadow-xl border border-slate-700 group">
                                <div className="relative aspect-[9/16]">
                                    <img src={item.imageUrl} alt="Result" className="w-full h-full object-cover" />
                                    <a href={item.imageUrl} download={`lookbook-${index}.jpg`} className="absolute top-2 right-2 bg-black/60 text-white p-2 rounded-full opacity-0 group-hover:opacity-100 transition-opacity">
                                        <DownloadIcon className="w-5 h-5"/>
                                    </a>
                                </div>
                                {item.videoPrompt && (
                                    <div className="p-3 bg-slate-900 border-t border-slate-700">
                                        <div className="flex justify-between items-center mb-1">
                                            <span className="text-[10px] font-bold text-pink-500">VIDEO PROMPT</span>
