export const generateBackgroundSuggestion = async (base64Image: string, mimeType: string, clothingType: string): Promise<string> => {
    try {
        const model = 'gemini-2.5-flash';
        const prompt = `Suggest a short, artistic background description (under 20 words) suitable for a fashion photo of this ${clothingType}. In Vietnamese.`;

        const response = await ai.models.generateContent({
            model,
            contents: {
                parts: [fileToPart(base64Image, mimeType), { text: prompt }]
            }
        });
        return response.text || "";
    } catch (e) {
        console.error("Generate Background Error", e);
        return "Phông nền studio chuyên nghiệp";
    }
}

export const generateStyledImage = async (base64Image: string, mimeType: string, clothingType: string, aspectRatio: AspectRatio, displayMode: ProductDisplayMode, count: number): Promise<string[]> => {
    const results: string[] = [];

    // Updated randomization for Flatlay: Full frame background colors and simple textures
    const pastelColors = ['pastel pink', 'mint green', 'cream', 'light lavender', 'neutral beige', 'soft white'];
    const textures = ['soft wave pattern', 'subtle geometric texture', 'plush texture', 'minimalist ribbed texture'];

    for(let i=0; i<count; i++) {
        try {
            let prompt = `Generate a professional product photo of this ${clothingType}. `;

            if (displayMode === 'flatlay') {
                const color = pastelColors[Math.floor(Math.random() * pastelColors.length)];
                const texture = textures[i % textures.length];

                prompt += `Placement: Flatlay. Background: A luxurious ${color} fur or soft fabric background that fills the entire frame edge-to-edge. Texture: ${texture} to add subtle detail. Style: Ultra-minimalist, clean, focus solely on the product. No extra props. View: Top-down. Lighting: Bright, high-key studio lighting, no shadows.`;
            } else {
                prompt += `Display mode: Hanging on a rack or shelf. Aspect Ratio: ${aspectRatio}. High quality bright studio lighting.`;
            }

            // Quality enhancement keywords
            prompt += ` Quality: 2k resolution, ultra-sharp focus, highly detailed texture, bright and airy colors, white balance, photorealistic masterpiece, no blur.`;

            const response = await ai.models.generateContent({
                model: 'gemini-2.5-flash-image',
                contents: {
                    parts: [
                        fileToPart(base64Image, mimeType),
                        { text: prompt }
                    ]
                }
            });

            if(response.candidates?.[0]?.content?.parts) {
                for (const part of response.candidates[0].content.parts) {
                    if (part.inlineData && part.inlineData.data) {
                        results.push(part.inlineData.data);
                        break; 
                    }
                }
            }
        } catch (e) {
            console.error(`Error generating image ${i+1}:`, e);
        }
    }

    if (results.length === 0) {
        throw new Error("Không thể tạo ảnh. Vui lòng thử lại sau.");
    }
    return results;
}

export const generateModelImage = async (base64Image: string, mimeType: string, options: ModelImageOptions): Promise<{imageUrl: string, videoPrompt: string}[]> => {
    const results: {imageUrl: string, videoPrompt: string}[] = [];
    const genderEn = options.gender === 'Nam' ? 'male' : 'female';
    const beautyTerms = options.gender === 'Nam' ? 'handsome, K-pop idol style' : 'very beautiful, angelic face';

    for(let i=0; i<options.numberOfImages; i++) {
        try {
             // Enforce Front Facing, Fair Skin, Beautiful Face, Smiling Gently
             const prompt = `Fashion photography. A ${options.age} year old Vietnamese ${genderEn} model (${beautyTerms}, fair white skin, glowing skin, flawless face, black hair, smiling gently, happy friendly expression) wearing this ${options.clothingType}. 
             Pose: Front facing, looking directly at the camera, symmetric composition. 
             Background: ${options.background}. Aspect Ratio: ${options.aspectRatio}. 
             Lighting: Bright studio lighting, high-key, soft shadows, clean white balance, bright and sharp.
             Quality: 2k resolution, ultra-sharp details, high fidelity, depth of field, photorealistic, 8k uhd. Ensure the clothing looks exactly like the reference image.`;

             const response = await ai.models.generateContent({
                model: 'gemini-2.5-flash-image', 
                contents: {
                    parts: [
                        fileToPart(base64Image, mimeType),
                        { text: prompt }
                    ]
                }
            });

            let imageUrl = "";
            if(response.candidates?.[0]?.content?.parts) {
                 for (const part of response.candidates[0].content.parts) {
                    if (part.inlineData && part.inlineData.data) {
                        imageUrl = `data:image/jpeg;base64,${part.inlineData.data}`;
                        break; 
                    }
                }
            }

            if(imageUrl) {
                 const videoPrompt = `Cinematic shot of a beautiful Vietnamese ${genderEn} model with fair skin in ${options.background}, wearing ${options.clothingType}, front facing, smiling gently, 4k resolution, slow motion, bright lighting.`;
                 results.push({ imageUrl, videoPrompt });
            }
        } catch (e) {
            console.error(`Error generating model image ${i+1}:`, e);
        }
    }

    if (results.length === 0) {
        throw new Error("Không thể tạo ảnh người mẫu. Vui lòng kiểm tra lại ảnh đầu vào.");
    }
    return results;
}

export const generateSelfieImage = async (base64Image: string, mimeType: string, clothingType: string, count: number): Promise<string[]> => {
    const results: string[] = [];

    for(let i=0; i<count; i++) {
