            // Enforce Fair Skin, Front Facing, Smiling Gently
            const prompt = `Mirror selfie fashion shot. A 20-25 year old Asian female model (fair white skin, beautiful face, glowing skin, cute, smiling gently, happy expression) wearing this ${clothingType}. 
