    if (!text.trim()) {
        setError('Vui lòng nhập văn bản cần đọc.');
        setAppState('ERROR');
        return;
    }

    setAppState('PROCESSING');
    setError(null);
    setAudioUrl(null);

    try {
        const wavBlob = await generateSpeech(text, selectedVoice.id);
        const url = URL.createObjectURL(wavBlob);
        setAudioUrl(url);
        setAppState('SUCCESS');
