                                        {voice.label}
                                    </div>
                                    <div className="text-xs text-slate-500 mt-0.5">{voice.description}</div>
                                </div>
                            </button>
                        ))}
                    </div>
                </div>

                {/* Generate Button */}
                <button
                    onClick={handleGenerate}
                    disabled={appState === 'PROCESSING' || !text.trim()}
                    className="w-full py-4 bg-gradient-to-r from-teal-600 to-emerald-600 hover:from-teal-500 hover:to-emerald-500 text-white font-bold rounded-xl shadow-lg shadow-teal-500/20 disabled:opacity-50 disabled:cursor-not-allowed transition-all transform hover:scale-[1.02] flex items-center justify-center space-x-2"
                >
                     {appState === 'PROCESSING' ? (
                         <>
                            <LoadingSpinner className="w-5 h-5" />
                            <span>Đang xử lý...</span>
                         </>
                     ) : (
                         <>
                            <WaveformIcon className="w-5 h-5" />
                            <span>Tạo giọng nói</span>
                         </>
                     )}
                </button>
             </div>
        </div>

        {/* Right Content: Player & Visualization */}
        <div className="flex-1 bg-slate-900 overflow-y-auto p-4 md:p-8 flex flex-col items-center justify-center">
            {appState === 'IDLE' && (
                <div className="flex flex-col items-center justify-center text-slate-600 space-y-4">
                     <WaveformIcon className="w-20 h-20 opacity-20" />
                     <p>Nhập văn bản và chọn giọng đọc để bắt đầu</p>
                </div>
            )}

            {appState === 'PROCESSING' && (
                <div className="text-center">
                    <LoadingSpinner className="w-16 h-16 text-teal-500 mx-auto mb-6" />
                    <p className="text-xl font-medium text-white">Đang chuyển đổi văn bản...</p>
                    <p className="text-slate-400 text-sm mt-2">AI đang tạo ngữ điệu tự nhiên</p>
                </div>
            )}

             {appState === 'ERROR' && (
                <div className="text-center text-red-400 max-w-md">
                     <ErrorIcon className="w-16 h-16 mx-auto mb-4" />
                     <h3 className="text-lg font-bold mb-2">Đã xảy ra lỗi</h3>
                     <p>{error}</p>
                </div>
            )}

            {appState === 'SUCCESS' && audioUrl && (
                <div className="w-full max-w-2xl bg-slate-800 rounded-3xl p-8 border border-slate-700 shadow-2xl animate-fade-in-up">
                    <div className="flex items-center justify-between mb-8">
                         <div className="flex items-center space-x-4">
                            <div className="w-12 h-12 rounded-full bg-teal-500 flex items-center justify-center shadow-lg shadow-teal-500/20">
                                <PlayIcon className="w-6 h-6 text-white" />
                            </div>
                            <div>
                                <h2 className="text-xl font-bold text-white">Kết quả giọng đọc</h2>
                                <p className="text-teal-400 text-sm">{selectedVoice.label}</p>
                            </div>
                         </div>
                    </div>

                    <div className="bg-slate-900 rounded-xl p-4 mb-8 flex items-center justify-center min-h-[120px]">
                        {/* Audio Visualization Mockup */}
                        <div className="flex items-center justify-center space-x-1 h-16 w-full px-8">
                             {[...Array(20)].map((_, i) => (
                                <div 
                                    key={i} 
                                    className="w-2 bg-teal-500 rounded-full animate-pulse" 
                                    style={{ 
                                        height: `${Math.random() * 100}%`,
                                        animationDelay: `${i * 0.05}s`,
                                        animationDuration: '0.8s'
                                    }}
                                ></div>
                             ))}
                        </div>
                    </div>

                    <audio 
                        ref={audioRef} 
                        src={audioUrl} 
                        controls 
                        className="w-full mb-6 accent-teal-500"
                        style={{ filter: 'invert(1) hue-rotate(180deg)' }} // Simple trick to style default audio player dark
                    />

                    <div className="flex justify-center">
                        <a 
                            href={audioUrl} 
                            download={`tts-${selectedVoice.id}-${Date.now()}.wav`}
                            className="flex items-center space-x-2 px-8 py-3 bg-slate-700 hover:bg-teal-600 text-white font-bold rounded-full transition-all hover:shadow-lg hover:shadow-teal-500/20"
                        >
                            <DownloadIcon className="w-5 h-5" />
                            <span>Tải xuống (WAV)</span>
                        </a>
                    </div>
                </div>
            )}
        </div>
      </div>
    </div>
  );
};

export default TextToSpeechGenerator;

