import React, { useState, useCallback, useRef, useEffect } from 'react';
import { generateSpeech } from './services/geminiService';
import { WaveformIcon, SparklesIcon, LoadingSpinner, ErrorIcon, ArrowLeftIcon, DownloadIcon, PlayIcon, SpeakerWaveIcon, StopIcon } from './components/Icons';

type AppState = 'IDLE' | 'PROCESSING' | 'SUCCESS' | 'ERROR';
type GenderFilter = 'All' | 'Nam' | 'Nữ';

interface TextToSpeechGeneratorProps {
  onGoBack: () => void;
}

interface VoiceOption {
    id: string; // The internal Gemini voice name (Puck, Kore, etc.)
    label: string;
    description: string;
    gender: 'Nam' | 'Nữ';
    tags: string[]; // Use case tags: Review, Vlog, Story, News
}

const VOICE_OPTIONS: VoiceOption[] = [
    { 
        id: 'Puck', 
        label: 'Nam - Năng động (Review/Shorts)', 
        description: 'Tốc độ nhanh, hào hứng, phù hợp video Review, TikTok.', 
        gender: 'Nam',
