        description: 'Giọng cao, chuyên nghiệp, rõ ràng, phù hợp Tin tức, Podcast.', 
        gender: 'Nữ',
        tags: ['Tin tức', 'Podcast', 'Thuyết trình'] 
    },
    { 
        id: 'Fenrir', 
        label: 'Nam - Trầm ấm (Kể chuyện)', 
        description: 'Giọng dày, nam tính, điện ảnh, phù hợp Kể chuyện ma, Phim.', 
        gender: 'Nam',
        tags: ['Kể chuyện', 'Phim', 'Sách nói'] 
    },
