                prompt += `Display mode: Hanging on a rack or shelf. Aspect Ratio: ${aspectRatio}. High quality bright studio lighting.`;
            }

            // Quality enhancement keywords
            prompt += ` Quality: 2k resolution, ultra-sharp focus, highly detailed texture, bright and airy colors, white balance, photorealistic masterpiece, no blur.`;

            const response = await ai.models.generateContent({
                model: 'gemini-2.5-flash-image',
                contents: {
                    parts: [
                        fileToPart(base64Image, mimeType),
                        { text: prompt }
                    ]
                }
            });

            if(response.candidates?.[0]?.content?.parts) {
                for (const part of response.candidates[0].content.parts) {
                    if (part.inlineData && part.inlineData.data) {
                        results.push(part.inlineData.data);
                        break; 
