export const generateSpeech = async (text: string, voiceName: string): Promise<Blob> => {
    try {
        // Force the model to read in Vietnamese naturally
        const prompt = `Read the following text in Vietnamese naturally, with emotion: "${text}"`;

        const response = await ai.models.generateContent({
            model: 'gemini-2.5-flash-preview-tts',
            contents: {
                parts: [{ text: prompt }]
            },
            config: {
                responseModalities: [Modality.AUDIO],
                speechConfig: {
                    voiceConfig: {
                        prebuiltVoiceConfig: { voiceName: voiceName }
                    }
                }
            }
        });

        const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
        if (!base64Audio) {
            throw new Error("No audio data returned");
        }

        // Convert base64 to PCM ArrayBuffer
        const pcmBuffer = base64ToArrayBuffer(base64Audio);

        // Convert PCM to WAV Blob for easy playback and download
        // Gemini TTS typically returns 24kHz mono PCM
        return pcmToWav(pcmBuffer, 24000, 1);
    } catch (e) {
        console.error("Generate Speech Error", e);
        throw new Error("Không thể tạo giọng nói. Vui lòng thử lại.");
    }
}

import React, { useState, useCallback, useRef } from 'react';
import { generateStyledImage, generateModelImage, generateSelfieImage, ModelPose, AspectRatio, generateBackgroundSuggestion, ProductDisplayMode, SelfieFraming, RugStyle, RugColor, RugPattern } from './services/geminiService';
import { UploadIcon, SparklesIcon, LoadingSpinner, ErrorIcon, HangerIcon, UserIcon, ArrowLeftIcon, DownloadIcon, XIcon, RefreshIcon, WandIcon, ClipboardIcon, ClipboardCheckIcon, CameraIcon, ZoomInIcon } from './components/Icons';

type AppState = 'IDLE' | 'PROCESSING' | 'SUCCESS' | 'ERROR';
type ClothingType = 'Áo' | 'Quần' | 'Cả bộ' | 'Váy' | 'Phụ kiện';
type FeatureMode = 'product' | 'model' | 'selfie';
type Gender = 'Nam' | 'Nữ';

interface ResultItem {
    id: string;
    url: string;
    videoPrompt?: string;
}

interface ProductStudioProps {
  onGoBack: () => void;
  onEnhanceImage: (imageUrl: string) => void;
}

const ProductStudio: React.FC<ProductStudioProps> = ({ onGoBack, onEnhanceImage }) => {
  // Core state
  const [originalImageFile, setOriginalImageFile] = useState<File | null>(null);
  const [originalImageUrl, setOriginalImageUrl] = useState<string | null>(null);
  const [generatedResults, setGeneratedResults] = useState<ResultItem[]>([]);
  const [appState, setAppState] = useState<AppState>('IDLE');
  const [error, setError] = useState<string | null>(null);
  const [zoomImage, setZoomImage] = useState<string | null>(null);

  // Feature selection state
  const [featureMode, setFeatureMode] = useState<FeatureMode>('product');
  const [clothingType, setClothingType] = useState<ClothingType>('Áo');
  const [aspectRatio, setAspectRatio] = useState<AspectRatio>('9:16');
  const [productDisplayMode, setProductDisplayMode] = useState<ProductDisplayMode>('hanger');

  // Flatlay Rug State
  const [rugStyle, setRugStyle] = useState<RugStyle>('Tự động');
  const [rugColor, setRugColor] = useState<RugColor>('Tự động');
  const [rugPattern, setRugPattern] = useState<RugPattern>('Tự động');

  // Model-specific state
  const [gender, setGender] = useState<Gender>('Nữ');
  const [age, setAge] = useState<string>('18-25');
  const [background, setBackground] = useState<string>('');
  const [numberOfImages, setNumberOfImages] = useState<number>(1);
  const [modelPose, setModelPose] = useState<ModelPose>('Dáng đứng');
  const [isGeneratingBackground, setIsGeneratingBackground] = useState<boolean>(false);
  const [copiedPromptIndex, setCopiedPromptIndex] = useState<number | null>(null);

  // Selfie specific state
  const [selfieFraming, setSelfieFraming] = useState<SelfieFraming>('Nửa thân');

  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFileChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (file) {
      if (!file.type.startsWith('image/')) {
        setError('Vui lòng chọn một tệp hình ảnh.');
        setAppState('ERROR');
        return;
      }
      setGeneratedResults([]);
      setError(null);
      setAppState('IDLE');
      setOriginalImageFile(file);
      setOriginalImageUrl(URL.createObjectURL(file));
    }
  };

  const handleRemoveImage = (e: React.MouseEvent) => {
    e.stopPropagation();
    setOriginalImageFile(null);
    setOriginalImageUrl(null);
    setGeneratedResults([]);
    setError(null);
    setAppState('IDLE');
    if (fileInputRef.current) {
        fileInputRef.current.value = "";
    }
  };

  const handleGenerateBackground = async () => {
    if (!originalImageFile || !clothingType) return;

    setIsGeneratingBackground(true);
    setError(null);

    const reader = new FileReader();
    reader.readAsDataURL(originalImageFile);
    reader.onloadend = async () => {
        try {
            const base64String = (reader.result as string).split(',')[1];
            if (!base64String) throw new Error('Cannot read file');
            const suggestion = await generateBackgroundSuggestion(base64String, originalImageFile.type, clothingType);
            setBackground(suggestion.trim().replace(/^"|"$/g, '')); 
        } catch (err: any) {
          setError(err.message || 'Error generating background.');
        } finally {
            setIsGeneratingBackground(false);
        }
    };
  };

  const generateId = (prefix: string) => {
      return `${prefix}_${Date.now()}_${Math.random().toString(36).substr(2, 6)}`;
  };

  const handleGenerateClick = useCallback(async () => {
    if (!originalImageFile || !clothingType || !featureMode) return;

    if(featureMode === 'model' && !background.trim()){
        setError('Vui lòng nhập mô tả bối cảnh.');
        setAppState('ERROR');
        return;
    }

    setAppState('PROCESSING');
    setError(null);
    setGeneratedResults([]);


    try {
      const reader = new FileReader();
      reader.readAsDataURL(originalImageFile);
      reader.onloadend = async () => {
        const base64String = (reader.result as string).split(',')[1];
        if (!base64String) throw new Error('Error processing image');

        if (featureMode === 'product') {
            const generatedImages = await generateStyledImage(
                base64String, 
                originalImageFile.type, 
                clothingType, 
                aspectRatio, 
                productDisplayMode, 
                numberOfImages,
                // Pass rug options if mode is flatlay
                productDisplayMode === 'flatlay' ? { style: rugStyle, color: rugColor, pattern: rugPattern } : undefined
            );
            setGeneratedResults(generatedImages.map(url => ({ 
                id: generateId('product'),
                url: `data:image/jpeg;base64,${url}` 
            })));
        } else if (featureMode === 'model') { 
            const generatedImages = await generateModelImage(base64String, originalImageFile.type, {
                clothingType,
                gender,
                age,
                background,
                numberOfImages,
                pose: modelPose,
                aspectRatio,
            });
            setGeneratedResults(generatedImages.map(item => ({
                id: generateId('model'),
                url: item.imageUrl,
                videoPrompt: item.videoPrompt
            })));
        } else if (featureMode === 'selfie') {
             const generatedImages = await generateSelfieImage(base64String, originalImageFile.type, clothingType, numberOfImages, gender, selfieFraming);
             setGeneratedResults(generatedImages.map(url => ({ 
                id: generateId('selfie'),
                url: `data:image/jpeg;base64,${url}` 
            })));
        }

        setAppState('SUCCESS');
      };
    } catch (err: any) {
      console.error(err);
      setError(err.message || 'Đã xảy ra lỗi không mong muốn.');
      setAppState('ERROR');
    }
  }, [originalImageFile, featureMode, clothingType, gender, age, background, numberOfImages, modelPose, aspectRatio, productDisplayMode, selfieFraming, rugStyle, rugColor, rugPattern]);

  const triggerFileInput = () => {
    fileInputRef.current?.click();
  };

  const handleCopyToClipboard = (textToCopy: string, index: number) => {
    navigator.clipboard.writeText(textToCopy);
    setCopiedPromptIndex(index);
    setTimeout(() => setCopiedPromptIndex(null), 2000);
  };

  const isGenerateButtonDisabled = () => {
    if (appState === 'PROCESSING' || !originalImageFile) return true;
    if (featureMode === 'model' && !background.trim()) return true;
    return false;
  }

  return (
    <div className="flex flex-col h-screen overflow-hidden bg-slate-900 text-slate-200">
      {/* Zoom Modal */}
      {zoomImage && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/90 backdrop-blur-sm p-4 animate-fade-in" onClick={() => setZoomImage(null)}>
            <button className="absolute top-4 right-4 text-white hover:text-gray-300 p-2 bg-white/10 rounded-full" onClick={() => setZoomImage(null)}>
                <XIcon className="w-8 h-8" />
            </button>
            <img src={zoomImage} alt="Zoom" className="max-w-full max-h-[90vh] object-contain rounded-lg shadow-2xl" onClick={(e) => e.stopPropagation()} />
        </div>
      )}

      {/* Header */}
      <header className="flex-none h-16 border-b border-slate-700 bg-slate-800/50 backdrop-blur-md flex items-center px-6 justify-between z-20">
        <div className="flex items-center">
            <button onClick={onGoBack} className="flex items-center text-slate-400 hover:text-white transition-colors mr-4">
                <ArrowLeftIcon className="w-5 h-5 mr-2"/>
                <span className="font-medium">Trang chủ</span>
            </button>
            <div className="h-6 w-px bg-slate-700 mx-4"></div>
            <h1 className="text-lg font-bold text-white tracking-tight">Studio Sản phẩm AI</h1>
        </div>
        <div className="flex items-center space-x-2">
            <span className="text-xs text-indigo-400 font-mono bg-indigo-500/10 px-2 py-1 rounded border border-indigo-500/20">GEMINI 2.5 FLASH</span>
        </div>
      </header>

      {/* Main Layout */}
      <div className="flex-1 flex overflow-hidden">

        {/* Left Sidebar: Controls */}
        <div className="w-full md:w-[400px] lg:w-[450px] flex-none border-r border-slate-700 bg-slate-800/50 overflow-y-auto custom-scrollbar">
            <div className="p-6 space-y-8">

                {/* 1. Image Upload */}
                <div className="space-y-3">
                    <h2 className="text-sm font-bold text-slate-400 uppercase tracking-wider">1. Ảnh gốc</h2>
                    <input type="file" ref={fileInputRef} onChange={handleFileChange} accept="image/*" className="hidden" />
                    <div 
