                    rugStylePrompt = styleMap[rugOptions.style] || rugOptions.style;
                }

                // Color Logic
                if (!rugOptions || rugOptions.color === 'Tự động') {
                    rugColorPrompt = "a color that provides excellent contrast to the product (e.g. if product is dark use light rug, if product is light use subtle pastel or neutral rug)";
                } else {
                    const colorMap: Record<string, string> = {
                        'Trắng/Kem': 'creamy white',
                        'Be (Beige)': 'warm beige',
                        'Xám': 'neutral grey',
                        'Pastel': 'soft pastel',
                        'Tối màu': 'dark elegant charcoal'
                    };
                    rugColorPrompt = colorMap[rugOptions.color] || rugOptions.color;
                }

                // Pattern Logic
                if (!rugOptions || rugOptions.pattern === 'Tự động') {
                    rugPatternPrompt = "a subtle texture or pattern that adds depth without being distracting";
                } else {
                     const patternMap: Record<string, string> = {
                        'Trơn (Solid)': 'solid color with texture only (no print)',
                        'Hình học (Geometric)': 'modern geometric lines pattern',
                        'Vân sóng': 'gentle wavy curves pattern',
                        'Trừu tượng': 'artistic abstract shapes'
                    };
                    rugPatternPrompt = patternMap[rugOptions.pattern] || rugOptions.pattern;
                }

                prompt += `Placement: Flatlay top-down view. 
                Background: The product is laid flat centrally on a ${rugColorPrompt} ${rugStylePrompt} rug.
                Rug Details: The rug features ${rugPatternPrompt}.
                Key Requirement: The product must be the ABSOLUTE HIGHLIGHT. The rug is background only. Ensure sharp focus on the clothing item. High contrast between product and rug.
                Lighting: Bright, natural, high-key studio lighting, soft shadows, creating a cozy and expensive look.`;
            } else {
                prompt += `Display mode: Hanging on a rack or shelf. Aspect Ratio: ${aspectRatio}. High quality bright studio lighting.`;
            }

            // Quality enhancement keywords
            prompt += ` Quality: 2k resolution, ultra-sharp focus, highly detailed texture, bright and airy colors, white balance, photorealistic masterpiece, no blur.`;

            const response = await ai.models.generateContent({
                model,
                contents: {
                    parts: [
                        fileToPart(base64Image, mimeType),
                        { text: prompt }
                    ]
                }
            });

            if(response.candidates?.[0]?.content?.parts) {
                for (const part of response.candidates[0].content.parts) {
                    if (part.inlineData && part.inlineData.data) {
                        results.push(part.inlineData.data);
                        break; 
                    }
                }
            }
        } catch (e) {
            console.error(`Error generating image ${i+1}:`, e);
        }
    }

    if (results.length === 0) {
        throw new Error("Không thể tạo ảnh. Vui lòng thử lại sau.");
    }
    return results;
}

