          Nền tảng sáng tạo hình ảnh thời trang all-in-one. Biến ý tưởng thành hiện thực với chất lượng Studio sắc nét.
        </p>
      </header>

      <main>
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          <div className="md:col-span-2 lg:col-span-2">
            <FeatureCard
              icon={<CameraIcon className="w-8 h-8" />}
              title="Studio Sản phẩm & Người Mẫu"
              description="Tạo ảnh sản phẩm thương mại điện tử, người mẫu ảo (AI Model) và selfie gương chân thực. Hỗ trợ tùy chỉnh dáng pose, độ tuổi và bối cảnh."
              colorClass="bg-indigo-500"
              onClick={() => onSelectFeature('PRODUCT_STUDIO')}
            />
          </div>

           <FeatureCard
            icon={<PhotoIcon className="w-8 h-8" />}
            title="Lookbook Collection"
            description="Tạo bộ sưu tập thời trang theo chủ đề. Tự động đề xuất Video Prompt cho Veo 3.1."
            colorClass="bg-pink-500"
            onClick={() => onSelectFeature('LOOKBOOK_GENERATOR')}
          />

          <FeatureCard
            icon={<WandIcon className="w-8 h-8" />}
            title="Nâng Cấp Ảnh (Upscale)"
            description="Làm nét ảnh bị mờ, tăng độ phân giải lên 2K/4K và xóa watermark thông minh."
            colorClass="bg-sky-500"
            onClick={() => onSelectFeature('IMAGE_ENHANCER')}
          />

           <FeatureCard
            icon={<MicrophoneIcon className="w-8 h-8" />}
            title="Kịch Bản Review"
            description="Viết kịch bản TikTok/Shorts thu hút với ngôn ngữ địa phương (Bắc/Nam) tự nhiên."
            colorClass="bg-rose-500"
            onClick={() => onSelectFeature('REVIEW_SCRIPT_GENERATOR')}
          />

           <FeatureCard
            icon={<WaveformIcon className="w-8 h-8" />}
            title="Tạo Giọng Nói (TTS)"
            description="Chuyển văn bản thành giọng đọc Tiếng Việt tự nhiên với nhiều phong cách cảm xúc."
            colorClass="bg-teal-500"
            onClick={() => onSelectFeature('TEXT_TO_SPEECH')}
          />

          <div className="bg-slate-800/50 rounded-2xl p-6 border border-slate-700/50 flex flex-col justify-center items-center text-center opacity-75">
             <SparklesIcon className="w-8 h-8 text-slate-500 mb-3" />
             <h3 className="text-lg font-bold text-slate-400">Sắp ra mắt</h3>
             <p className="text-slate-500 text-xs mt-1">Video Editor AI & Virtual Try-on</p>
          </div>
        </div>
      </main>

      <footer className="mt-20 text-center text-slate-600 text-sm">
        <p>© 2024 AI Fashion Studio. Powered by {modelLevel === 'pro' ? 'Gemini 3 Pro' : 'Gemini 2.5 Flash'} & Veo.</p>
      </footer>
    </div>
  );
};

export default HomePage;

import React, { useState, useCallback, useRef } from 'react';
import { generateStyledImage, generateModelImage, generateSelfieImage, ModelPose, AspectRatio, generateBackgroundSuggestion, ProductDisplayMode, SelfieFraming, RugStyle, RugColor, RugPattern, ModelLevel } from './services/geminiService';
import { UploadIcon, SparklesIcon, LoadingSpinner, ErrorIcon, HangerIcon, UserIcon, ArrowLeftIcon, DownloadIcon, XIcon, RefreshIcon, WandIcon, ClipboardIcon, ClipboardCheckIcon, CameraIcon, ZoomInIcon } from './components/Icons';

type AppState = 'IDLE' | 'PROCESSING' | 'SUCCESS' | 'ERROR';
type ClothingType = 'Áo' | 'Quần' | 'Cả bộ' | 'Váy' | 'Phụ kiện';
type FeatureMode = 'product' | 'model' | 'selfie';
type Gender = 'Nam' | 'Nữ';

interface ResultItem {
    id: string;
    url: string;
    videoPrompt?: string;
}

interface ProductStudioProps {
  onGoBack: () => void;
  onEnhanceImage: (imageUrl: string) => void;
  modelLevel: ModelLevel;
}

const ProductStudio: React.FC<ProductStudioProps> = ({ onGoBack, onEnhanceImage, modelLevel }) => {
  // Core state
  const [originalImageFile, setOriginalImageFile] = useState<File | null>(null);
  const [originalImageUrl, setOriginalImageUrl] = useState<string | null>(null);
  const [generatedResults, setGeneratedResults] = useState<ResultItem[]>([]);
  const [appState, setAppState] = useState<AppState>('IDLE');
  const [error, setError] = useState<string | null>(null);
  const [zoomImage, setZoomImage] = useState<string | null>(null);

  // Feature selection state
  const [featureMode, setFeatureMode] = useState<FeatureMode>('product');
  const [clothingType, setClothingType] = useState<ClothingType>('Áo');
  const [aspectRatio, setAspectRatio] = useState<AspectRatio>('9:16');
  const [productDisplayMode, setProductDisplayMode] = useState<ProductDisplayMode>('hanger');

  // Flatlay Rug State
  const [rugStyle, setRugStyle] = useState<RugStyle>('Tự động');
  const [rugColor, setRugColor] = useState<RugColor>('Tự động');
  const [rugPattern, setRugPattern] = useState<RugPattern>('Tự động');

  // Model-specific state
  const [gender, setGender] = useState<Gender>('Nữ');
  const [age, setAge] = useState<string>('18-25');
  const [background, setBackground] = useState<string>('');
  const [numberOfImages, setNumberOfImages] = useState<number>(1);
  const [modelPose, setModelPose] = useState<ModelPose>('Dáng đứng');
  const [isGeneratingBackground, setIsGeneratingBackground] = useState<boolean>(false);
  const [copiedPromptIndex, setCopiedPromptIndex] = useState<number | null>(null);

  // Selfie specific state
  const [selfieFraming, setSelfieFraming] = useState<SelfieFraming>('Nửa thân');

  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFileChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (file) {
      if (!file.type.startsWith('image/')) {
        setError('Vui lòng chọn một tệp hình ảnh.');
        setAppState('ERROR');
        return;
      }
      setGeneratedResults([]);
      setError(null);
      setAppState('IDLE');
      setOriginalImageFile(file);
      setOriginalImageUrl(URL.createObjectURL(file));
    }
  };

  const handleRemoveImage = (e: React.MouseEvent) => {
    e.stopPropagation();
    setOriginalImageFile(null);
    setOriginalImageUrl(null);
    setGeneratedResults([]);
    setError(null);
    setAppState('IDLE');
    if (fileInputRef.current) {
        fileInputRef.current.value = "";
    }
  };

  const handleGenerateBackground = async () => {
    if (!originalImageFile || !clothingType) return;

    setIsGeneratingBackground(true);
    setError(null);

    const reader = new FileReader();
    reader.readAsDataURL(originalImageFile);
    reader.onloadend = async () => {
        try {
            const base64String = (reader.result as string).split(',')[1];
            if (!base64String) throw new Error('Cannot read file');
            const suggestion = await generateBackgroundSuggestion(base64String, originalImageFile.type, clothingType, modelLevel);
            setBackground(suggestion.trim().replace(/^"|"$/g, '')); 
        } catch (err: any) {
          setError(err.message || 'Error generating background.');
        } finally {
            setIsGeneratingBackground(false);
        }
    };
  };

  const generateId = (prefix: string) => {
      return `${prefix}_${Date.now()}_${Math.random().toString(36).substr(2, 6)}`;
  };

  const handleGenerateClick = useCallback(async () => {
    if (!originalImageFile || !clothingType || !featureMode) return;

    if(featureMode === 'model' && !background.trim()){
        setError('Vui lòng nhập mô tả bối cảnh.');
        setAppState('ERROR');
        return;
    }

    setAppState('PROCESSING');
    setError(null);
    setGeneratedResults([]);


    try {
      const reader = new FileReader();
      reader.readAsDataURL(originalImageFile);
      reader.onloadend = async () => {
        const base64String = (reader.result as string).split(',')[1];
        if (!base64String) throw new Error('Error processing image');

        if (featureMode === 'product') {
            const generatedImages = await generateStyledImage(
                base64String, 
                originalImageFile.type, 
                clothingType, 
                aspectRatio, 
                productDisplayMode, 
                numberOfImages,
                modelLevel,
                // Pass rug options if mode is flatlay
                productDisplayMode === 'flatlay' ? { style: rugStyle, color: rugColor, pattern: rugPattern } : undefined
            );
            setGeneratedResults(generatedImages.map(url => ({ 
                id: generateId('product'),
                url: `data:image/jpeg;base64,${url}` 
            })));
        } else if (featureMode === 'model') { 
            const generatedImages = await generateModelImage(base64String, originalImageFile.type, {
                clothingType,
                gender,
                age,
                background,
                numberOfImages,
                pose: modelPose,
                aspectRatio,
            }, modelLevel);
            setGeneratedResults(generatedImages.map(item => ({
                id: generateId('model'),
                url: item.imageUrl,
                videoPrompt: item.videoPrompt
            })));
        } else if (featureMode === 'selfie') {
             const generatedImages = await generateSelfieImage(base64String, originalImageFile.type, clothingType, numberOfImages, gender, selfieFraming, modelLevel);
             setGeneratedResults(generatedImages.map(url => ({ 
                id: generateId('selfie'),
                url: `data:image/jpeg;base64,${url}` 
            })));
        }

        setAppState('SUCCESS');
      };
    } catch (err: any) {
      console.error(err);
      setError(err.message || 'Đã xảy ra lỗi không mong muốn.');
      setAppState('ERROR');
    }
  }, [originalImageFile, featureMode, clothingType, gender, age, background, numberOfImages, modelPose, aspectRatio, productDisplayMode, selfieFraming, rugStyle, rugColor, rugPattern, modelLevel]);

  const triggerFileInput = () => {
    fileInputRef.current?.click();
  };

  const handleCopyToClipboard = (textToCopy: string, index: number) => {
    navigator.clipboard.writeText(textToCopy);
    setCopiedPromptIndex(index);
    setTimeout(() => setCopiedPromptIndex(null), 2000);
  };

  const isGenerateButtonDisabled = () => {
    if (appState === 'PROCESSING' || !originalImageFile) return true;
    if (featureMode === 'model' && !background.trim()) return true;
    return false;
  }

  return (
    <div className="flex flex-col h-screen overflow-hidden bg-slate-900 text-slate-200">
      {/* Zoom Modal */}
      {zoomImage && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/90 backdrop-blur-sm p-4 animate-fade-in" onClick={() => setZoomImage(null)}>
            <button className="absolute top-4 right-4 text-white hover:text-gray-300 p-2 bg-white/10 rounded-full" onClick={() => setZoomImage(null)}>
                <XIcon className="w-8 h-8" />
            </button>
            <img src={zoomImage} alt="Zoom" className="max-w-full max-h-[90vh] object-contain rounded-lg shadow-2xl" onClick={(e) => e.stopPropagation()} />
        </div>
      )}

      {/* Header */}
      <header className="flex-none h-16 border-b border-slate-700 bg-slate-800/50 backdrop-blur-md flex items-center px-6 justify-between z-20">
        <div className="flex items-center">
            <button onClick={onGoBack} className="flex items-center text-slate-400 hover:text-white transition-colors mr-4">
                <ArrowLeftIcon className="w-5 h-5 mr-2"/>
                <span className="font-medium">Trang chủ</span>
            </button>
            <div className="h-6 w-px bg-slate-700 mx-4"></div>
            <h1 className="text-lg font-bold text-white tracking-tight">Studio Sản phẩm AI</h1>
        </div>
        <div className="flex items-center space-x-2">
            <span className={`text-xs font-mono px-2 py-1 rounded border ${modelLevel === 'pro' ? 'bg-purple-500/20 border-purple-500/30 text-purple-300' : 'bg-indigo-500/10 border-indigo-500/20 text-indigo-400'}`}>
                {modelLevel === 'pro' ? 'GEMINI 3 PRO' : 'GEMINI 2.5 FLASH'}
            </span>
        </div>
      </header>

      {/* Main Layout */}
      <div className="flex-1 flex overflow-hidden">

        {/* Left Sidebar: Controls */}
        <div className="w-full md:w-[400px] lg:w-[450px] flex-none border-r border-slate-700 bg-slate-800/50 overflow-y-auto custom-scrollbar">
            <div className="p-6 space-y-8">

                {/* 1. Image Upload */}
                <div className="space-y-3">
                    <h2 className="text-sm font-bold text-slate-400 uppercase tracking-wider">1. Ảnh gốc</h2>
                    <input type="file" ref={fileInputRef} onChange={handleFileChange} accept="image/*" className="hidden" />
                    <div 
                        onClick={!originalImageUrl ? triggerFileInput : undefined}
                        className={`relative aspect-[3/4] w-full rounded-xl border-2 border-dashed transition-all duration-300 flex flex-col items-center justify-center overflow-hidden cursor-pointer
                            ${originalImageUrl ? 'border-indigo-500 bg-slate-800' : 'border-slate-600 bg-slate-800/50 hover:border-indigo-400 hover:bg-slate-700'}
                        `}
                    >
                        {originalImageUrl ? (
                            <>
                                <img src={originalImageUrl} alt="Upload" className="w-full h-full object-contain" />
                                <button onClick={handleRemoveImage} className="absolute top-2 right-2 bg-slate-900/80 text-white p-2 rounded-full hover:bg-red-500 transition-colors">
                                    <XIcon className="w-4 h-4" />
                                </button>
                                <button onClick={triggerFileInput} className="absolute bottom-2 right-2 bg-slate-900/80 text-white px-3 py-1.5 rounded-lg text-xs font-medium hover:bg-indigo-600 transition-colors backdrop-blur-sm">
                                    Thay ảnh
                                </button>
                            </>
                        ) : (
                            <div className="text-center p-6">
                                <UploadIcon className="w-10 h-10 text-slate-500 mx-auto mb-3" />
                                <p className="text-slate-300 font-medium">Tải ảnh trang phục</p>
                                <p className="text-xs text-slate-500 mt-1">Hỗ trợ JPG, PNG</p>
                            </div>
                        )}
                    </div>
                </div>

                {/* 2. Mode Selection */}
                <div className={`space-y-3 transition-opacity duration-300 ${!originalImageFile ? 'opacity-50 pointer-events-none' : ''}`}>
                    <h2 className="text-sm font-bold text-slate-400 uppercase tracking-wider">2. Chế độ tạo</h2>
                    <div className="grid grid-cols-3 gap-2 p-1 bg-slate-900 rounded-xl">
                        {[
                            { id: 'product', icon: HangerIcon, label: 'Sản phẩm' },
                            { id: 'model', icon: UserIcon, label: 'Mẫu ảo' },
                            { id: 'selfie', icon: CameraIcon, label: 'Selfie' }
                        ].map(mode => (
                            <button
                                key={mode.id}
                                onClick={() => setFeatureMode(mode.id as FeatureMode)}
                                className={`flex flex-col items-center justify-center py-3 rounded-lg text-xs font-semibold transition-all duration-200
                                    ${featureMode === mode.id ? 'bg-indigo-600 text-white shadow-lg' : 'text-slate-400 hover:text-white hover:bg-slate-800'}
                                `}
                            >
                                <mode.icon className="w-5 h-5 mb-1" />
                                {mode.label}
                            </button>
                        ))}
                    </div>
                </div>

                {/* 3. Detailed Settings */}
                <div className={`space-y-6 transition-opacity duration-300 ${!originalImageFile ? 'opacity-50 pointer-events-none' : ''}`}>

                    {/* Clothing Type */}
                    <div className="space-y-2">
                        <label className="text-xs font-medium text-slate-400">Loại trang phục</label>
                        <div className="flex flex-wrap gap-2">
                            {(['Áo', 'Quần', 'Cả bộ', 'Váy', 'Phụ kiện'] as ClothingType[]).map((type) => (
                                <button
                                    key={type}
                                    onClick={() => setClothingType(type)}
                                    className={`px-3 py-1.5 rounded-full text-xs font-medium border transition-all
                                        ${clothingType === type ? 'bg-indigo-500/20 border-indigo-500 text-indigo-300' : 'bg-slate-800 border-slate-700 text-slate-400 hover:border-slate-500'}
                                    `}
                                >
                                    {type}
                                </button>
                            ))}
                        </div>
                    </div>

                    {/* Aspect Ratio */}
                     {featureMode !== 'selfie' && (
                        <div className="space-y-2">
                            <label className="text-xs font-medium text-slate-400">Tỉ lệ khung hình</label>
                            <div className="flex bg-slate-900 rounded-lg p-1">
                                {(['9:16', '1:1', '4:5', '16:9'] as AspectRatio[]).map((ratio) => (
                                    <button
                                        key={ratio}
                                        onClick={() => setAspectRatio(ratio)}
                                        className={`flex-1 py-1.5 rounded text-xs font-medium transition-all
                                            ${aspectRatio === ratio ? 'bg-slate-700 text-white shadow' : 'text-slate-500 hover:text-slate-300'}
                                        `}
                                    >
                                        {ratio}
                                    </button>
                                ))}
                            </div>
                        </div>
                    )}

                    {/* Feature Specific Settings */}
                    {featureMode === 'product' && (
                        <div className="space-y-4 p-4 bg-slate-900/50 rounded-xl border border-slate-700">
                             <div className="space-y-2">
                                <label className="text-xs font-medium text-slate-400">Cách trình bày</label>
                                <div className="grid grid-cols-2 gap-2">
                                    <button onClick={() => setProductDisplayMode('hanger')} className={`py-2 px-3 rounded-lg border text-xs font-medium ${productDisplayMode === 'hanger' ? 'bg-indigo-500/20 border-indigo-500 text-white' : 'bg-slate-800 border-slate-700 text-slate-400'}`}>Treo móc / Kệ</button>
                                    <button onClick={() => setProductDisplayMode('flatlay')} className={`py-2 px-3 rounded-lg border text-xs font-medium ${productDisplayMode === 'flatlay' ? 'bg-indigo-500/20 border-indigo-500 text-white' : 'bg-slate-800 border-slate-700 text-slate-400'}`}>Flatlay (Trải sàn)</button>
                                </div>
                            </div>

                             {productDisplayMode === 'flatlay' && (
                                <div className="space-y-4 pt-2 border-t border-slate-700/50 animate-fade-in-up">
                                    <div className="space-y-2">
                                        <label className="text-xs font-medium text-slate-400 block">Loại thảm</label>
                                        <select value={rugStyle} onChange={(e) => setRugStyle(e.target.value as RugStyle)} className="w-full bg-slate-800 border border-slate-600 rounded-lg px-3 py-2 text-sm text-white focus:ring-1 focus:ring-indigo-500 outline-none">
                                            {(['Tự động', 'Lông mềm (Fur)', 'Thảm Ba Tư (Vintage)', 'Dệt Boho', 'Tối giản (Minimalist)', 'Lụa sang trọng'] as RugStyle[]).map(s => (
                                                <option key={s} value={s}>{s}</option>
                                            ))}
                                        </select>
                                    </div>
                                    <div className="space-y-2">
                                        <label className="text-xs font-medium text-slate-400 block">Màu sắc thảm</label>
                                        <select value={rugColor} onChange={(e) => setRugColor(e.target.value as RugColor)} className="w-full bg-slate-800 border border-slate-600 rounded-lg px-3 py-2 text-sm text-white focus:ring-1 focus:ring-indigo-500 outline-none">
                                            {(['Tự động', 'Trắng/Kem', 'Be (Beige)', 'Xám', 'Pastel', 'Tối màu'] as RugColor[]).map(c => (
                                                <option key={c} value={c}>{c}</option>
                                            ))}
                                        </select>
                                    </div>
                                    <div className="space-y-2">
                                        <label className="text-xs font-medium text-slate-400 block">Họa tiết thảm</label>
                                        <select value={rugPattern} onChange={(e) => setRugPattern(e.target.value as RugPattern)} className="w-full bg-slate-800 border border-slate-600 rounded-lg px-3 py-2 text-sm text-white focus:ring-1 focus:ring-indigo-500 outline-none">
                                            {(['Tự động', 'Trơn (Solid)', 'Hình học (Geometric)', 'Vân sóng', 'Trừu tượng'] as RugPattern[]).map(p => (
                                                <option key={p} value={p}>{p}</option>
                                            ))}
                                        </select>
                                    </div>
                                </div>
                            )}
                        </div>
                    )}

                    {featureMode === 'model' && (
                        <div className="space-y-4 p-4 bg-slate-900/50 rounded-xl border border-slate-700">
                            <div className="grid grid-cols-2 gap-4">
                                <div>
                                    <label className="text-xs font-medium text-slate-400 block mb-1.5">Giới tính</label>
                                    <select value={gender} onChange={(e) => setGender(e.target.value as Gender)} className="w-full bg-slate-800 border border-slate-600 rounded-lg px-3 py-2 text-sm text-white focus:ring-1 focus:ring-indigo-500 focus:border-indigo-500 outline-none">
                                        <option value="Nữ">Nữ</option>
                                        <option value="Nam">Nam</option>
                                    </select>
                                </div>
                                <div>
                                    <label className="text-xs font-medium text-slate-400 block mb-1.5">Độ tuổi</label>
                                    <select value={age} onChange={(e) => setAge(e.target.value)} className="w-full bg-slate-800 border border-slate-600 rounded-lg px-3 py-2 text-sm text-white focus:ring-1 focus:ring-indigo-500 focus:border-indigo-500 outline-none">
                                        <option value="18-25">18-25</option>
                                        <option value="26-35">26-35</option>
                                    </select>
                                </div>
                            </div>
                            <div>
                                <label className="text-xs font-medium text-slate-400 block mb-1.5">Dáng Pose</label>
                                <select value={modelPose} onChange={(e) => setModelPose(e.target.value as ModelPose)} className="w-full bg-slate-800 border border-slate-600 rounded-lg px-3 py-2 text-sm text-white focus:ring-1 focus:ring-indigo-500 focus:border-indigo-500 outline-none">
                                    <option value="Dáng đứng">Dáng đứng</option>
                                    <option value="Dáng đi">Dáng đi</option>
                                    <option value="Giới thiệu (Cầm móc)">Cầm móc áo</option>
                                    <option value="Giới thiệu (Chỉ mặc)">Chỉ mặc & Tạo dáng</option>
                                </select>
                            </div>
                            <div className="space-y-2">
                                <label className="text-xs font-medium text-slate-400 block">Bối cảnh</label>
                                <div className="relative">
                                    <input 
                                        type="text" 
                                        value={background} 
                                        onChange={(e) => setBackground(e.target.value)} 
                                        placeholder="VD: Đường phố Sài Gòn, Studio..."
                                        className="w-full bg-slate-800 border border-slate-600 rounded-lg pl-3 pr-10 py-2 text-sm text-white focus:ring-1 focus:ring-indigo-500 outline-none"
                                    />
                                    <button 
                                        onClick={handleGenerateBackground}
                                        disabled={isGeneratingBackground || !clothingType}
                                        className="absolute right-1 top-1 p-1.5 text-indigo-400 hover:text-indigo-300 disabled:opacity-50"
                                        title="Tự động gợi ý"
                                    >
                                        {isGeneratingBackground ? <LoadingSpinner className="w-4 h-4" /> : <SparklesIcon className="w-4 h-4" />}
                                    </button>
                                </div>
                            </div>
                        </div>
                    )}

                    {featureMode === 'selfie' && (
                        <div className="space-y-4 p-4 bg-slate-900/50 rounded-xl border border-slate-700">
                             <div className="space-y-2">
                                <label className="text-xs font-medium text-slate-400 block mb-1.5">Giới tính</label>
                                <select value={gender} onChange={(e) => setGender(e.target.value as Gender)} className="w-full bg-slate-800 border border-slate-600 rounded-lg px-3 py-2 text-sm text-white focus:ring-1 focus:ring-indigo-500 focus:border-indigo-500 outline-none">
                                    <option value="Nữ">Nữ</option>
                                    <option value="Nam">Nam</option>
                                </select>
                            </div>
                            <div className="space-y-2">
                                <label className="text-xs font-medium text-slate-400">Góc chụp</label>
                                <div className="grid grid-cols-2 gap-2">
                                    <button onClick={() => setSelfieFraming('Nửa thân')} className={`py-2 px-3 rounded-lg border text-xs font-medium ${selfieFraming === 'Nửa thân' ? 'bg-indigo-500/20 border-indigo-500 text-white' : 'bg-slate-800 border-slate-700 text-slate-400'}`}>Nửa thân (Waist Up)</button>
                                    <button onClick={() => setSelfieFraming('Toàn thân')} className={`py-2 px-3 rounded-lg border text-xs font-medium ${selfieFraming === 'Toàn thân' ? 'bg-indigo-500/20 border-indigo-500 text-white' : 'bg-slate-800 border-slate-700 text-slate-400'}`}>Toàn thân (Full Body)</button>
                                </div>
                            </div>
                        </div>
                    )}

                    {/* Number of Images Slider */}
                     <div className="space-y-2">
                        <div className="flex justify-between">
                             <label className="text-xs font-medium text-slate-400">Số lượng ảnh</label>
                             <span className="text-xs font-bold text-indigo-400">{numberOfImages}</span>
                        </div>
                        <input 
                            type="range" 
                            min="1" max="4" 
                            value={numberOfImages} 
                            onChange={(e) => setNumberOfImages(Number(e.target.value))}
                            className="w-full h-2 bg-slate-700 rounded-lg appearance-none cursor-pointer accent-indigo-500"
                        />
                    </div>

                    {/* Action Button */}
                    <button
                        onClick={handleGenerateClick}
                        disabled={isGenerateButtonDisabled()}
                        className="w-full py-4 bg-gradient-to-r from-indigo-600 to-purple-600 hover:from-indigo-500 hover:to-purple-500 text-white font-bold rounded-xl shadow-lg shadow-indigo-500/20 disabled:opacity-50 disabled:cursor-not-allowed transition-all duration-300 transform hover:scale-[1.02] active:scale-[0.98] flex items-center justify-center space-x-2"
                    >
                         {appState === 'PROCESSING' ? (
                             <>
                                <LoadingSpinner className="w-5 h-5" />
                                <span>Đang xử lý...</span>
                             </>
                         ) : (
                             <>
                                <SparklesIcon className="w-5 h-5" />
                                <span>Tạo ảnh ngay</span>
                             </>
                         )}
                    </button>
                </div>
            </div>
        </div>

        {/* Right Content: Results Gallery */}
        <div className="flex-1 bg-slate-900 overflow-y-auto p-4 md:p-8 flex flex-col items-center">

            {appState === 'IDLE' && (
                <div className="flex flex-col items-center justify-center h-full text-slate-500 space-y-4 opacity-60">
                    <div className="p-6 rounded-full bg-slate-800 border border-slate-700">
                        <SparklesIcon className="w-12 h-12" />
                    </div>
                    <p className="text-lg font-medium">Kết quả AI sẽ hiển thị tại đây</p>
                </div>
            )}

            {appState === 'PROCESSING' && (
                <div className="flex flex-col items-center justify-center h-full space-y-6">
                    <div className="relative">
                        <div className="absolute inset-0 bg-indigo-500 blur-xl opacity-20 animate-pulse rounded-full"></div>
                        <LoadingSpinner className="w-16 h-16 text-indigo-500 relative z-10" />
                    </div>
                    <div className="text-center space-y-2">
                        <h3 className="text-xl font-bold text-white">Đang sáng tạo...</h3>
                        <p className="text-slate-400 max-w-xs mx-auto">AI đang phân tích trang phục và tạo ra những bức ảnh tuyệt đẹp.</p>
                    </div>
                </div>
            )}

            {appState === 'ERROR' && (
                <div className="flex flex-col items-center justify-center h-full text-red-400 space-y-4">
                     <ErrorIcon className="w-16 h-16" />
                     <p className="text-lg font-medium">{error}</p>
                </div>
            )}

            {appState === 'SUCCESS' && (
                <div className="w-full max-w-6xl space-y-8 animate-fade-in">
                    <div className="flex items-center justify-between">
                        <h2 className="text-2xl font-bold text-white">Kết quả ({generatedResults.length})</h2>
                        <button onClick={handleGenerateClick} className="flex items-center space-x-2 text-indigo-400 hover:text-indigo-300 text-sm font-medium">
                            <RefreshIcon className="w-4 h-4" />
                            <span>Tạo lại</span>
                        </button>
                    </div>

                    <div className={`grid gap-6 ${generatedResults.length === 1 ? 'grid-cols-1 max-w-md mx-auto' : 'grid-cols-1 md:grid-cols-2 xl:grid-cols-3'}`}>
                        {generatedResults.map((item, index) => (
                            <div key={index} className="bg-slate-800 rounded-2xl p-3 border border-slate-700 hover:border-slate-500 transition-all duration-300 shadow-xl flex flex-col h-full group">
                                <div className="relative rounded-xl overflow-hidden aspect-[9/16] bg-slate-900 mb-3">
                                    <img src={item.url} alt="Generated" className="w-full h-full object-cover transform group-hover:scale-105 transition-transform duration-700" />
                                    <div className="absolute inset-0 bg-gradient-to-t from-black/60 via-transparent to-transparent opacity-0 group-hover:opacity-100 transition-opacity duration-300 flex flex-col justify-end p-4">
                                        <div className="flex space-x-2 justify-end">
                                            <button onClick={() => setZoomImage(item.url)} className="p-2 bg-white/10 backdrop-blur-md rounded-lg text-white hover:bg-white/20 transition-colors" title="Phóng to">
                                                <ZoomInIcon className="w-5 h-5" />
                                            </button>
                                            <button onClick={() => onEnhanceImage(item.url)} className="p-2 bg-white/10 backdrop-blur-md rounded-lg text-white hover:bg-white/20 transition-colors" title="Nâng cấp ảnh">
                                                <WandIcon className="w-5 h-5" />
                                            </button>
                                            <a href={item.url} download={`${item.id}.jpg`} className="p-2 bg-indigo-600 rounded-lg text-white hover:bg-indigo-700 transition-colors" title="Tải xuống">
                                                <DownloadIcon className="w-5 h-5" />
                                            </a>
                                        </div>
                                    </div>
                                </div>
                                {item.videoPrompt && (
                                    <div className="bg-slate-900/50 rounded-lg p-3 border border-slate-700/50 mt-auto">
                                        <div className="flex items-center justify-between mb-2">
                                            <span className="text-[10px] font-bold text-indigo-400 uppercase tracking-wider">Veo 3.1 Prompt</span>
                                            <button onClick={() => handleCopyToClipboard(item.videoPrompt!, index)} className="text-slate-400 hover:text-white">
                                                {copiedPromptIndex === index ? <ClipboardCheckIcon className="w-3 h-3 text-green-400" /> : <ClipboardIcon className="w-3 h-3" />}
                                            </button>
                                        </div>
                                        <p className="text-xs text-slate-400 line-clamp-2 hover:line-clamp-none transition-all cursor-pointer" title={item.videoPrompt}>
                                            {item.videoPrompt}
                                        </p>
                                    </div>
                                )}
                            </div>
                        ))}
                    </div>
                </div>
            )}

        </div>
      </div>
    </div>
  );
};

export default ProductStudio;

import React, { useState, useCallback, useRef } from 'react';
import { generateLookbookImages, LookbookOptions, ModelPose, AspectRatio, LookbookResult, Ethnicity, ModelLevel } from './services/geminiService';
import { UploadIcon, SparklesIcon, LoadingSpinner, ErrorIcon, ArrowLeftIcon, DownloadIcon, XIcon, PhotoIcon, ClipboardIcon, ClipboardCheckIcon, FilmIcon, UserIcon, ZoomInIcon } from './components/Icons';

type AppState = 'IDLE' | 'PROCESSING' | 'SUCCESS' | 'ERROR';
type ClothingType = 'Áo' | 'Quần' | 'Cả bộ' | 'Váy';
type Gender = 'Nam' | 'Nữ';

interface LookbookGeneratorProps {
  onGoBack: () => void;
  modelLevel: ModelLevel;
}

const LookbookGenerator: React.FC<LookbookGeneratorProps> = ({ onGoBack, modelLevel }) => {
  const [originalImageFile, setOriginalImageFile] = useState<File | null>(null);
  const [originalImageUrl, setOriginalImageUrl] = useState<string | null>(null);
  const [generatedLookbookItems, setGeneratedLookbookItems] = useState<(LookbookResult & { id: string })[]>([]);
  const [appState, setAppState] = useState<AppState>('IDLE');
  const [error, setError] = useState<string | null>(null);
  const [copiedPromptIndex, setCopiedPromptIndex] = useState<number | null>(null);
  const [zoomImage, setZoomImage] = useState<string | null>(null);

  // Settings
  const [clothingType, setClothingType] = useState<ClothingType>('Áo');
  const [aspectRatio, setAspectRatio] = useState<AspectRatio>('9:16');
  const [gender, setGender] = useState<Gender>('Nữ');
  const [ethnicity, setEthnicity] = useState<Ethnicity>('Việt Nam');
  const [age, setAge] = useState<string>('18-25');
  const [theme, setTheme] = useState<string>('');
  const [additionalPrompt, setAdditionalPrompt] = useState<string>('');
  const [numberOfImages, setNumberOfImages] = useState<number>(4);
  const [modelPose, setModelPose] = useState<ModelPose>('Dáng đứng');
  const [generateVideo, setGenerateVideo] = useState<boolean>(false);

  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFileChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (file) {
      if (!file.type.startsWith('image/')) {
        setError('Vui lòng chọn một tệp hình ảnh.');
        setAppState('ERROR');
        return;
      }
      setGeneratedLookbookItems([]);
      setError(null);
      setAppState('IDLE');
      setOriginalImageFile(file);
      setOriginalImageUrl(URL.createObjectURL(file));
    }
  };

  const handleRemoveImage = (e: React.MouseEvent) => {
    e.stopPropagation();
    setOriginalImageFile(null);
    setOriginalImageUrl(null);
    setGeneratedLookbookItems([]);
    setError(null);
    setAppState('IDLE');
    if (fileInputRef.current) {
        fileInputRef.current.value = "";
    }
  };

  const handleGenerateClick = useCallback(async () => {
    if (!originalImageFile) {
        setError('Vui lòng tải ảnh lên.');
        setAppState('ERROR');
        return;
    }

    setAppState('PROCESSING');
    setError(null);
    setGeneratedLookbookItems([]);

    try {
      const reader = new FileReader();
      reader.readAsDataURL(originalImageFile);
      reader.onloadend = async () => {
        const base64String = (reader.result as string).split(',')[1];
        if (!base64String) throw new Error('Cannot process image');

        const options: LookbookOptions = {
            clothingType,
            gender,
            age,
            theme: theme.trim() || "Professional fashion lookbook, clean background, high fashion style", // Default theme if empty
            additionalPrompt,
            numberOfImages,
            pose: modelPose,
            aspectRatio,
            generateVideo,
            ethnicity
        };
        const generatedItems = await generateLookbookImages(base64String, originalImageFile.type, options, modelLevel);

        setGeneratedLookbookItems(generatedItems.map(item => ({
            ...item,
            id: `lookbook_${Date.now()}_${Math.random().toString(36).substr(2, 6)}`
        })));
        setAppState('SUCCESS');
      };
    } catch (err: any) {
      console.error(err);
      setError(err.message || 'Đã xảy ra lỗi.');
      setAppState('ERROR');
    }
  }, [originalImageFile, clothingType, gender, ethnicity, age, theme, additionalPrompt, numberOfImages, modelPose, aspectRatio, generateVideo, modelLevel]);

  const triggerFileInput = () => {
    fileInputRef.current?.click();
  };

  const handleCopyToClipboard = (textToCopy: string, index: number) => {
    navigator.clipboard.writeText(textToCopy);
    setCopiedPromptIndex(index);
    setTimeout(() => setCopiedPromptIndex(null), 2000);
  };

  const isGenerateButtonDisabled = () => {
    return appState === 'PROCESSING' || !originalImageFile;
  }

  return (
    <div className="flex flex-col h-screen overflow-hidden bg-slate-900 text-slate-200">
      {/* Zoom Modal */}
      {zoomImage && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/90 backdrop-blur-sm p-4 animate-fade-in" onClick={() => setZoomImage(null)}>
            <button className="absolute top-4 right-4 text-white hover:text-gray-300 p-2 bg-white/10 rounded-full" onClick={() => setZoomImage(null)}>
                <XIcon className="w-8 h-8" />
            </button>
            <img src={zoomImage} alt="Zoom" className="max-w-full max-h-[90vh] object-contain rounded-lg shadow-2xl" onClick={(e) => e.stopPropagation()} />
        </div>
      )}

       <header className="flex-none h-16 border-b border-slate-700 bg-slate-800/50 backdrop-blur-md flex items-center px-6 justify-between z-20">
        <div className="flex items-center">
            <button onClick={onGoBack} className="flex items-center text-slate-400 hover:text-white transition-colors mr-4">
                <ArrowLeftIcon className="w-5 h-5 mr-2"/>
                <span className="font-medium">Trang chủ</span>
            </button>
            <div className="h-6 w-px bg-slate-700 mx-4"></div>
            <h1 className="text-lg font-bold text-white tracking-tight">Lookbook Generator</h1>
        </div>
        <div className="flex items-center space-x-2">
            <span className={`text-xs font-mono px-2 py-1 rounded border ${modelLevel === 'pro' ? 'bg-purple-500/20 border-purple-500/30 text-purple-300' : 'bg-indigo-500/10 border-indigo-500/20 text-indigo-400'}`}>
                {modelLevel === 'pro' ? 'GEMINI 3 PRO' : 'GEMINI 2.5 FLASH'}
            </span>
        </div>
      </header>

      <div className="flex-1 flex overflow-hidden">
        {/* Left Sidebar */}
        <div className="w-full md:w-[400px] lg:w-[450px] flex-none border-r border-slate-700 bg-slate-800/50 overflow-y-auto custom-scrollbar">
             <div className="p-6 space-y-8">
                {/* Image Upload */}
                <div className="space-y-3">
                    <h2 className="text-sm font-bold text-slate-400 uppercase tracking-wider">1. Sản phẩm</h2>
                    <input type="file" ref={fileInputRef} onChange={handleFileChange} accept="image/*" className="hidden" />
                    <div 
                        onClick={!originalImageUrl ? triggerFileInput : undefined}
                        className={`relative aspect-[3/4] w-full rounded-xl border-2 border-dashed transition-all duration-300 flex flex-col items-center justify-center overflow-hidden cursor-pointer
                            ${originalImageUrl ? 'border-pink-500 bg-slate-800' : 'border-slate-600 bg-slate-800/50 hover:border-pink-400 hover:bg-slate-700'}
                        `}
                    >
                        {originalImageUrl ? (
                            <>
                                <img src={originalImageUrl} alt="Upload" className="w-full h-full object-contain" />
                                <button onClick={handleRemoveImage} className="absolute top-2 right-2 bg-slate-900/80 text-white p-2 rounded-full hover:bg-red-500 transition-colors">
                                    <XIcon className="w-4 h-4" />
                                </button>
                            </>
                        ) : (
                            <div className="text-center p-6">
                                <UploadIcon className="w-10 h-10 text-slate-500 mx-auto mb-3" />
                                <p className="text-slate-300 font-medium">Tải ảnh sản phẩm</p>
                            </div>
                        )}
                    </div>
                     <div className="flex flex-wrap gap-2 mt-2">
                        {(['Áo', 'Quần', 'Cả bộ', 'Váy'] as ClothingType[]).map((type) => (
                            <button key={type} onClick={() => setClothingType(type)} className={`px-3 py-1.5 rounded-full text-xs font-medium border transition-all ${clothingType === type ? 'bg-pink-500/20 border-pink-500 text-pink-300' : 'bg-slate-800 border-slate-700 text-slate-400'}`}>
                                {type}
                            </button>
                        ))}
                    </div>
                </div>

                {/* Settings */}
                <div className={`space-y-6 transition-opacity duration-300 ${!originalImageFile ? 'opacity-50 pointer-events-none' : ''}`}>
                    <h2 className="text-sm font-bold text-slate-400 uppercase tracking-wider">2. Cấu hình Lookbook</h2>

                    <div className="space-y-4 p-5 bg-slate-900/50 rounded-xl border border-slate-700">
                        {/* Theme Input */}
                        <div>
                             <label className="text-xs font-bold text-pink-400 block mb-2 uppercase">Chủ đề (Concept)</label>
                             <textarea 
                                value={theme}
                                onChange={(e) => setTheme(e.target.value)}
                                placeholder="VD: Dạo phố mùa thu lãng mạn, tone màu be, ánh nắng nhẹ... (Để trống để AI tự sáng tạo)"
                                rows={3}
                                className="w-full bg-slate-800 border border-slate-600 rounded-lg p-3 text-sm text-white focus:ring-1 focus:ring-pink-500 outline-none"
                            />
                        </div>

                         <div className="grid grid-cols-2 gap-4">
                            <div>
                                <label className="text-xs font-medium text-slate-400 block mb-1.5">Người mẫu</label>
                                <div className="flex bg-slate-800 border border-slate-600 rounded-lg p-1">
                                    {(['Nữ', 'Nam'] as Gender[]).map(g => (
                                         <button
                                            key={g}
                                            onClick={() => setGender(g)}
                                            className={`flex-1 py-1.5 rounded text-xs font-bold transition-all ${gender === g ? 'bg-pink-600 text-white shadow' : 'text-slate-400 hover:text-white'}`}
                                         >
                                            {g}
                                         </button>
                                    ))}
                                </div>
                            </div>
                            <div>
                                <label className="text-xs font-medium text-slate-400 block mb-1.5">Quốc tịch</label>
                                <select value={ethnicity} onChange={(e) => setEthnicity(e.target.value as Ethnicity)} className="w-full bg-slate-800 border border-slate-600 rounded-lg px-3 py-2 text-sm text-white focus:ring-1 focus:ring-pink-500 outline-none">
                                    <option value="Việt Nam">Việt Nam</option>
                                    <option value="Hàn Quốc">Hàn Quốc</option>
                                </select>
                            </div>
                         </div>

                         <div>
                            <label className="text-xs font-medium text-slate-400 block mb-1.5">Tư thế</label>
                            <div className="flex bg-slate-800 border border-slate-600 rounded-lg p-1">
                                <button
                                    onClick={() => setModelPose('Dáng đứng')}
                                    className={`flex-1 py-1.5 rounded text-xs font-bold transition-all ${modelPose === 'Dáng đứng' ? 'bg-pink-600 text-white shadow' : 'text-slate-400 hover:text-white'}`}
                                >
                                    Dáng đứng
                                </button>
                                <button
                                    onClick={() => setModelPose('Dáng đi')}
                                    className={`flex-1 py-1.5 rounded text-xs font-bold transition-all ${modelPose === 'Dáng đi' ? 'bg-pink-600 text-white shadow' : 'text-slate-400 hover:text-white'}`}
                                >
                                    Dáng đi
                                </button>
                            </div>
                         </div>

                         <div>
                            <label className="text-xs font-medium text-slate-400 block mb-1.5">Độ tuổi</label>
                            <select value={age} onChange={(e) => setAge(e.target.value)} className="w-full bg-slate-800 border border-slate-600 rounded-lg px-3 py-2 text-sm text-white focus:ring-1 focus:ring-pink-500 outline-none">
                                <option value="18-25">18-25</option>
                                <option value="26-35">26-35</option>
                            </select>
                         </div>

                         <div>
                            <label className="flex items-center space-x-3 cursor-pointer p-3 rounded-lg bg-slate-800 border border-slate-700 hover:border-pink-500/50 transition-colors">
                                <input 
                                    type="checkbox" 
                                    checked={generateVideo} 
                                    onChange={(e) => setGenerateVideo(e.target.checked)}
                                    className="h-5 w-5 rounded border-slate-500 text-pink-600 focus:ring-pink-500 bg-slate-900"
                                />
                                <div className="flex flex-col">
                                    <span className="text-sm font-medium text-white flex items-center">
                                        <FilmIcon className="w-4 h-4 mr-2 text-pink-500" />
                                        Tạo kèm Video Prompt
                                    </span>
                                    <span className="text-[10px] text-slate-500">Tối ưu cho Google Veo 3.1</span>
                                </div>
                            </label>
                        </div>

                         {/* Number of Images Slider */}
                        <div className="space-y-2 pt-2 border-t border-slate-700/50">
                            <div className="flex justify-between">
                                <label className="text-xs font-medium text-slate-400">Số lượng ảnh</label>
                                <span className="text-xs font-bold text-pink-400">{numberOfImages}</span>
                            </div>
                            <input 
                                type="range" 
                                min="1" max="10" 
                                value={numberOfImages} 
                                onChange={(e) => setNumberOfImages(Number(e.target.value))}
                                className="w-full h-2 bg-slate-700 rounded-lg appearance-none cursor-pointer accent-pink-500"
                            />
                        </div>
                    </div>

                    <button
                        onClick={handleGenerateClick}
                        disabled={isGenerateButtonDisabled()}
                        className="w-full py-4 bg-gradient-to-r from-pink-600 to-rose-600 hover:from-pink-500 hover:to-rose-500 text-white font-bold rounded-xl shadow-lg shadow-pink-500/20 disabled:opacity-50 disabled:cursor-not-allowed transition-all duration-300 transform hover:scale-[1.02] flex items-center justify-center space-x-2"
                    >
                         {appState === 'PROCESSING' ? (
                             <>
                                <LoadingSpinner className="w-5 h-5" />
                                <span>Đang sáng tạo...</span>
                             </>
                         ) : (
                             <>
                                <PhotoIcon className="w-5 h-5" />
                                <span>Tạo Collection</span>
                             </>
                         )}
                    </button>
                </div>
             </div>
        </div>

        {/* Right Content */}
        <div className="flex-1 bg-slate-900 overflow-y-auto p-4 md:p-8 flex flex-col items-center">
            {appState === 'SUCCESS' && generatedLookbookItems.length > 0 ? (
                <div className="w-full max-w-6xl space-y-6 animate-fade-in">
                    <h2 className="text-2xl font-bold text-white mb-6">Bộ sưu tập Lookbook</h2>
                    <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-4 gap-4">
                        {generatedLookbookItems.map((item, index) => (
                            <div key={index} className="bg-slate-800 rounded-xl overflow-hidden shadow-xl border border-slate-700 group">
                                <div className="relative aspect-[9/16] group cursor-pointer" onClick={() => setZoomImage(item.imageUrl)}>
                                    <img src={item.imageUrl} alt="Result" className="w-full h-full object-cover" />
                                    <div className="absolute inset-0 bg-black/0 group-hover:bg-black/20 transition-all flex items-center justify-center opacity-0 group-hover:opacity-100">
                                        <ZoomInIcon className="w-10 h-10 text-white drop-shadow-md" />
                                    </div>
                                    <a href={item.imageUrl} download={`${item.id}.jpg`} className="absolute top-2 right-2 bg-black/60 text-white p-2 rounded-full opacity-0 group-hover:opacity-100 transition-opacity" onClick={(e) => e.stopPropagation()}>
                                        <DownloadIcon className="w-5 h-5"/>
                                    </a>
                                </div>
                                {item.videoPrompt && (
                                    <div className="p-3 bg-slate-900 border-t border-slate-700">
                                        <div className="flex justify-between items-center mb-1">
                                            <span className="text-[10px] font-bold text-pink-500">VIDEO PROMPT</span>
                                            <button onClick={() => handleCopyToClipboard(item.videoPrompt!, index)}>
                                                {copiedPromptIndex === index ? <ClipboardCheckIcon className="w-3 h-3 text-green-500"/> : <ClipboardIcon className="w-3 h-3 text-slate-500 hover:text-white"/>}
                                            </button>
                                        </div>
                                        <p className="text-[10px] text-slate-400 line-clamp-2">{item.videoPrompt}</p>
                                    </div>
                                )}
                            </div>
                        ))}
                    </div>
                </div>
            ) : (
                <div className="flex flex-col items-center justify-center h-full text-slate-600 space-y-4">
                    {appState === 'PROCESSING' ? (
                         <LoadingSpinner className="w-12 h-12 text-pink-500" />
                    ) : (
                        <>
                             <PhotoIcon className="w-16 h-16 opacity-50" />
                             <p>Kết quả Lookbook sẽ hiển thị tại đây</p>
                        </>
                    )}
                </div>
            )}
        </div>
      </div>
    </div>
  );
};

export default LookbookGenerator;

import React, { useState, useCallback, useRef, useEffect } from 'react';
import { enhanceImage, EnhanceOptions, ModelLevel } from './services/geminiService';
import { UploadIcon, SparklesIcon, LoadingSpinner, ErrorIcon, ArrowLeftIcon, WandIcon, XIcon, DownloadIcon, ZoomInIcon } from './components/Icons';

type AppState = 'IDLE' | 'PROCESSING' | 'SUCCESS' | 'ERROR';

interface ImageEnhancerProps {
  onGoBack: () => void;
  initialImageUrl?: string | null;
  modelLevel: ModelLevel;
}

const ImageEnhancer: React.FC<ImageEnhancerProps> = ({ onGoBack, initialImageUrl, modelLevel }) => {
  const [originalImageFile, setOriginalImageFile] = useState<File | null>(null);
  const [originalImageUrl, setOriginalImageUrl] = useState<string | null>(null);
  const [generatedImageUrl, setGeneratedImageUrl] = useState<string | null>(null);
  const [appState, setAppState] = useState<AppState>('IDLE');
  const [error, setError] = useState<string | null>(null);
  const [zoomImage, setZoomImage] = useState<string | null>(null);
  const [options, setOptions] = useState<EnhanceOptions>({
    upscale: false,
    sharpen: false,
    removeWatermark: false,
  });

  const fileInputRef = useRef<HTMLInputElement>(null);

  const dataUrlToFile = async (dataUrl: string, filename: string): Promise<File> => {
      const res = await fetch(dataUrl);
      const blob = await res.blob();
      const mimeType = blob.type || 'image/jpeg';
      const finalFilename = filename.includes('.') ? filename : `${filename}.${mimeType.split('/')[1] || 'jpeg'}`;
      return new File([blob], finalFilename, { type: mimeType });
  };

  useEffect(() => {
    if (initialImageUrl) {
        const loadImage = async () => {
            try {
                setGeneratedImageUrl(null);
                setError(null);
                setAppState('IDLE');
                if (fileInputRef.current) fileInputRef.current.value = "";
                setOriginalImageUrl(initialImageUrl);
                const file = await dataUrlToFile(initialImageUrl, 'image-from-studio.jpeg');
                setOriginalImageFile(file);
            } catch (e) {
                setError("Không thể tải ảnh.");
                setAppState('ERROR');
            }
        };
        loadImage();
    }
  }, [initialImageUrl]);

  const handleFileChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (file) {
      if (!file.type.startsWith('image/')) {
        setError('Vui lòng chọn một tệp hình ảnh.');
        setAppState('ERROR');
        return;
      }
      setGeneratedImageUrl(null);
      setError(null);
      setAppState('IDLE');
      setOriginalImageFile(file);
      setOriginalImageUrl(URL.createObjectURL(file));
    }
  };

  const handleRemoveImage = (e: React.MouseEvent) => {
    e.stopPropagation();
    setOriginalImageFile(null);
    setOriginalImageUrl(null);
    setGeneratedImageUrl(null);
    setError(null);
    setAppState('IDLE');
    if (fileInputRef.current) fileInputRef.current.value = "";
  };

  const handleOptionChange = (option: keyof EnhanceOptions) => {
    setOptions(prev => ({ ...prev, [option]: !prev[option] }));
  };

  const handleGenerateClick = useCallback(async () => {
    if (!originalImageFile || (!options.upscale && !options.sharpen && !options.removeWatermark)) return;

    setAppState('PROCESSING');
    setError(null);
    setGeneratedImageUrl(null);

    try {
      const reader = new FileReader();
      reader.readAsDataURL(originalImageFile);
      reader.onloadend = async () => {
        const base64String = (reader.result as string).split(',')[1];
        if (!base64String) throw new Error('Failed to read image');

        const generatedImage = await enhanceImage(base64String, originalImageFile.type, options, modelLevel);
        setGeneratedImageUrl(`data:image/jpeg;base64,${generatedImage}`);
        setAppState('SUCCESS');
      };
    } catch (err: any) {
      setError(err.message || 'Lỗi không xác định.');
      setAppState('ERROR');
    }
  }, [originalImageFile, options, modelLevel]);

  const triggerFileInput = () => {
    fileInputRef.current?.click();
  };

  const OptionCard: React.FC<{ id: keyof EnhanceOptions; title: string, desc: string, disabled: boolean }> = ({ id, title, desc, disabled }) => (
     <div 
        onClick={() => !disabled && handleOptionChange(id)}
        className={`relative p-4 rounded-xl border-2 cursor-pointer transition-all duration-200 flex items-start space-x-3
            ${disabled ? 'opacity-50 cursor-not-allowed border-slate-700 bg-slate-800' : 
              options[id] ? 'border-sky-500 bg-sky-500/10' : 'border-slate-700 bg-slate-800 hover:border-slate-500'}
        `}
     >
        <div className={`mt-1 w-5 h-5 rounded border flex items-center justify-center transition-colors
            ${options[id] ? 'bg-sky-500 border-sky-500' : 'border-slate-500 bg-transparent'}
        `}>
            {options[id] && <svg className="w-3.5 h-3.5 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M5 13l4 4L19 7" /></svg>}
        </div>
        <div>
            <h3 className={`font-semibold text-sm ${options[id] ? 'text-white' : 'text-slate-300'}`}>{title}</h3>
            <p className="text-xs text-slate-500 mt-1">{desc}</p>
        </div>
     </div>
  );

  return (
    <div className="bg-slate-900 min-h-screen text-slate-200 font-sans">
      {/* Zoom Modal */}
      {zoomImage && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/90 backdrop-blur-sm p-4 animate-fade-in" onClick={() => setZoomImage(null)}>
            <button className="absolute top-4 right-4 text-white hover:text-gray-300 p-2 bg-white/10 rounded-full" onClick={() => setZoomImage(null)}>
                <XIcon className="w-8 h-8" />
            </button>
            <img src={zoomImage} alt="Zoom" className="max-w-full max-h-[90vh] object-contain rounded-lg shadow-2xl" onClick={(e) => e.stopPropagation()} />
        </div>
      )}

      <header className="flex-none h-16 border-b border-slate-700 bg-slate-800/50 backdrop-blur-md flex items-center px-6 justify-between z-20">
        <div className="flex items-center">
            <button onClick={onGoBack} className="flex items-center text-slate-400 hover:text-white transition-colors mr-4">
                <ArrowLeftIcon className="w-5 h-5 mr-2"/>
                <span className="font-medium">Trang chủ</span>
            </button>
            <div className="h-6 w-px bg-slate-700 mx-4"></div>
            <h1 className="text-lg font-bold text-white tracking-tight">Image Enhancer</h1>
        </div>
        <div className="flex items-center space-x-2">
            <span className={`text-xs font-mono px-2 py-1 rounded border ${modelLevel === 'pro' ? 'bg-purple-500/20 border-purple-500/30 text-purple-300' : 'bg-indigo-500/10 border-indigo-500/20 text-indigo-400'}`}>
                {modelLevel === 'pro' ? 'GEMINI 3 PRO' : 'GEMINI 2.5 FLASH'}
            </span>
        </div>
      </header>

      <div className="container mx-auto px-4 py-8 max-w-5xl">

        <div className="grid grid-cols-1 md:grid-cols-2 gap-8">

            {/* Input Column */}
            <div className="space-y-6">
                <div className="space-y-2">
                    <h1 className="text-3xl font-bold text-white">Nâng Cấp Ảnh AI</h1>
                    <p className="text-slate-400">Tối ưu hóa chất lượng hình ảnh với công nghệ AI tiên tiến.</p>
                </div>

                {/* Upload */}
                <input type="file" ref={fileInputRef} onChange={handleFileChange} accept="image/*" className="hidden" />
                <div 
                    onClick={!originalImageUrl ? triggerFileInput : undefined}
                    className={`relative w-full aspect-video rounded-2xl border-2 border-dashed flex flex-col items-center justify-center overflow-hidden transition-all duration-300 cursor-pointer
                        ${originalImageUrl ? 'border-sky-500 bg-slate-800' : 'border-slate-700 bg-slate-800/50 hover:bg-slate-800 hover:border-sky-400'}
                    `}
                >
                     {originalImageUrl ? (
                        <>
                            <img src={originalImageUrl} alt="Original" className="w-full h-full object-contain" />
                            <button onClick={handleRemoveImage} className="absolute top-2 right-2 bg-slate-900/80 p-2 rounded-full hover:bg-red-500 text-white transition-colors">
                                <XIcon className="w-4 h-4" />
                            </button>
                        </>
                    ) : (
                        <div className="text-center">
                            <UploadIcon className="w-10 h-10 text-slate-500 mx-auto mb-3" />
                            <p className="text-slate-300 font-medium">Chọn ảnh cần nâng cấp</p>
                        </div>
                    )}
                </div>

                {/* Options */}
                <div className="space-y-3">
                    <p className="text-sm font-bold text-slate-500 uppercase tracking-wider">Tùy chọn xử lý</p>
                    <OptionCard id="upscale" title="Upscale 2K/4K" desc="Tăng độ phân giải và chi tiết." disabled={!originalImageFile} />
                    <OptionCard id="sharpen" title="Làm nét (Sharpen)" desc="Khử mờ, tăng độ sắc nét cho chủ thể." disabled={!originalImageFile} />
                    <OptionCard id="removeWatermark" title="Xóa Watermark" desc="Loại bỏ chữ, logo trên ảnh tự động." disabled={!originalImageFile} />
                </div>

                <button
                    onClick={handleGenerateClick}
                    disabled={appState === 'PROCESSING' || !originalImageFile || (!options.upscale && !options.sharpen && !options.removeWatermark)}
                    className="w-full py-4 bg-sky-600 hover:bg-sky-500 text-white font-bold rounded-xl shadow-lg shadow-sky-500/20 disabled:opacity-50 disabled:cursor-not-allowed transition-all flex items-center justify-center space-x-2"
                >
                     {appState === 'PROCESSING' ? (
                         <> <LoadingSpinner className="w-5 h-5" /> <span>Đang xử lý...</span> </>
                     ) : (
                         <> <WandIcon className="w-5 h-5" /> <span>Bắt đầu nâng cấp</span> </>
                     )}
                </button>
            </div>

            {/* Output Column */}
            <div className="bg-slate-800/50 rounded-3xl p-6 border border-slate-700/50 flex flex-col">
                <h2 className="text-xl font-bold text-white mb-4">Kết quả</h2>
                <div className="flex-1 rounded-2xl bg-slate-900 border border-slate-700 overflow-hidden relative flex items-center justify-center group">
                    {appState === 'IDLE' && <p className="text-slate-500">Chưa có kết quả</p>}
                    {appState === 'PROCESSING' && (
                        <div className="text-center">
                            <LoadingSpinner className="w-12 h-12 text-sky-500 mx-auto mb-4" />
                            <p className="text-sky-400 animate-pulse">AI đang làm việc...</p>
                        </div>
                    )}
                    {appState === 'SUCCESS' && generatedImageUrl && (
                        <div className="relative w-full h-full cursor-pointer" onClick={() => setZoomImage(generatedImageUrl)}>
                            <img src={generatedImageUrl} alt="Enhanced" className="w-full h-full object-contain" />
                            <div className="absolute inset-0 bg-black/0 group-hover:bg-black/20 transition-all flex items-center justify-center opacity-0 group-hover:opacity-100">
                                <ZoomInIcon className="w-12 h-12 text-white drop-shadow-lg" />
                            </div>
                        </div>
                    )}
                    {appState === 'ERROR' && (
                        <div className="text-center text-red-400">
                            <ErrorIcon className="w-10 h-10 mx-auto mb-2" />
                            <p>{error}</p>
                        </div>
                    )}
                </div>

                {appState === 'SUCCESS' && generatedImageUrl && (
                    <a href={generatedImageUrl} download="enhanced-image.jpg" className="mt-4 w-full py-3 bg-green-600 hover:bg-green-500 text-white font-bold rounded-xl flex items-center justify-center space-x-2 shadow-lg transition-all">
                        <DownloadIcon className="w-5 h-5" />
                        <span>Tải ảnh về máy</span>
                    </a>
                )}
            </div>

        </div>
      </div>
    </div>
  );
};

export default ImageEnhancer;

import React, { useState, useCallback } from 'react';
import { generateReviewScript, ReviewScriptOptions, ScriptType, RegionalAccent, ReviewScriptResult, ModelLevel } from './services/geminiService';
