import React, { useState, useCallback, useRef } from 'react';
import { generateVideoPrompt, generateVoiceoverScript, VideoPromptOptions, VoiceoverStyle, ModelLevel } from './services/geminiService';
import { UploadIcon, SparklesIcon, LoadingSpinner, ErrorIcon, ArrowLeftIcon, FilmIcon, XIcon } from './components/Icons';

type AppState = 'IDLE' | 'PROCESSING_VOICEOVER' | 'PROCESSING_PROMPT' | 'SUCCESS' | 'ERROR';

interface VideoPromptGeneratorProps {
  onGoBack: () => void;
  modelLevel: ModelLevel;
}

const VideoPromptGenerator: React.FC<VideoPromptGeneratorProps> = ({ onGoBack, modelLevel }) => {
  const [originalImageFile, setOriginalImageFile] = useState<File | null>(null);
  const [originalImageUrl, setOriginalImageUrl] = useState<string | null>(null);
  const [generatedPrompt, setGeneratedPrompt] = useState<string>('');
  const [voiceoverScript, setVoiceoverScript] = useState<string>('');
  const [voiceoverStyle, setVoiceoverStyle] = useState<VoiceoverStyle>('Năng động');
  const [appState, setAppState] = useState<AppState>('IDLE');
  const [error, setError] = useState<string | null>(null);
  const [options, setOptions] = useState<VideoPromptOptions>({
    productInfo: '',
    targetAudience: '',
    videoStyle: '',
  });

  const fileInputRef = useRef<HTMLInputElement>(null);
  const resultTextareaRef = useRef<HTMLTextAreaElement>(null);

  const handleFileChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (file) {
      if (!file.type.startsWith('image/')) {
        setError('Vui lòng chọn một tệp hình ảnh.');
        setAppState('ERROR');
        return;
      }
      // Reset only results, not settings
      setGeneratedPrompt('');
      setError(null);
      setAppState('IDLE');

      setOriginalImageFile(file);
      setOriginalImageUrl(URL.createObjectURL(file));
    }
  };

  const handleRemoveImage = (e: React.MouseEvent) => {
    e.stopPropagation();
    // Only reset image and results, keep all other settings
    setOriginalImageFile(null);
    setOriginalImageUrl(null);
    setGeneratedPrompt('');
    setError(null);
    setAppState('IDLE');
    if (fileInputRef.current) {
        fileInputRef.current.value = "";
    }
  };

  const handleOptionChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
    const { name, value } = e.target;
    setOptions(prev => ({ ...prev, [name]: value }));
  };

  const handleGenerateVoiceover = async () => {
    if (!options.productInfo.trim()) {
        setError("Vui lòng nhập thông tin sản phẩm để tạo giọng đọc.");
        setAppState('ERROR');
        return;
    };

    setAppState('PROCESSING_VOICEOVER');
    setError(null);

    try {
        const script = await generateVoiceoverScript(options, voiceoverStyle, modelLevel);
        setVoiceoverScript(script);
        setAppState('IDLE'); // Return to idle to allow prompt generation
    } catch (err: any) {
        console.error(err);
        setError(err.message || 'Không thể tạo giọng đọc.');
        setAppState('ERROR');
    }
  };

  const handleGeneratePrompt = useCallback(async () => {
    if (!originalImageFile || !options.productInfo.trim() || !voiceoverScript.trim()) return;

    setAppState('PROCESSING_PROMPT');
    setError(null);
    setGeneratedPrompt('');

    try {
      const reader = new FileReader();
      reader.readAsDataURL(originalImageFile);
      reader.onloadend = async () => {
        const base64String = (reader.result as string).split(',')[1];
        if (!base64String) {
          throw new Error('Không thể chuyển đổi hình ảnh.');
        }

        const promptText = await generateVideoPrompt(base64String, originalImageFile.type, options, voiceoverScript, modelLevel);

        setGeneratedPrompt(promptText);
        setAppState('SUCCESS');
      };
      reader.onerror = () => {
         throw new Error('Lỗi khi đọc tệp hình ảnh.');
      }
    } catch (err: any) {
      console.error(err);
      setError(err.message || 'Đã xảy ra lỗi không mong muốn. Vui lòng thử lại.');
      setAppState('ERROR');
    }
  }, [originalImageFile, options, voiceoverScript, modelLevel]);

  const triggerFileInput = () => {
    fileInputRef.current?.click();
  };

  const resetState = () => {
    setOriginalImageFile(null);
    setOriginalImageUrl(null);
    setGeneratedPrompt('');
    setVoiceoverScript('');
    setError(null);
    setOptions({ productInfo: '', targetAudience: '', videoStyle: '' });
    setAppState('IDLE');
    if(fileInputRef.current) {
        fileInputRef.current.value = "";
    }
  };

  const handleCopyToClipboard = () => {
    if (resultTextareaRef.current) {
      resultTextareaRef.current.select();
      navigator.clipboard.writeText(resultTextareaRef.current.value);
    }
  };

  const isGeneratePromptDisabled = () => {
    return appState === 'PROCESSING_PROMPT' || appState === 'PROCESSING_VOICEOVER' || !originalImageFile || !options.productInfo.trim() || !voiceoverScript.trim();
  }

  return (
    <div className="bg-gray-50 min-h-screen text-gray-800 font-sans">
      <div className="container mx-auto px-4 py-8">
        <header className="flex items-center justify-between mb-8 md:mb-12 relative">
            <button onClick={onGoBack} className="flex items-center text-gray-500 hover:text-indigo-600 transition-colors group">
                <ArrowLeftIcon className="w-6 h-6 mr-2 transform group-hover:-translate-x-1 transition-transform"/>
                <span className="font-semibold">Trang chủ</span>
            </button>
            <div className="flex items-center space-x-2 absolute right-0 top-0">
                <span className={`text-xs font-mono px-2 py-1 rounded border ${modelLevel === 'pro' ? 'bg-purple-100 border-purple-200 text-purple-700' : 'bg-indigo-100 border-indigo-200 text-indigo-700'}`}>
                    {modelLevel === 'pro' ? 'GEMINI 3 PRO' : 'GEMINI 2.5 FLASH'}
                </span>
            </div>
            <div className="w-full text-center pointer-events-none">
                 <h1 className="text-4xl md:text-5xl font-bold text-gray-900 tracking-tight">
                    Tạo Prompt Video AI
                </h1>
                 <p className="mt-4 text-lg text-gray-600 max-w-2xl mx-auto">
                    Tạo kịch bản video quảng cáo chuyên nghiệp (tiếng Anh) cho Veo/Sora.
                </p>
            </div>
        </header>

        <main className="bg-white rounded-2xl shadow-xl p-6 md:p-10">
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 lg:gap-12 items-start">
            {/* Input Section */}
            <div className="flex flex-col items-center justify-center space-y-6">
              <h2 className="text-2xl font-semibold text-gray-700">1. Cung cấp thông tin</h2>
              <input
                type="file"
                ref={fileInputRef}
                onChange={handleFileChange}
                accept="image/*"
                className="hidden"
              />
              <div
                onClick={!originalImageUrl ? triggerFileInput : undefined}
                className="relative w-full max-w-md mx-auto aspect-video bg-gray-50 border-2 border-dashed border-gray-300 rounded-lg flex flex-col justify-center items-center text-center cursor-pointer hover:border-indigo-500 hover:bg-indigo-50 transition-colors duration-300"
              >
                {originalImageUrl ? (
                   <>
                    <img src={originalImageUrl} alt="Original Upload" className="max-h-full max-w-full object-contain rounded-md p-2" />
                     <button
                        onClick={handleRemoveImage}
                        className="absolute top-2 right-2 bg-gray-900/50 text-white rounded-full p-1.5 hover:bg-gray-900/75 transition-colors z-10"
                        aria-label="Xóa ảnh"
                    >
                        <XIcon className="w-4 h-4" />
                    </button>
                  </>
                ) : (
                  <>
                    <UploadIcon className="w-12 h-12 text-gray-400" />
                    <p className="mt-2 text-gray-500">Tải ảnh sản phẩm</p>
                    <p className="text-xs text-gray-400 mt-1">PNG, JPG, WEBP</p>
                  </>
                )}
              </div>

            <div className={`w-full max-w-md mx-auto space-y-4 transition-opacity duration-300 ${!originalImageFile ? 'opacity-50 pointer-events-none' : ''}`}>
                <div>
                    <label htmlFor="productInfo" className="block text-sm font-medium text-gray-700 mb-1">Thông tin sản phẩm <span className="text-red-500">*</span></label>
                    <textarea
                        id="productInfo" name="productInfo" rows={3} value={options.productInfo} onChange={handleOptionChange}
                        placeholder="VD: Áo thun cotton thoáng mát, phong cách năng động..."
                        className="w-full p-2 border border-gray-300 rounded-md focus:ring-indigo-500 focus:border-indigo-500"
                    />
                </div>
                 <div>
                    <label htmlFor="targetAudience" className="block text-sm font-medium text-gray-700 mb-1">Đối tượng khách hàng</label>
                    <input
                        type="text" id="targetAudience" name="targetAudience" value={options.targetAudience} onChange={handleOptionChange}
                        placeholder="VD: Giới trẻ, nhân viên văn phòng"
                        className="w-full p-2 border border-gray-300 rounded-md focus:ring-indigo-500 focus:border-indigo-500"
                    />
                </div>
                 <div>
                    <label htmlFor="videoStyle" className="block text-sm font-medium text-gray-700 mb-1">Phong cách video</label>
                    <input
                        type="text" id="videoStyle" name="videoStyle" value={options.videoStyle} onChange={handleOptionChange}
                        placeholder="VD: Năng động, sang trọng, tối giản"
                        className="w-full p-2 border border-gray-300 rounded-md focus:ring-indigo-500 focus:border-indigo-500"
                    />
                </div>

                <div className="p-4 bg-gray-100 rounded-lg space-y-3">
                    <h3 className="font-semibold text-gray-800">Tùy chọn giọng đọc</h3>
                    <div>
                         <label htmlFor="voiceoverStyle" className="block text-sm font-medium text-gray-700 mb-1">Phong cách</label>
                        <select
                            id="voiceoverStyle" name="voiceoverStyle" value={voiceoverStyle}
                            onChange={(e) => setVoiceoverStyle(e.target.value as VoiceoverStyle)}
                            className="w-full p-2 border border-gray-300 rounded-md focus:ring-indigo-500 focus:border-indigo-500"
                        >
                            <option>Năng động</option>
                            <option>Trang trọng</option>
                            <option>Thân thiện</option>
                        </select>
                    </div>
                    <button
                        onClick={handleGenerateVoiceover}
                        disabled={appState === 'PROCESSING_VOICEOVER' || !options.productInfo.trim()}
                        className="w-full flex items-center justify-center px-4 py-2 text-sm font-medium text-white bg-purple-600 rounded-md hover:bg-purple-700 disabled:bg-purple-300 transition-colors"
                    >
                       {appState === 'PROCESSING_VOICEOVER' ? (
                           <> <LoadingSpinner className="w-4 h-4 mr-2" /> Đang tạo... </>
                       ) : "Tạo giọng đọc (Tiếng Việt)"}
                    </button>
                    <textarea
                        id="voiceoverScript" name="voiceoverScript" rows={4} value={voiceoverScript}
                        onChange={(e) => setVoiceoverScript(e.target.value)}
                        placeholder="Tạo và chỉnh sửa kịch bản lồng tiếng ở đây..."
                        className="w-full p-2 border border-gray-300 rounded-md focus:ring-indigo-500 focus:border-indigo-500 mt-2"
                    />
                </div>
            </div>

              <div className="w-full flex justify-center space-x-4 pt-4">
                  <button
                    onClick={handleGeneratePrompt}
                    disabled={isGeneratePromptDisabled()}
                    className="flex items-center justify-center w-full max-w-xs px-6 py-3 bg-green-600 text-white font-semibold rounded-lg shadow-md hover:bg-green-700 disabled:bg-green-300 disabled:cursor-not-allowed focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-green-500 transition-all duration-300 transform hover:scale-105"
                  >
                    {appState === 'PROCESSING_PROMPT' ? (
                      <>
                        <LoadingSpinner className="w-5 h-5 mr-3" />
                        Đang viết...
                      </>
                    ) : (
                      <>
                        <FilmIcon className="w-5 h-5 mr-3" />
                        Tạo kịch bản (Tiếng Anh)
                      </>
                    )}
                  </button>
                   {originalImageFile && (
                    <button
                        onClick={resetState}
                        className="px-6 py-3 bg-gray-200 text-gray-700 font-semibold rounded-lg hover:bg-gray-300 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-gray-400 transition-colors"
                    >
                        Làm lại
                    </button>
                  )}
              </div>
            </div>

            {/* Output Section */}
            <div className="flex flex-col items-center justify-center space-y-6">
                 <h2 className="text-2xl font-semibold text-gray-700">2. Kịch bản Video (Tiếng Anh)</h2>
                <div className="w-full max-w-md mx-auto aspect-video bg-gray-100 rounded-lg flex justify-center items-center overflow-hidden shadow-inner p-4">
                    {appState === 'PROCESSING_PROMPT' && (
                        <div className="text-center text-gray-500">
                           <LoadingSpinner className="w-12 h-12 mx-auto" />
                           <p className="mt-4 animate-pulse">AI đang làm đạo diễn...</p>
                        </div>
                    )}
                    {(appState === 'ERROR' && error) && (
                        <div className="text-center text-red-500 p-4">
                            <ErrorIcon className="w-12 h-12 mx-auto"/>
                            <p className="mt-4 font-semibold">Lỗi!</p>
                            <p className="text-sm">{error}</p>
                        </div>
                    )}
                    {appState === 'SUCCESS' && generatedPrompt && (
                        <textarea
                            ref={resultTextareaRef}
                            readOnly
                            value={generatedPrompt}
                            className="w-full h-full bg-transparent border-none text-gray-800 resize-none focus:ring-0"
                        />
                    )}
                    {(appState !== 'PROCESSING_PROMPT' && appState !== 'ERROR' && appState !== 'SUCCESS') && (
                       <div className="text-center text-gray-400 p-4">
                          <p>Kịch bản video do AI tạo sẽ xuất hiện ở đây.</p>
                       </div>
                    )}
                </div>
                {appState === 'SUCCESS' && generatedPrompt && (
                    <button
                        onClick={handleCopyToClipboard}
                        className="flex items-center justify-center w-full max-w-xs px-6 py-3 bg-blue-600 text-white font-semibold rounded-lg shadow-md hover:bg-blue-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-blue-500 transition-all duration-300 transform hover:scale-105"
                    >
                        Sao chép kịch bản
                    </button>
                )}
            </div>
          </div>
        </main>
      </div>
    </div>
  );
};

export default VideoPromptGenerator;

import React, { useState, useCallback, useRef, useEffect } from 'react';
import { generateStyledImage, generateModelImage, generateSelfieImage, ModelPose, AspectRatio, generateBackgroundSuggestion, ProductDisplayMode, SelfieFraming, RugStyle, RugColor, RugPattern, ModelLevel } from './services/geminiService';
import { UploadIcon, SparklesIcon, LoadingSpinner, ErrorIcon, HangerIcon, UserIcon, ArrowLeftIcon, DownloadIcon, XIcon, RefreshIcon, WandIcon, ClipboardIcon, ClipboardCheckIcon, CameraIcon, ZoomInIcon } from './components/Icons';

type ClothingType = 'Áo' | 'Quần' | 'Cả bộ' | 'Váy' | 'Phụ kiện';
type FeatureMode = 'product' | 'model' | 'selfie';
type Gender = 'Nam' | 'Nữ';
type ItemStatus = 'IDLE' | 'PROCESSING' | 'SUCCESS' | 'ERROR';

// Interface for each item in the session
interface SessionItem {
    id: string;
    file: File;
    inputPreviewUrl: string; // The original uploaded image
    outputUrl?: string;      // The generated result
    videoPrompt?: string;    // For model mode
    status: ItemStatus;
    error?: string;
}

interface ProductStudioProps {
  onGoBack: () => void;
  onEnhanceImage: (imageUrl: string) => void;
  modelLevel: ModelLevel;
}

const ProductStudio: React.FC<ProductStudioProps> = ({ onGoBack, onEnhanceImage, modelLevel }) => {
  // Core state: List of session items instead of single file
  const [sessionItems, setSessionItems] = useState<SessionItem[]>([]);

  // Global App State (mostly for the big generate button)
  const [isGlobalProcessing, setIsGlobalProcessing] = useState(false);
  const [zoomImage, setZoomImage] = useState<string | null>(null);

  // Feature selection state
  const [featureMode, setFeatureMode] = useState<FeatureMode>('product');
  const [clothingType, setClothingType] = useState<ClothingType>('Áo');
  const [aspectRatio, setAspectRatio] = useState<AspectRatio>('9:16');
  const [productDisplayMode, setProductDisplayMode] = useState<ProductDisplayMode>('hanger');

  // Flatlay Rug State
  const [rugStyle, setRugStyle] = useState<RugStyle>('Tự động');
  const [rugColor, setRugColor] = useState<RugColor>('Tự động');
  const [rugPattern, setRugPattern] = useState<RugPattern>('Tự động');

  // Model-specific state
  const [gender, setGender] = useState<Gender>('Nữ');
  const [age, setAge] = useState<string>('18-25');
  const [background, setBackground] = useState<string>('');
  const [numberOfImages, setNumberOfImages] = useState<number>(1); // Only used if sessionItems.length === 1
  const [modelPose, setModelPose] = useState<ModelPose>('Dáng đứng');
  const [isGeneratingBackground, setIsGeneratingBackground] = useState<boolean>(false);
  const [copiedPromptIndex, setCopiedPromptIndex] = useState<string | null>(null);

  // Selfie specific state
  const [selfieFraming, setSelfieFraming] = useState<SelfieFraming>('Nửa thân');

  const fileInputRef = useRef<HTMLInputElement>(null);

  // Helper to read file to base64
  const fileToBase64 = (file: File): Promise<string> => {
      return new Promise((resolve, reject) => {
          const reader = new FileReader();
          reader.readAsDataURL(file);
          reader.onload = () => {
              const result = reader.result as string;
              resolve(result.split(',')[1]);
          };
          reader.onerror = error => reject(error);
      });
  };

  const handleFileChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    const files = event.target.files;
    if (files && files.length > 0) {
        const newItems: SessionItem[] = Array.from(files)
            .filter(file => file.type.startsWith('image/'))
            .map(file => ({
                id: `item_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
                file,
                inputPreviewUrl: URL.createObjectURL(file),
                status: 'IDLE'
            }));

        setSessionItems(prev => [...prev, ...newItems]);
    }
    // Reset input
    if (fileInputRef.current) fileInputRef.current.value = "";
  };

  const handleRemoveItem = (id: string, e?: React.MouseEvent) => {
    e?.stopPropagation();
    setSessionItems(prev => {
        const itemToRemove = prev.find(item => item.id === id);
        if (itemToRemove) {
            // Clean up object URL
            // URL.revokeObjectURL(itemToRemove.inputPreviewUrl); // Optional: creates flicker if removing quickly, browser handles GC eventually
        }
        return prev.filter(item => item.id !== id);
    });
  };

  const handleClearAll = () => {
      setSessionItems([]);
      setBackground('');
  };

  const handleGenerateBackground = async () => {
    // Only use the first image for background suggestion
    const firstItem = sessionItems[0];
    if (!firstItem || !clothingType) return;

    setIsGeneratingBackground(true);
    try {
        const base64String = await fileToBase64(firstItem.file);
        const suggestion = await generateBackgroundSuggestion(base64String, firstItem.file.type, clothingType, modelLevel);
        setBackground(suggestion.trim().replace(/^"|"$/g, '')); 
    } catch (err: any) {
        console.error("BG Gen Error", err);
    } finally {
        setIsGeneratingBackground(false);
    }
  };

  // The Core Worker Function for a SINGLE Item
  const processItem = async (item: SessionItem): Promise<SessionItem> => {
      try {
          const base64String = await fileToBase64(item.file);

          // Determine count: if batch (multiple items), force 1. If single item, use slider.
          // However, this function generates ONE result for THIS item.
          // If the user wants multiple variants for a SINGLE uploaded image, we handle that in the loop or UI.
          // For simplicity in this architectural change: 
          // If uploading multiple images -> 1 result per image.
          // If uploading 1 image -> N results (based on slider). 
          // *But `processItem` returns a single updated SessionItem.*
          // If count > 1 (single image mode), we might need to fork this logic.
          // *Correction:* The requirement says "if upload multiple images... create only 1 output image".
          // So let's handle the API call.

          // Logic:
          // If we are in "Batch Mode" (items > 1), we call API with count=1.
          // If we are in "Single Mode" (items === 1), we call API with count=numberOfImages.
          // Wait, SessionItem structure holds `outputUrl` (singular).
          // To support "Single Mode" with multiple outputs, we should strictly follow the prompt:
          // "if upload multiple images... only 1 output".
          // Implicitly: If upload 1 image, we can generate multiple.
          // But to keep the UI consistent (grid of cards), let's simplify:
          // EACH Item card represents 1 generation request. 

          const effectiveCount = 1; // We process per item card.

          if (featureMode === 'product') {
              const urls = await generateStyledImage(
                  base64String, item.file.type, clothingType, aspectRatio, productDisplayMode, effectiveCount, modelLevel,
                  productDisplayMode === 'flatlay' ? { style: rugStyle, color: rugColor, pattern: rugPattern } : undefined
              );
              return { ...item, outputUrl: `data:image/jpeg;base64,${urls[0]}`, status: 'SUCCESS', error: undefined };

          } else if (featureMode === 'model') {
              const results = await generateModelImage(base64String, item.file.type, {
                  clothingType, gender, age, background, numberOfImages: effectiveCount, pose: modelPose, aspectRatio
              }, modelLevel);
              return { ...item, outputUrl: results[0].imageUrl, videoPrompt: results[0].videoPrompt, status: 'SUCCESS', error: undefined };

          } else { // selfie
              const urls = await generateSelfieImage(base64String, item.file.type, clothingType, effectiveCount, gender, selfieFraming, modelLevel);
              return { ...item, outputUrl: `data:image/jpeg;base64,${urls[0]}`, status: 'SUCCESS', error: undefined };
          }
      } catch (e: any) {
          return { ...item, status: 'ERROR', error: e.message || 'Error generating image' };
      }
  };

  // Generate All (Batch)
  const handleGenerateAll = async () => {
    if (sessionItems.length === 0) return;
    if (featureMode === 'model' && !background.trim()) {
        alert("Vui lòng nhập mô tả bối cảnh");
        return;
    }

    setIsGlobalProcessing(true);

    // If there is ONLY 1 item and user requested N images (slider > 1).
    // We need to clone the input item N times to simulate batch processing for variants.
    if (sessionItems.length === 1 && numberOfImages > 1) {
        const seedItem = sessionItems[0];
        const newItems: SessionItem[] = [];
        // Keep the original as the first one
        newItems.push({...seedItem, status: 'PROCESSING'});
        // Add copies
        for(let i = 1; i < numberOfImages; i++) {
             newItems.push({
                 ...seedItem,
                 id: seedItem.id + `_variant_${i}`,
                 status: 'PROCESSING'
             });
        }
        setSessionItems(newItems);

        // Now process them in parallel
        const promises = newItems.map(item => processItem(item));
        const results = await Promise.all(promises);

        setSessionItems(results);
    } else {
        // Normal Batch Mode (or Single Mode with count=1)
        // Mark all IDLE or ERROR items as PROCESSING
        setSessionItems(prev => prev.map(item => 
            (item.status === 'IDLE' || item.status === 'ERROR' || item.status === 'SUCCESS') 
            ? { ...item, status: 'PROCESSING', error: undefined } 
            : item
        ));

        // Create a working copy of current items to process
        // We act on the *current* list state
        const itemsToProcess = sessionItems.map(item => ({...item, status: 'PROCESSING' as ItemStatus}));

        // Execute in parallel
        // Note: For a real app, might want to limit concurrency (e.g., p-limit) to avoid rate limits.
        // For Gemini API, 5-10 concurrent requests is usually fine.

        // We need to update state as they finish? Or wait for all?
        // Let's use map/Promise.all to get final results, then update.
        // Actually, updating one by one gives better UX.

        const updateItemResult = (updatedItem: SessionItem) => {
             setSessionItems(prev => prev.map(i => i.id === updatedItem.id ? updatedItem : i));
        };

        const promises = itemsToProcess.map(async (item) => {
             const result = await processItem(item);
             updateItemResult(result);
        });

        await Promise.all(promises);
    }

    setIsGlobalProcessing(false);
  };

  // Regenerate Single Item
  const handleRegenerateItem = async (id: string) => {
      const itemToRegen = sessionItems.find(i => i.id === id);
      if (!itemToRegen) return;
      if (featureMode === 'model' && !background.trim()) {
          alert("Vui lòng nhập bối cảnh");
          return;
      }

      // Update status to processing
      setSessionItems(prev => prev.map(i => i.id === id ? { ...i, status: 'PROCESSING', error: undefined } : i));

      // Process
      const result = await processItem(itemToRegen);

      // Update result
      setSessionItems(prev => prev.map(i => i.id === id ? result : i));
  };

  const triggerFileInput = () => {
    fileInputRef.current?.click();
  };

  const handleCopyToClipboard = (textToCopy: string, id: string) => {
    navigator.clipboard.writeText(textToCopy);
    setCopiedPromptIndex(id);
    setTimeout(() => setCopiedPromptIndex(null), 2000);
  };

  const isGenerateButtonDisabled = () => {
    if (isGlobalProcessing || sessionItems.length === 0) return true;
    if (featureMode === 'model' && !background.trim()) return true;
    return false;
  }

  return (
    <div className="flex flex-col h-screen overflow-hidden bg-slate-900 text-slate-200">
      {/* Zoom Modal */}
      {zoomImage && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/90 backdrop-blur-sm p-4 animate-fade-in" onClick={() => setZoomImage(null)}>
            <button className="absolute top-4 right-4 text-white hover:text-gray-300 p-2 bg-white/10 rounded-full" onClick={() => setZoomImage(null)}>
                <XIcon className="w-8 h-8" />
            </button>
            <img src={zoomImage} alt="Zoom" className="max-w-full max-h-[90vh] object-contain rounded-lg shadow-2xl" onClick={(e) => e.stopPropagation()} />
        </div>
      )}

      {/* Header */}
      <header className="flex-none h-16 border-b border-slate-700 bg-slate-800/50 backdrop-blur-md flex items-center px-6 justify-between z-20">
        <div className="flex items-center">
            <button onClick={onGoBack} className="flex items-center text-slate-400 hover:text-white transition-colors mr-4">
                <ArrowLeftIcon className="w-5 h-5 mr-2"/>
                <span className="font-medium">Trang chủ</span>
            </button>
            <div className="h-6 w-px bg-slate-700 mx-4"></div>
            <h1 className="text-lg font-bold text-white tracking-tight">Studio Sản phẩm AI (Batch Mode)</h1>
        </div>
        <div className="flex items-center space-x-2">
