                    <div className="grid gap-6 grid-cols-1 md:grid-cols-2 xl:grid-cols-3">
                        {sessionItems.map((item) => (
                            <div key={item.id} className="bg-slate-800 rounded-2xl p-3 border border-slate-700 hover:border-slate-500 transition-all duration-300 shadow-xl flex flex-col h-full group relative">

                                {/* Status Overlay / Image */}
                                <div className="relative rounded-xl overflow-hidden aspect-[9/16] bg-slate-900 mb-3">
                                    {/* Small Input Thumbnail Overlay */}
                                    <div className="absolute top-2 left-2 z-20 w-12 h-16 rounded border border-white/20 overflow-hidden shadow-lg">
                                        <img src={item.inputPreviewUrl} alt="Input" className="w-full h-full object-cover" />
                                    </div>

                                    {/* Regenerate Button Specific to this Item */}
                                    <button 
                                        onClick={() => handleRegenerateItem(item.id)}
                                        disabled={item.status === 'PROCESSING'}
                                        className="absolute top-2 right-2 z-20 p-2 bg-black/60 backdrop-blur-md rounded-full text-white hover:bg-indigo-600 transition-colors disabled:opacity-50"
                                        title="Tạo lại riêng ảnh này"
                                    >
                                        {item.status === 'PROCESSING' ? <LoadingSpinner className="w-4 h-4" /> : <RefreshIcon className="w-4 h-4" />}
                                    </button>

                                    {/* Main Content */}
                                    {item.status === 'PROCESSING' && !item.outputUrl && (
                                        <div className="absolute inset-0 flex flex-col items-center justify-center bg-slate-800/80 backdrop-blur-sm z-10">
                                            <LoadingSpinner className="w-10 h-10 text-indigo-500 mb-2" />
                                            <span className="text-xs text-indigo-300">Đang tạo...</span>
                                        </div>
                                    )}

                                    {item.status === 'ERROR' ? (
                                        <div className="absolute inset-0 flex flex-col items-center justify-center bg-slate-800 text-red-400 p-4 text-center">
                                            <ErrorIcon className="w-10 h-10 mb-2" />
                                            <p className="text-xs">{item.error || 'Lỗi tạo ảnh'}</p>
                                        </div>
                                    ) : item.outputUrl ? (
                                        <>
                                            <img src={item.outputUrl} alt="Generated" className="w-full h-full object-cover" />
                                            {/* Action Overlay */}
                                            <div className="absolute inset-0 bg-gradient-to-t from-black/60 via-transparent to-transparent opacity-0 group-hover:opacity-100 transition-opacity duration-300 flex flex-col justify-end p-4 z-10">
                                                <div className="flex space-x-2 justify-end">
                                                    <button onClick={() => setZoomImage(item.outputUrl!)} className="p-2 bg-white/10 backdrop-blur-md rounded-lg text-white hover:bg-white/20 transition-colors" title="Phóng to">
                                                        <ZoomInIcon className="w-5 h-5" />
                                                    </button>
                                                    <button onClick={() => onEnhanceImage(item.outputUrl!)} className="p-2 bg-white/10 backdrop-blur-md rounded-lg text-white hover:bg-white/20 transition-colors" title="Nâng cấp ảnh">
                                                        <WandIcon className="w-5 h-5" />
                                                    </button>
                                                    <a href={item.outputUrl} download={`${item.id}.jpg`} className="p-2 bg-indigo-600 rounded-lg text-white hover:bg-indigo-700 transition-colors" title="Tải xuống">
                                                        <DownloadIcon className="w-5 h-5" />
                                                    </a>
                                                </div>
                                            </div>
                                        </>
                                    ) : (
                                        // IDLE State - Show placeholder or waiting
                                        <div className="w-full h-full flex flex-col items-center justify-center text-slate-600">
                                            <SparklesIcon className="w-10 h-10 mb-2 opacity-20" />
                                            <span className="text-xs">Sẵn sàng tạo</span>
                                        </div>
                                    )}
                                </div>

                                {/* Video Prompt info if available */}
                                {item.videoPrompt && (
                                    <div className="bg-slate-900/50 rounded-lg p-3 border border-slate-700/50 mt-auto">
                                        <div className="flex items-center justify-between mb-2">
                                            <span className="text-[10px] font-bold text-indigo-400 uppercase tracking-wider">Veo 3.1 Prompt</span>
                                            <button onClick={() => handleCopyToClipboard(item.videoPrompt!, item.id)} className="text-slate-400 hover:text-white">
                                                {copiedPromptIndex === item.id ? <ClipboardCheckIcon className="w-3 h-3 text-green-400" /> : <ClipboardIcon className="w-3 h-3" />}
                                            </button>
                                        </div>
                                        <p className="text-xs text-slate-400 line-clamp-2 hover:line-clamp-none transition-all cursor-pointer" title={item.videoPrompt}>
                                            {item.videoPrompt}
                                        </p>
                                    </div>
                                )}
                            </div>
                        ))}
                    </div>
                </div>
            )}

        </div>
      </div>
    </div>
  );
};

export default ProductStudio;

import React, { useState, useCallback, useRef, useEffect } from 'react';
import { generateStyledImage, generateModelImage, generateSelfieImage, ModelPose, AspectRatio, generateBackgroundSuggestion, ProductDisplayMode, SelfieFraming, RugStyle, RugColor, RugPattern, ModelLevel } from './services/geminiService';
import { UploadIcon, SparklesIcon, LoadingSpinner, ErrorIcon, HangerIcon, UserIcon, ArrowLeftIcon, DownloadIcon, XIcon, RefreshIcon, WandIcon, ClipboardIcon, ClipboardCheckIcon, CameraIcon, ZoomInIcon } from './components/Icons';

type ClothingType = 'Áo' | 'Quần' | 'Cả bộ' | 'Váy' | 'Phụ kiện';
type FeatureMode = 'product' | 'model' | 'selfie';
type Gender = 'Nam' | 'Nữ';
type ItemStatus = 'IDLE' | 'PROCESSING' | 'SUCCESS' | 'ERROR';

// Interface for each item in the session
interface SessionItem {
    id: string;
    file: File;
    inputPreviewUrl: string; // The original uploaded image
    outputUrl?: string;      // The generated result
    videoPrompt?: string;    // For model mode
    status: ItemStatus;
    error?: string;
}

interface ProductStudioProps {
  onGoBack: () => void;
  onEnhanceImage: (imageUrl: string) => void;
  modelLevel: ModelLevel;
}

const ProductStudio: React.FC<ProductStudioProps> = ({ onGoBack, onEnhanceImage, modelLevel }) => {
  // Core state: List of session items instead of single file
  const [sessionItems, setSessionItems] = useState<SessionItem[]>([]);

  // Global App State (mostly for the big generate button)
  const [isGlobalProcessing, setIsGlobalProcessing] = useState(false);
  const [zoomImage, setZoomImage] = useState<string | null>(null);

  // Feature selection state
  const [featureMode, setFeatureMode] = useState<FeatureMode>('product');
  const [clothingType, setClothingType] = useState<ClothingType>('Áo');
  const [aspectRatio, setAspectRatio] = useState<AspectRatio>('9:16');
  const [productDisplayMode, setProductDisplayMode] = useState<ProductDisplayMode>('hanger');

  // Flatlay Rug State
  const [rugStyle, setRugStyle] = useState<RugStyle>('Tự động');
  const [rugColor, setRugColor] = useState<RugColor>('Tự động');
  const [rugPattern, setRugPattern] = useState<RugPattern>('Tự động');

  // Model-specific state
  const [gender, setGender] = useState<Gender>('Nữ');
  const [age, setAge] = useState<string>('18-25');
  const [background, setBackground] = useState<string>('');
  const [numberOfImages, setNumberOfImages] = useState<number>(1); // Only used if sessionItems.length === 1
  const [modelPose, setModelPose] = useState<ModelPose>('Dáng đứng');
  const [isGeneratingBackground, setIsGeneratingBackground] = useState<boolean>(false);
  const [copiedPromptIndex, setCopiedPromptIndex] = useState<string | null>(null);

  // Selfie specific state
  const [selfieFraming, setSelfieFraming] = useState<SelfieFraming>('Nửa thân');

  const fileInputRef = useRef<HTMLInputElement>(null);

  // Helper to read file to base64
  const fileToBase64 = (file: File): Promise<string> => {
      return new Promise((resolve, reject) => {
          const reader = new FileReader();
          reader.readAsDataURL(file);
          reader.onload = () => {
              const result = reader.result as string;
              resolve(result.split(',')[1]);
          };
          reader.onerror = error => reject(error);
      });
  };

  const handleFileChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    const files = event.target.files;
    if (files && files.length > 0) {
        const newItems: SessionItem[] = Array.from(files)
            .filter((file: File) => file.type.startsWith('image/'))
            .map((file: File) => ({
                id: `item_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
                file,
                inputPreviewUrl: URL.createObjectURL(file),
                status: 'IDLE'
            }));

        setSessionItems(prev => [...prev, ...newItems]);
    }
    // Reset input
    if (fileInputRef.current) fileInputRef.current.value = "";
  };

  const handleRemoveItem = (id: string, e?: React.MouseEvent) => {
    e?.stopPropagation();
    setSessionItems(prev => {
        const itemToRemove = prev.find(item => item.id === id);
        if (itemToRemove) {
            // Clean up object URL
            // URL.revokeObjectURL(itemToRemove.inputPreviewUrl); // Optional: creates flicker if removing quickly, browser handles GC eventually
        }
        return prev.filter(item => item.id !== id);
    });
  };

  const handleClearAll = () => {
      setSessionItems([]);
      setBackground('');
  };

  const handleGenerateBackground = async () => {
    // Only use the first image for background suggestion
    const firstItem = sessionItems[0];
    if (!firstItem || !clothingType) return;

    setIsGeneratingBackground(true);
    try {
        const base64String = await fileToBase64(firstItem.file);
        const suggestion = await generateBackgroundSuggestion(base64String, firstItem.file.type, clothingType, modelLevel);
        setBackground(suggestion.trim().replace(/^"|"$/g, '')); 
    } catch (err: any) {
        console.error("BG Gen Error", err);
    } finally {
        setIsGeneratingBackground(false);
    }
  };

  // The Core Worker Function for a SINGLE Item
  const processItem = async (item: SessionItem): Promise<SessionItem> => {
      try {
          const base64String = await fileToBase64(item.file);

          // Determine count: if batch (multiple items), force 1. If single item, use slider.
          // However, this function generates ONE result for THIS item.
          // If the user wants multiple variants for a SINGLE uploaded image, we handle that in the loop or UI.
          // For simplicity in this architectural change: 
          // If uploading multiple images -> 1 result per image.
          // If uploading 1 image -> N results (based on slider). 
          // *But `processItem` returns a single updated SessionItem.*
          // If count > 1 (single image mode), we might need to fork this logic.
          // *Correction:* The requirement says "if upload multiple images... create only 1 output image".
          // So let's handle the API call.

          // Logic:
          // If we are in "Batch Mode" (items > 1), we call API with count=1.
          // If we are in "Single Mode" (items === 1), we call API with count=numberOfImages.
          // Wait, SessionItem structure holds `outputUrl` (singular).
          // To support "Single Mode" with multiple outputs, we should strictly follow the prompt:
          // "if upload multiple images... only 1 output".
          // Implicitly: If upload 1 image, we can generate multiple.
          // But to keep the UI consistent (grid of cards), let's simplify:
          // EACH Item card represents 1 generation request. 

          const effectiveCount = 1; // We process per item card.

          if (featureMode === 'product') {
              const urls = await generateStyledImage(
                  base64String, item.file.type, clothingType, aspectRatio, productDisplayMode, effectiveCount, modelLevel,
                  productDisplayMode === 'flatlay' ? { style: rugStyle, color: rugColor, pattern: rugPattern } : undefined
              );
              return { ...item, outputUrl: `data:image/jpeg;base64,${urls[0]}`, status: 'SUCCESS', error: undefined };

          } else if (featureMode === 'model') {
              const results = await generateModelImage(base64String, item.file.type, {
                  clothingType, gender, age, background, numberOfImages: effectiveCount, pose: modelPose, aspectRatio
              }, modelLevel);
              return { ...item, outputUrl: results[0].imageUrl, videoPrompt: results[0].videoPrompt, status: 'SUCCESS', error: undefined };

          } else { // selfie
              const urls = await generateSelfieImage(base64String, item.file.type, clothingType, effectiveCount, gender, selfieFraming, modelLevel);
              return { ...item, outputUrl: `data:image/jpeg;base64,${urls[0]}`, status: 'SUCCESS', error: undefined };
          }
      } catch (e: any) {
          return { ...item, status: 'ERROR', error: e.message || 'Error generating image' };
      }
  };

  // Generate All (Batch)
  const handleGenerateAll = async () => {
    if (sessionItems.length === 0) return;
    if (featureMode === 'model' && !background.trim()) {
        alert("Vui lòng nhập mô tả bối cảnh");
        return;
    }

    setIsGlobalProcessing(true);

    // If there is ONLY 1 item and user requested N images (slider > 1).
    // We need to clone the input item N times to simulate batch processing for variants.
    if (sessionItems.length === 1 && numberOfImages > 1) {
        const seedItem = sessionItems[0];
        const newItems: SessionItem[] = [];
        // Keep the original as the first one
        newItems.push({...seedItem, status: 'PROCESSING'});
        // Add copies
        for(let i = 1; i < numberOfImages; i++) {
             newItems.push({
                 ...seedItem,
                 id: seedItem.id + `_variant_${i}`,
                 status: 'PROCESSING'
             });
        }
        setSessionItems(newItems);

        // Now process them in parallel
        const promises = newItems.map(item => processItem(item));
        const results = await Promise.all(promises);

        setSessionItems(results);
    } else {
        // Normal Batch Mode (or Single Mode with count=1)
        // Mark all IDLE or ERROR items as PROCESSING
        setSessionItems(prev => prev.map(item => 
            (item.status === 'IDLE' || item.status === 'ERROR' || item.status === 'SUCCESS') 
            ? { ...item, status: 'PROCESSING', error: undefined } 
            : item
        ));

        // Create a working copy of current items to process
        // We act on the *current* list state
        const itemsToProcess = sessionItems.map(item => ({...item, status: 'PROCESSING' as ItemStatus}));

        // Execute in parallel
        // Note: For a real app, might want to limit concurrency (e.g., p-limit) to avoid rate limits.
        // For Gemini API, 5-10 concurrent requests is usually fine.

        // We need to update state as they finish? Or wait for all?
        // Let's use map/Promise.all to get final results, then update.
        // Actually, updating one by one gives better UX.

        const updateItemResult = (updatedItem: SessionItem) => {
             setSessionItems(prev => prev.map(i => i.id === updatedItem.id ? updatedItem : i));
        };

        const promises = itemsToProcess.map(async (item) => {
             const result = await processItem(item);
             updateItemResult(result);
        });

        await Promise.all(promises);
    }

    setIsGlobalProcessing(false);
  };

  // Regenerate Single Item
  const handleRegenerateItem = async (id: string) => {
      const itemToRegen = sessionItems.find(i => i.id === id);
      if (!itemToRegen) return;
      if (featureMode === 'model' && !background.trim()) {
          alert("Vui lòng nhập bối cảnh");
          return;
      }

      // Update status to processing
      setSessionItems(prev => prev.map(i => i.id === id ? { ...i, status: 'PROCESSING', error: undefined } : i));

      // Process
      const result = await processItem(itemToRegen);

      // Update result
      setSessionItems(prev => prev.map(i => i.id === id ? result : i));
  };

  const triggerFileInput = () => {
    fileInputRef.current?.click();
  };

  const handleCopyToClipboard = (textToCopy: string, id: string) => {
    navigator.clipboard.writeText(textToCopy);
    setCopiedPromptIndex(id);
    setTimeout(() => setCopiedPromptIndex(null), 2000);
  };

  const isGenerateButtonDisabled = () => {
    if (isGlobalProcessing || sessionItems.length === 0) return true;
    if (featureMode === 'model' && !background.trim()) return true;
    return false;
  }

  return (
    <div className="flex flex-col h-screen overflow-hidden bg-slate-900 text-slate-200">
      {/* Zoom Modal */}
      {zoomImage && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/90 backdrop-blur-sm p-4 animate-fade-in" onClick={() => setZoomImage(null)}>
            <button className="absolute top-4 right-4 text-white hover:text-gray-300 p-2 bg-white/10 rounded-full" onClick={() => setZoomImage(null)}>
                <XIcon className="w-8 h-8" />
            </button>
            <img src={zoomImage} alt="Zoom" className="max-w-full max-h-[90vh] object-contain rounded-lg shadow-2xl" onClick={(e) => e.stopPropagation()} />
        </div>
      )}

      {/* Header */}
      <header className="flex-none h-16 border-b border-slate-700 bg-slate-800/50 backdrop-blur-md flex items-center px-6 justify-between z-20">
        <div className="flex items-center">
            <button onClick={onGoBack} className="flex items-center text-slate-400 hover:text-white transition-colors mr-4">
                <ArrowLeftIcon className="w-5 h-5 mr-2"/>
                <span className="font-medium">Trang chủ</span>
            </button>
            <div className="h-6 w-px bg-slate-700 mx-4"></div>
            <h1 className="text-lg font-bold text-white tracking-tight">Studio Sản phẩm AI (Batch Mode)</h1>
        </div>
        <div className="flex items-center space-x-2">
            <span className={`text-xs font-mono px-2 py-1 rounded border ${modelLevel === 'pro' ? 'bg-purple-500/20 border-purple-500/30 text-purple-300' : 'bg-indigo-500/10 border-indigo-500/20 text-indigo-400'}`}>
                {modelLevel === 'pro' ? 'GEMINI 3 PRO' : 'GEMINI 2.5 FLASH'}
            </span>
        </div>
      </header>

      {/* Main Layout */}
      <div className="flex-1 flex overflow-hidden">

        {/* Left Sidebar: Controls */}
        <div className="w-full md:w-[400px] lg:w-[450px] flex-none border-r border-slate-700 bg-slate-800/50 overflow-y-auto custom-scrollbar">
            <div className="p-6 space-y-8">

                {/* 1. Image Upload (Multiple) */}
                <div className="space-y-3">
                    <div className="flex justify-between items-center">
                        <h2 className="text-sm font-bold text-slate-400 uppercase tracking-wider">1. Ảnh gốc ({sessionItems.length})</h2>
                        {sessionItems.length > 0 && (
                            <button onClick={handleClearAll} className="text-xs text-red-400 hover:text-red-300 underline">Xóa hết</button>
                        )}
                    </div>

                    <input type="file" ref={fileInputRef} onChange={handleFileChange} accept="image/*" multiple className="hidden" />

                    {sessionItems.length === 0 ? (
                        <div 
                            onClick={triggerFileInput}
                            className="relative aspect-[3/2] w-full rounded-xl border-2 border-dashed border-slate-600 bg-slate-800/50 hover:border-indigo-400 hover:bg-slate-700 transition-all duration-300 flex flex-col items-center justify-center cursor-pointer"
                        >
                            <UploadIcon className="w-10 h-10 text-slate-500 mx-auto mb-3" />
                            <p className="text-slate-300 font-medium">Tải ảnh (Chọn nhiều)</p>
                            <p className="text-xs text-slate-500 mt-1">JPG, PNG</p>
                        </div>
                    ) : (
                        <div className="grid grid-cols-3 gap-2">
                            {sessionItems.map((item) => (
                                <div key={item.id} className="relative aspect-square rounded-lg overflow-hidden border border-slate-600 group">
                                    <img src={item.inputPreviewUrl} alt="Preview" className="w-full h-full object-cover" />
                                    <button 
                                        onClick={(e) => handleRemoveItem(item.id, e)} 
                                        className="absolute top-1 right-1 bg-black/60 text-white p-1 rounded-full opacity-0 group-hover:opacity-100 transition-opacity hover:bg-red-500"
                                    >
                                        <XIcon className="w-3 h-3" />
                                    </button>
                                </div>
                            ))}
                            <button 
                                onClick={triggerFileInput}
                                className="aspect-square rounded-lg border-2 border-dashed border-slate-600 flex flex-col items-center justify-center text-slate-500 hover:border-indigo-400 hover:text-indigo-400 hover:bg-slate-800 transition-all"
                            >
                                <UploadIcon className="w-6 h-6" />
                                <span className="text-[10px] mt-1 font-medium">Thêm</span>
                            </button>
                        </div>
                    )}
                </div>

                {/* 2. Mode Selection */}
                <div className={`space-y-3 transition-opacity duration-300 ${sessionItems.length === 0 ? 'opacity-50 pointer-events-none' : ''}`}>
                    <h2 className="text-sm font-bold text-slate-400 uppercase tracking-wider">2. Chế độ tạo</h2>
                    <div className="grid grid-cols-3 gap-2 p-1 bg-slate-900 rounded-xl">
                        {[
                            { id: 'product', icon: HangerIcon, label: 'Sản phẩm' },
                            { id: 'model', icon: UserIcon, label: 'Mẫu ảo' },
                            { id: 'selfie', icon: CameraIcon, label: 'Selfie' }
                        ].map(mode => (
                            <button
                                key={mode.id}
                                onClick={() => setFeatureMode(mode.id as FeatureMode)}
                                className={`flex flex-col items-center justify-center py-3 rounded-lg text-xs font-semibold transition-all duration-200
                                    ${featureMode === mode.id ? 'bg-indigo-600 text-white shadow-lg' : 'text-slate-400 hover:text-white hover:bg-slate-800'}
                                `}
                            >
                                <mode.icon className="w-5 h-5 mb-1" />
                                {mode.label}
                            </button>
                        ))}
                    </div>
                </div>

                {/* 3. Detailed Settings */}
                <div className={`space-y-6 transition-opacity duration-300 ${sessionItems.length === 0 ? 'opacity-50 pointer-events-none' : ''}`}>

                    {/* Clothing Type */}
                    <div className="space-y-2">
                        <label className="text-xs font-medium text-slate-400">Loại trang phục</label>
                        <div className="flex flex-wrap gap-2">
                            {(['Áo', 'Quần', 'Cả bộ', 'Váy', 'Phụ kiện'] as ClothingType[]).map((type) => (
                                <button
                                    key={type}
                                    onClick={() => setClothingType(type)}
                                    className={`px-3 py-1.5 rounded-full text-xs font-medium border transition-all
                                        ${clothingType === type ? 'bg-indigo-500/20 border-indigo-500 text-indigo-300' : 'bg-slate-800 border-slate-700 text-slate-400 hover:border-slate-500'}
                                    `}
                                >
                                    {type}
                                </button>
                            ))}
                        </div>
                    </div>

                    {/* Aspect Ratio */}
                     {featureMode !== 'selfie' && (
                        <div className="space-y-2">
                            <label className="text-xs font-medium text-slate-400">Tỉ lệ khung hình</label>
                            <div className="flex bg-slate-900 rounded-lg p-1">
                                {(['9:16', '1:1', '4:5', '16:9'] as AspectRatio[]).map((ratio) => (
                                    <button
                                        key={ratio}
                                        onClick={() => setAspectRatio(ratio)}
                                        className={`flex-1 py-1.5 rounded text-xs font-medium transition-all
                                            ${aspectRatio === ratio ? 'bg-slate-700 text-white shadow' : 'text-slate-500 hover:text-slate-300'}
                                        `}
                                    >
                                        {ratio}
                                    </button>
                                ))}
                            </div>
                        </div>
                    )}

                    {/* Feature Specific Settings */}
                    {featureMode === 'product' && (
                        <div className="space-y-4 p-4 bg-slate-900/50 rounded-xl border border-slate-700">
                             <div className="space-y-2">
                                <label className="text-xs font-medium text-slate-400">Cách trình bày</label>
                                <div className="grid grid-cols-2 gap-2">
                                    <button onClick={() => setProductDisplayMode('hanger')} className={`py-2 px-3 rounded-lg border text-xs font-medium ${productDisplayMode === 'hanger' ? 'bg-indigo-500/20 border-indigo-500 text-white' : 'bg-slate-800 border-slate-700 text-slate-400'}`}>Treo móc / Kệ</button>
                                    <button onClick={() => setProductDisplayMode('flatlay')} className={`py-2 px-3 rounded-lg border text-xs font-medium ${productDisplayMode === 'flatlay' ? 'bg-indigo-500/20 border-indigo-500 text-white' : 'bg-slate-800 border-slate-700 text-slate-400'}`}>Flatlay (Trải sàn)</button>
                                </div>
                            </div>

                             {productDisplayMode === 'flatlay' && (
                                <div className="space-y-4 pt-2 border-t border-slate-700/50 animate-fade-in-up">
                                    <div className="space-y-2">
                                        <label className="text-xs font-medium text-slate-400 block">Loại thảm</label>
                                        <select value={rugStyle} onChange={(e) => setRugStyle(e.target.value as RugStyle)} className="w-full bg-slate-800 border border-slate-600 rounded-lg px-3 py-2 text-sm text-white focus:ring-1 focus:ring-indigo-500 outline-none">
                                            {(['Tự động', 'Lông mềm (Fur)', 'Thảm Ba Tư (Vintage)', 'Dệt Boho', 'Tối giản (Minimalist)', 'Lụa sang trọng'] as RugStyle[]).map(s => (
                                                <option key={s} value={s}>{s}</option>
                                            ))}
                                        </select>
                                    </div>
                                    <div className="space-y-2">
                                        <label className="text-xs font-medium text-slate-400 block">Màu sắc thảm</label>
                                        <select value={rugColor} onChange={(e) => setRugColor(e.target.value as RugColor)} className="w-full bg-slate-800 border border-slate-600 rounded-lg px-3 py-2 text-sm text-white focus:ring-1 focus:ring-indigo-500 outline-none">
                                            {(['Tự động', 'Trắng/Kem', 'Be (Beige)', 'Xám', 'Pastel', 'Tối màu'] as RugColor[]).map(c => (
                                                <option key={c} value={c}>{c}</option>
                                            ))}
                                        </select>
                                    </div>
                                    <div className="space-y-2">
                                        <label className="text-xs font-medium text-slate-400 block">Họa tiết thảm</label>
                                        <select value={rugPattern} onChange={(e) => setRugPattern(e.target.value as RugPattern)} className="w-full bg-slate-800 border border-slate-600 rounded-lg px-3 py-2 text-sm text-white focus:ring-1 focus:ring-indigo-500 outline-none">
                                            {(['Tự động', 'Trơn (Solid)', 'Hình học (Geometric)', 'Vân sóng', 'Trừu tượng'] as RugPattern[]).map(p => (
                                                <option key={p} value={p}>{p}</option>
                                            ))}
                                        </select>
                                    </div>
                                </div>
                            )}
                        </div>
                    )}

                    {featureMode === 'model' && (
                        <div className="space-y-4 p-4 bg-slate-900/50 rounded-xl border border-slate-700">
                            <div className="grid grid-cols-2 gap-4">
                                <div>
                                    <label className="text-xs font-medium text-slate-400 block mb-1.5">Giới tính</label>
                                    <select value={gender} onChange={(e) => setGender(e.target.value as Gender)} className="w-full bg-slate-800 border border-slate-600 rounded-lg px-3 py-2 text-sm text-white focus:ring-1 focus:ring-indigo-500 focus:border-indigo-500 outline-none">
                                        <option value="Nữ">Nữ</option>
                                        <option value="Nam">Nam</option>
                                    </select>
                                </div>
                                <div>
                                    <label className="text-xs font-medium text-slate-400 block mb-1.5">Độ tuổi</label>
                                    <select value={age} onChange={(e) => setAge(e.target.value)} className="w-full bg-slate-800 border border-slate-600 rounded-lg px-3 py-2 text-sm text-white focus:ring-1 focus:ring-indigo-500 focus:border-indigo-500 outline-none">
                                        <option value="18-25">18-25</option>
                                        <option value="26-35">26-35</option>
                                    </select>
                                </div>
                            </div>
                            <div>
                                <label className="text-xs font-medium text-slate-400 block mb-1.5">Dáng Pose</label>
                                <select value={modelPose} onChange={(e) => setModelPose(e.target.value as ModelPose)} className="w-full bg-slate-800 border border-slate-600 rounded-lg px-3 py-2 text-sm text-white focus:ring-1 focus:ring-indigo-500 focus:border-indigo-500 outline-none">
                                    <option value="Dáng đứng">Dáng đứng</option>
                                    <option value="Dáng đi">Dáng đi</option>
                                    <option value="Giới thiệu (Cầm móc)">Cầm móc áo</option>
                                    <option value="Giới thiệu (Chỉ mặc)">Chỉ mặc & Tạo dáng</option>
                                </select>
                            </div>
                            <div className="space-y-2">
                                <label className="text-xs font-medium text-slate-400 block">Bối cảnh</label>
                                <div className="relative">
                                    <input 
                                        type="text" 
                                        value={background} 
                                        onChange={(e) => setBackground(e.target.value)} 
                                        placeholder="VD: Đường phố Sài Gòn, Studio..."
                                        className="w-full bg-slate-800 border border-slate-600 rounded-lg pl-3 pr-10 py-2 text-sm text-white focus:ring-1 focus:ring-indigo-500 outline-none"
                                    />
                                    <button 
                                        onClick={handleGenerateBackground}
                                        disabled={isGeneratingBackground || !clothingType || sessionItems.length === 0}
                                        className="absolute right-1 top-1 p-1.5 text-indigo-400 hover:text-indigo-300 disabled:opacity-50"
                                        title="Tự động gợi ý từ ảnh đầu tiên"
                                    >
                                        {isGeneratingBackground ? <LoadingSpinner className="w-4 h-4" /> : <SparklesIcon className="w-4 h-4" />}
                                    </button>
                                </div>
                            </div>
                        </div>
                    )}

                    {featureMode === 'selfie' && (
                        <div className="space-y-4 p-4 bg-slate-900/50 rounded-xl border border-slate-700">
                             <div className="space-y-2">
                                <label className="text-xs font-medium text-slate-400 block mb-1.5">Giới tính</label>
                                <select value={gender} onChange={(e) => setGender(e.target.value as Gender)} className="w-full bg-slate-800 border border-slate-600 rounded-lg px-3 py-2 text-sm text-white focus:ring-1 focus:ring-indigo-500 focus:border-indigo-500 outline-none">
                                    <option value="Nữ">Nữ</option>
                                    <option value="Nam">Nam</option>
                                </select>
                            </div>
                            <div className="space-y-2">
                                <label className="text-xs font-medium text-slate-400">Góc chụp</label>
                                <div className="grid grid-cols-2 gap-2">
                                    <button onClick={() => setSelfieFraming('Nửa thân')} className={`py-2 px-3 rounded-lg border text-xs font-medium ${selfieFraming === 'Nửa thân' ? 'bg-indigo-500/20 border-indigo-500 text-white' : 'bg-slate-800 border-slate-700 text-slate-400'}`}>Nửa thân (Waist Up)</button>
                                    <button onClick={() => setSelfieFraming('Toàn thân')} className={`py-2 px-3 rounded-lg border text-xs font-medium ${selfieFraming === 'Toàn thân' ? 'bg-indigo-500/20 border-indigo-500 text-white' : 'bg-slate-800 border-slate-700 text-slate-400'}`}>Toàn thân (Full Body)</button>
                                </div>
                            </div>
                        </div>
                    )}

                    {/* Number of Images Slider (Only show if 1 item uploaded) */}
                     {sessionItems.length === 1 && (
                         <div className="space-y-2 animate-fade-in-up">
                            <div className="flex justify-between">
                                 <label className="text-xs font-medium text-slate-400">Số lượng ảnh đầu ra</label>
                                 <span className="text-xs font-bold text-indigo-400">{numberOfImages}</span>
                            </div>
                            <input 
                                type="range" 
                                min="1" max="4" 
                                value={numberOfImages} 
                                onChange={(e) => setNumberOfImages(Number(e.target.value))}
                                className="w-full h-2 bg-slate-700 rounded-lg appearance-none cursor-pointer accent-indigo-500"
                            />
                        </div>
                     )}

                    {/* Action Button */}
                    <button
