// Helpers
const fileToPart = (base64String: string, mimeType: string) => {
    return {
        inlineData: {
            data: base64String,
            mimeType
        }
    };
};

const base64ToArrayBuffer = (base64: string) => {
    const binaryString = window.atob(base64);
    const len = binaryString.length;
    const bytes = new Uint8Array(len);
    for (let i = 0; i < len; i++) {
        bytes[i] = binaryString.charCodeAt(i);
    }
    return bytes.buffer;
};

// PCM to WAV Converter
const pcmToWav = (pcmData: ArrayBuffer, sampleRate: number = 24000, numChannels: number = 1, bitDepth: number = 16): Blob => {
    const dataView = new DataView(pcmData);
    const numSamples = pcmData.byteLength / (bitDepth / 8);
    const blockAlign = numChannels * (bitDepth / 8);
    const byteRate = sampleRate * blockAlign;
    const dataSize = numSamples * blockAlign;

    const buffer = new ArrayBuffer(44 + dataSize);
    const view = new DataView(buffer);

    // RIFF identifier
    writeString(view, 0, 'RIFF');
    // RIFF chunk length
    view.setUint32(4, 36 + dataSize, true);
    // RIFF type
    writeString(view, 8, 'WAVE');
    // format chunk identifier
    writeString(view, 12, 'fmt ');
    // format chunk length
    view.setUint32(16, 16, true);
    // sample format (raw)
    view.setUint16(20, 1, true);
    // channel count
    view.setUint16(22, numChannels, true);
    // sample rate
    view.setUint32(24, sampleRate, true);
    // byte rate (sample rate * block align)
    view.setUint32(28, byteRate, true);
    // block align (channel count * bytes per sample)
    view.setUint16(32, blockAlign, true);
    // bits per sample
    view.setUint16(34, bitDepth, true);
    // data chunk identifier
    writeString(view, 36, 'data');
    // data chunk length
    view.setUint32(40, dataSize, true);

    // Write PCM samples
    const pcmBytes = new Uint8Array(pcmData);
    const wavBytes = new Uint8Array(buffer, 44);
    wavBytes.set(pcmBytes);

    return new Blob([buffer], { type: 'audio/wav' });
};

const writeString = (view: DataView, offset: number, string: string) => {
    for (let i = 0; i < string.length; i++) {
        view.setUint8(offset + i, string.charCodeAt(i));
    }
};

// Model Selector Helper
const getImageModel = (level: ModelLevel) => {
    return level === 'pro' ? 'gemini-3-pro-image-preview' : 'gemini-2.5-flash-image';
};

const getTextModel = (level: ModelLevel) => {
    return level === 'pro' ? 'gemini-3-pro-preview' : 'gemini-2.5-flash';
};


// Implementations

export const generateBackgroundSuggestion = async (base64Image: string, mimeType: string, clothingType: string, modelLevel: ModelLevel): Promise<string> => {
    try {
        const model = getTextModel(modelLevel);
        const prompt = `Suggest a short, artistic background description (under 20 words) suitable for a fashion photo of this ${clothingType}. In Vietnamese.`;

        const response = await ai.models.generateContent({
            model,
            contents: {
                parts: [fileToPart(base64Image, mimeType), { text: prompt }]
            }
        });
        return response.text || "";
    } catch (e) {
        console.error("Generate Background Error", e);
        return "Phông nền studio chuyên nghiệp";
    }
}

export const generateStyledImage = async (base64Image: string, mimeType: string, clothingType: string, aspectRatio: AspectRatio, displayMode: ProductDisplayMode, count: number, modelLevel: ModelLevel, rugOptions?: RugOptions): Promise<string[]> => {
    const results: string[] = [];
    const model = getImageModel(modelLevel);

    for(let i=0; i<count; i++) {
        try {
            let prompt = `Generate a professional product photo of this ${clothingType}. `;

            if (displayMode === 'flatlay') {
                // Construct logic for Rug styling
                let rugStylePrompt = "";
                let rugColorPrompt = "";
                let rugPatternPrompt = "";

                // Style Logic
                if (!rugOptions || rugOptions.style === 'Tự động') {
                    rugStylePrompt = "high-end, aesthetic rug material that perfectly compliments the clothing style";
                } else {
                    const styleMap: Record<string, string> = {
                        'Lông mềm (Fur)': 'soft plush faux fur',
                        'Thảm Ba Tư (Vintage)': 'vintage Persian intricate',
                        'Dệt Boho': 'Bohemian woven texture',
                        'Tối giản (Minimalist)': 'minimalist clean fabric',
                        'Lụa sang trọng': 'luxurious silk-like'
                    };
                    rugStylePrompt = styleMap[rugOptions.style] || rugOptions.style;
                }

                // Color Logic
                if (!rugOptions || rugOptions.color === 'Tự động') {
                    rugColorPrompt = "a color that provides excellent contrast to the product (e.g. if product is dark use light rug, if product is light use subtle pastel or neutral rug)";
                } else {
                    const colorMap: Record<string, string> = {
                        'Trắng/Kem': 'creamy white',
                        'Be (Beige)': 'warm beige',
                        'Xám': 'neutral grey',
                        'Pastel': 'soft pastel',
                        'Tối màu': 'dark elegant charcoal'
                    };
                    rugColorPrompt = colorMap[rugOptions.color] || rugOptions.color;
                }

                // Pattern Logic
                if (!rugOptions || rugOptions.pattern === 'Tự động') {
                    rugPatternPrompt = "a subtle texture or pattern that adds depth without being distracting";
                } else {
                     const patternMap: Record<string, string> = {
                        'Trơn (Solid)': 'solid color with texture only (no print)',
                        'Hình học (Geometric)': 'modern geometric lines pattern',
                        'Vân sóng': 'gentle wavy curves pattern',
                        'Trừu tượng': 'artistic abstract shapes'
                    };
                    rugPatternPrompt = patternMap[rugOptions.pattern] || rugOptions.pattern;
                }

                prompt += `Placement: Flatlay top-down view. 
                Background: The product is laid flat centrally on a ${rugColorPrompt} ${rugStylePrompt} rug.
                Rug Details: The rug features ${rugPatternPrompt}.
                Key Requirement: The product must be the ABSOLUTE HIGHLIGHT. The rug is background only. Ensure sharp focus on the clothing item. High contrast between product and rug.
                Lighting: Bright, natural, high-key studio lighting, soft shadows, creating a cozy and expensive look.`;
            } else {
                prompt += `Display mode: Hanging on a rack or shelf. Aspect Ratio: ${aspectRatio}. High quality bright studio lighting.`;
            }

            // Quality enhancement keywords
            prompt += ` Quality: 2k resolution, ultra-sharp focus, highly detailed texture, bright and airy colors, white balance, photorealistic masterpiece, no blur.`;

            const response = await ai.models.generateContent({
                model,
                contents: {
                    parts: [
                        fileToPart(base64Image, mimeType),
                        { text: prompt }
                    ]
                }
            });

            if(response.candidates?.[0]?.content?.parts) {
                for (const part of response.candidates[0].content.parts) {
                    if (part.inlineData && part.inlineData.data) {
                        results.push(part.inlineData.data);
                        break; 
                    }
                }
            }
        } catch (e) {
            console.error(`Error generating image ${i+1}:`, e);
        }
    }

    if (results.length === 0) {
        throw new Error("Không thể tạo ảnh. Vui lòng thử lại sau.");
    }
    return results;
}

export const generateModelImage = async (base64Image: string, mimeType: string, options: ModelImageOptions, modelLevel: ModelLevel): Promise<{imageUrl: string, videoPrompt: string}[]> => {
    const results: {imageUrl: string, videoPrompt: string}[] = [];
