  const handleGenerate = useCallback(async () => {
    if (!text.trim()) {
        setError('Vui lòng nhập văn bản.');
        setAppState('ERROR');
        return;
    }

    setAppState('PROCESSING');
    setError(null);
    setAudioUrl(null);

    try {
        // Construct prompt based on SSML setting
        let promptText = text;
        const isSSMLRequest = enableSSML;

        if (!enableSSML) {
            // If not raw SSML mode, we wrap the text in SSML to control speed/pitch behind the scenes
            // or just send text if default values. 
            // Gemini supports some SSML tags. <prosody> is key for rate/pitch.
            if (speed !== 1.0 || pitch !== 0) {
                 // Convert pitch number to semi-tones string (e.g., "+2st", "-5st")
                 const pitchSt = pitch >= 0 ? `+${pitch}st` : `${pitch}st`;
                 promptText = `
                    <speak>
                        <prosody rate="${speed}" pitch="${pitchSt}">
                            ${text}
                        </prosody>
                    </speak>
                 `;
            }
        }

        // We pass 'true' for isSSML if we either enabled it explicitly OR if we wrapped it ourselves.
        const shouldUseSSMLMode = enableSSML || (speed !== 1.0 || pitch !== 0);

        const wavBlob = await generateSpeech(promptText, selectedVoice.id, shouldUseSSMLMode);
        const url = URL.createObjectURL(wavBlob);
        setAudioUrl(url);
        setAppState('SUCCESS');
    } catch (err: any) {
        console.error(err);
        setError(err.message || 'Không thể tạo giọng nói.');
        setAppState('ERROR');
    }
  }, [text, selectedVoice, speed, pitch, enableSSML]);

