            <div className="grid grid-cols-1 lg:grid-cols-12 gap-6">

                {/* Column 1: Settings (3 cols) */}
                <div className="lg:col-span-3 space-y-4">
                    <div className="bg-slate-800 rounded-xl border border-slate-700 p-5 h-full">
                        <h2 className="text-sm font-bold text-slate-200 mb-4 border-b border-slate-700 pb-2">Cài đặt</h2>

                        <div className="space-y-5">
                            <div>
                                <label className="block text-xs font-semibold text-slate-400 mb-1.5">Ngôn ngữ (Language)</label>
                                <select className="w-full bg-slate-900 border border-slate-600 rounded-lg px-3 py-2 text-sm text-white focus:ring-1 focus:ring-indigo-500 outline-none">
                                    <option>Tiếng Việt</option>
                                    <option>English (Coming soon)</option>
                                </select>
                            </div>

                            <div>
                                <label className="block text-xs font-semibold text-slate-400 mb-1.5">Giọng đọc (Voice)</label>
                                <select 
                                    value={selectedVoice.id}
                                    onChange={(e) => {
                                        const voice = VOICES.find(v => v.id === e.target.value);
                                        if (voice) setSelectedVoice(voice);
                                    }}
                                    className="w-full bg-slate-900 border border-slate-600 rounded-lg px-3 py-2 text-sm text-white focus:ring-1 focus:ring-indigo-500 outline-none"
                                >
                                    {VOICES.map(v => (
                                        <option key={v.id} value={v.id}>{v.label}</option>
                                    ))}
                                </select>
                                <p className="text-xs text-slate-500 mt-2 italic leading-relaxed">{selectedVoice.description}</p>
                            </div>

                            <div>
                                <div className="flex justify-between mb-1">
                                    <label className="block text-xs font-semibold text-slate-400">Tốc độ (Speed)</label>
                                    <span className="text-xs text-indigo-400 font-mono">{speed.toFixed(2)}x</span>
