        throw new Error("Không thể tạo ảnh selfie. Vui lòng thử lại.");
    }
    return results;
}

export const generateLookbookImages = async (base64Image: string, mimeType: string, options: LookbookOptions, modelLevel: ModelLevel): Promise<LookbookResult[]> => {
    const results: LookbookResult[] = [];
    const model = getImageModel(modelLevel);
    const genderEn = options.gender === 'Nam' ? 'male' : 'female';

    // Determine ethnicity specific prompt details
    let ethnicityPrompt = "";
    const beautyTerms = options.gender === 'Nam' ? 'handsome, attractive face' : 'beautiful, pretty face';

    if (options.ethnicity === 'Hàn Quốc') {
        ethnicityPrompt = "Korean (K-pop idol aesthetic, pale white skin, trendy hairstyle)";
    } else {
        ethnicityPrompt = "Vietnamese (distinctive Vietnamese Asian features, fair white skin, glowing skin)";
    }

    // Define variations to ensure background diversity in batch mode
    const backgroundVariations = [
        "Wide angle view showing the depth of the environment.",
        "Close-up background texture/architecture with shallow depth of field (bokeh).",
        "Angled perspective showing a different side of the location.",
        "High contrast lighting area of the setting.",
        "Symmetric background composition with clean lines."
    ];

    for(let i=0; i<options.numberOfImages; i++) {
        try {
            // Map the pose to English description while keeping strict "Front facing" constraint
            const poseDescription = options.pose === 'Dáng đi' 
                ? 'Walking forward towards the camera, dynamic movement' 
                : 'Standing confident upright, power pose';

            // Select a variation strategy based on the index to force diverse backgrounds
            const backgroundStrategy = backgroundVariations[i % backgroundVariations.length];

            // Enhanced Lookbook Prompt - Strict constraints on skin tone, pose, and smile
            const prompt = `Fashion Lookbook Photography. A ${options.age} year old ${ethnicityPrompt} ${genderEn} model (${beautyTerms}, smiling gently, happy expression, warm vibes) wearing this ${options.clothingType}.
            Pose: ${poseDescription}, Front facing, looking directly at camera.
            Theme: ${options.theme}.
            Background Composition Strategy: ${backgroundStrategy}. (Crucial: Ensure this background composition is distinct from other images in the same location).
            Additional details: ${options.additionalPrompt || 'None'}.
            Lighting: Bright airy lighting, sunlight, high-key, sharp contrast, clear colors.
            Aspect Ratio: ${options.aspectRatio}.
            Quality: 2k resolution, ultra-sharp focus, highly detailed texture, fair white skin texture, photorealistic masterpiece, 8k uhd, magazine quality.`;

             const response = await ai.models.generateContent({
                model,
                contents: {
                    parts: [
                        fileToPart(base64Image, mimeType),
                        { text: prompt }
                    ]
                }
            });

            let imageUrl = "";
            if(response.candidates?.[0]?.content?.parts) {
                for (const part of response.candidates[0].content.parts) {
                    if (part.inlineData && part.inlineData.data) {
                        imageUrl = `data:image/jpeg;base64,${part.inlineData.data}`;
                        break; 
                    }
                }
            }

            if (imageUrl) {
                 let videoPrompt = "";
                 if (options.generateVideo) {
                     let actionDescription = "";
                     let cameraDescription = "";

                     if (options.pose === 'Dáng đi') {
                         // Walking logic: Tracking shot, keep in frame
                         actionDescription = "walking forward casually like strolling, confident gait";
                         cameraDescription = "Camera performs a smooth tracking shot (dolly out) moving backwards at the exact same speed as the model. The model must remain perfectly framed (full body visible, head to toe) at all times. No zooming, no cuts, continuous one-shot.";
                     } else {
                         // Standing logic: Static camera, subtle poses
                         actionDescription = "standing at a fixed location, making subtle poses to showcase the outfit, taking small subtle steps in place or shifting weight without moving away. No talking";
                         cameraDescription = "Static camera (tripod shot), absolutely no camera movement or zooming. The frame is fixed and stable. Continuous one-shot.";
                     }

                     videoPrompt = `Cinematic one-shot video (no cuts). A beautiful ${ethnicityPrompt} ${genderEn} model with fair skin wearing ${options.clothingType}, located in ${options.theme}. 
                     Action: The model is ${actionDescription}. Looking directly at camera, smiling gently, happy expression.
                     Camera: ${cameraDescription}
                     Style: High fashion, 4k resolution, shallow depth of field, slow motion, photorealistic.`;
                 }
                 results.push({ imageUrl, videoPrompt });
            }

        } catch (e) {
            console.error(`Error generating lookbook image ${i+1}:`, e);
        }
    }

    if (results.length === 0) {
        throw new Error("Không thể tạo ảnh Lookbook. Vui lòng thử lại.");
    }
    return results;
}

