export const generateSpeech = async (text: string, voiceName: string, isSSML: boolean = false): Promise<Blob> => {
    try {
        // If not explicit SSML, wrap with a natural prompt helper, otherwise send raw
        const prompt = isSSML ? text : `Read the following text in Vietnamese naturally, with emotion: "${text}"`;

        const response = await ai.models.generateContent({
            model: 'gemini-2.5-flash-preview-tts',
            contents: {
                parts: [{ text: prompt }]
            },
            config: {
                responseModalities: [Modality.AUDIO],
                speechConfig: {
                    voiceConfig: {
                        prebuiltVoiceConfig: { voiceName: voiceName }
                    }
                }
            }
        });

        const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
        if (!base64Audio) {
            throw new Error("No audio data returned");
        }

        // Convert base64 to PCM ArrayBuffer
        const pcmBuffer = base64ToArrayBuffer(base64Audio);

        // Convert PCM to WAV Blob for easy playback and download
        // Gemini TTS typically returns 24kHz mono PCM
        return pcmToWav(pcmBuffer, 24000, 1);
    } catch (e) {
        console.error("Generate Speech Error", e);
        throw new Error("Không thể tạo giọng nói. Vui lòng thử lại.");
    }
}

import React, { useState, useCallback, useRef, useEffect } from 'react';
import { generateStyledImage, generateModelImage, generateSelfieImage, ModelPose, AspectRatio, generateBackgroundSuggestion, ProductDisplayMode, SelfieFraming, RugStyle, RugColor, RugPattern, ModelLevel } from './services/geminiService';
import { UploadIcon, SparklesIcon, LoadingSpinner, ErrorIcon, HangerIcon, UserIcon, ArrowLeftIcon, DownloadIcon, XIcon, RefreshIcon, WandIcon, ClipboardIcon, ClipboardCheckIcon, CameraIcon, ZoomInIcon } from './components/Icons';

type ClothingType = 'Áo' | 'Quần' | 'Cả bộ' | 'Váy' | 'Phụ kiện';
type FeatureMode = 'product' | 'model' | 'selfie';
type Gender = 'Nam' | 'Nữ';
type ItemStatus = 'IDLE' | 'PROCESSING' | 'SUCCESS' | 'ERROR';

// Interface for each item in the session
interface SessionItem {
    id: string;
    file: File;
    inputPreviewUrl: string; // The original uploaded image
    outputUrl?: string;      // The generated result
    videoPrompt?: string;    // For model mode
    status: ItemStatus;
    error?: string;
}

interface ProductStudioProps {
  onGoBack: () => void;
  onEnhanceImage: (imageUrl: string) => void;
  modelLevel: ModelLevel;
}

const SELFIE_BACKGROUNDS = [
    "Phòng ngủ tối giản, gương đứng (Minimalist Bedroom)",
    "Phòng thay đồ sang trọng (Walk-in Closet)",
    "Gương phòng tắm hiện đại (Modern Bathroom)",
    "Góc quán cafe chill (Coffee Shop)",
    "Phòng tập Gym (Gym Mirror)",
    "Thang máy khách sạn (Elevator)",
    "Phòng thử đồ thời trang (Fitting Room)",
    "Bức tường gạch trắng (White Brick Wall)",
    "Công viên xanh mát (Green Park)",
    "Bãi biển hoàng hôn (Beach Sunset)",
    "Đường phố thành thị mờ ảo (City Street Bokeh)",
    "Studio phông xám chuyên nghiệp (Studio Grey)",
    "Ánh đèn Neon (Neon Lights)",
    "Góc cửa sổ nắng đẹp (Sunlit Window)",
    "Tường hoa nghệ thuật (Flower Wall)",
    "Kệ sách thư viện (Library Bookshelf)",
    "Hành lang chung cư cao cấp (Luxury Hallway)",
    "Gương trang điểm có đèn (Vanity Mirror)",
    "Bầu trời xanh trong (Blue Sky)",
    "Tường bê tông thô (Concrete Wall)"
];

const ProductStudio: React.FC<ProductStudioProps> = ({ onGoBack, onEnhanceImage, modelLevel }) => {
  // Core state: List of session items instead of single file
  const [sessionItems, setSessionItems] = useState<SessionItem[]>([]);

  // Global App State (mostly for the big generate button)
  const [isGlobalProcessing, setIsGlobalProcessing] = useState(false);
  const [zoomImage, setZoomImage] = useState<string | null>(null);

  // Feature selection state
  const [featureMode, setFeatureMode] = useState<FeatureMode>('product');
  const [clothingType, setClothingType] = useState<ClothingType>('Áo');
  const [aspectRatio, setAspectRatio] = useState<AspectRatio>('9:16');
  const [productDisplayMode, setProductDisplayMode] = useState<ProductDisplayMode>('hanger');

  // Flatlay Rug State
  const [rugStyle, setRugStyle] = useState<RugStyle>('Tự động');
  const [rugColor, setRugColor] = useState<RugColor>('Tự động');
  const [rugPattern, setRugPattern] = useState<RugPattern>('Tự động');

  // Model-specific state
  const [gender, setGender] = useState<Gender>('Nữ');
  const [age, setAge] = useState<string>('18-25');
  const [background, setBackground] = useState<string>('');
  const [numberOfImages, setNumberOfImages] = useState<number>(1); // Only used if sessionItems.length === 1
  const [modelPose, setModelPose] = useState<ModelPose>('Dáng đứng');
  const [isGeneratingBackground, setIsGeneratingBackground] = useState<boolean>(false);
  const [copiedPromptIndex, setCopiedPromptIndex] = useState<string | null>(null);

  // Selfie specific state
  const [selfieFraming, setSelfieFraming] = useState<SelfieFraming>('Nửa thân');
  const [selfieBackground, setSelfieBackground] = useState<string>(SELFIE_BACKGROUNDS[0]);

  const fileInputRef = useRef<HTMLInputElement>(null);

  // Helper to read file to base64
  const fileToBase64 = (file: File): Promise<string> => {
      return new Promise((resolve, reject) => {
          const reader = new FileReader();
          reader.readAsDataURL(file);
          reader.onload = () => {
              const result = reader.result as string;
              resolve(result.split(',')[1]);
          };
          reader.onerror = error => reject(error);
      });
  };

  const handleFileChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    const files = event.target.files;
    if (files && files.length > 0) {
        const newItems: SessionItem[] = Array.from(files)
            .filter((file: File) => file.type.startsWith('image/'))
            .map((file: File) => ({
                id: `item_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
                file,
                inputPreviewUrl: URL.createObjectURL(file),
                status: 'IDLE'
            }));

        setSessionItems(prev => [...prev, ...newItems]);
    }
    // Reset input
    if (fileInputRef.current) fileInputRef.current.value = "";
  };

  const handleRemoveItem = (id: string, e?: React.MouseEvent) => {
    e?.stopPropagation();
    setSessionItems(prev => {
        const itemToRemove = prev.find(item => item.id === id);
        if (itemToRemove) {
            // Clean up object URL
            // URL.revokeObjectURL(itemToRemove.inputPreviewUrl); // Optional: creates flicker if removing quickly, browser handles GC eventually
        }
        return prev.filter(item => item.id !== id);
    });
  };

  const handleClearAll = () => {
      setSessionItems([]);
      setBackground('');
  };

  const handleGenerateBackground = async () => {
    // Only use the first image for background suggestion
    const firstItem = sessionItems[0];
    if (!firstItem || !clothingType) return;

    setIsGeneratingBackground(true);
    try {
        const base64String = await fileToBase64(firstItem.file);
        const suggestion = await generateBackgroundSuggestion(base64String, firstItem.file.type, clothingType, modelLevel);
        setBackground(suggestion.trim().replace(/^"|"$/g, '')); 
    } catch (err: any) {
        console.error("BG Gen Error", err);
    } finally {
        setIsGeneratingBackground(false);
    }
  };

  // The Core Worker Function for a SINGLE Item
  const processItem = async (item: SessionItem): Promise<SessionItem> => {
      try {
          const base64String = await fileToBase64(item.file);

          const effectiveCount = 1; // We process per item card.

          if (featureMode === 'product') {
              const urls = await generateStyledImage(
                  base64String, item.file.type, clothingType, aspectRatio, productDisplayMode, effectiveCount, modelLevel,
                  productDisplayMode === 'flatlay' ? { style: rugStyle, color: rugColor, pattern: rugPattern } : undefined
              );
              return { ...item, outputUrl: `data:image/jpeg;base64,${urls[0]}`, status: 'SUCCESS', error: undefined };

          } else if (featureMode === 'model') {
              const results = await generateModelImage(base64String, item.file.type, {
                  clothingType, gender, age, background, numberOfImages: effectiveCount, pose: modelPose, aspectRatio
              }, modelLevel);
              return { ...item, outputUrl: results[0].imageUrl, videoPrompt: results[0].videoPrompt, status: 'SUCCESS', error: undefined };

          } else { // selfie
              const urls = await generateSelfieImage(base64String, item.file.type, clothingType, effectiveCount, gender, selfieFraming, selfieBackground, modelLevel);
              return { ...item, outputUrl: `data:image/jpeg;base64,${urls[0]}`, status: 'SUCCESS', error: undefined };
          }
      } catch (e: any) {
          return { ...item, status: 'ERROR', error: e.message || 'Error generating image' };
      }
  };

  // Generate All (Batch)
  const handleGenerateAll = async () => {
    if (sessionItems.length === 0) return;
    if (featureMode === 'model' && !background.trim()) {
        alert("Vui lòng nhập mô tả bối cảnh");
        return;
    }

    setIsGlobalProcessing(true);

    // If there is ONLY 1 item and user requested N images (slider > 1).
    // We need to clone the input item N times to simulate batch processing for variants.
    if (sessionItems.length === 1 && numberOfImages > 1) {
        const seedItem = sessionItems[0];
        const newItems: SessionItem[] = [];
        // Keep the original as the first one
        newItems.push({...seedItem, status: 'PROCESSING'});
        // Add copies
        for(let i = 1; i < numberOfImages; i++) {
             newItems.push({
                 ...seedItem,
                 id: seedItem.id + `_variant_${i}`,
                 status: 'PROCESSING'
             });
        }
        setSessionItems(newItems);

        // Now process them in parallel
        const promises = newItems.map(item => processItem(item));
        const results = await Promise.all(promises);

        setSessionItems(results);
    } else {
        // Normal Batch Mode (or Single Mode with count=1)
        // Mark all IDLE or ERROR items as PROCESSING
        setSessionItems(prev => prev.map(item => 
            (item.status === 'IDLE' || item.status === 'ERROR' || item.status === 'SUCCESS') 
            ? { ...item, status: 'PROCESSING', error: undefined } 
            : item
        ));

        // Create a working copy of current items to process
        // We act on the *current* list state
        const itemsToProcess = sessionItems.map(item => ({...item, status: 'PROCESSING' as ItemStatus}));

        // Execute in parallel

        const updateItemResult = (updatedItem: SessionItem) => {
             setSessionItems(prev => prev.map(i => i.id === updatedItem.id ? updatedItem : i));
        };

        const promises = itemsToProcess.map(async (item) => {
             const result = await processItem(item);
             updateItemResult(result);
        });

        await Promise.all(promises);
    }

    setIsGlobalProcessing(false);
  };

  // Regenerate Single Item
  const handleRegenerateItem = async (id: string) => {
      const itemToRegen = sessionItems.find(i => i.id === id);
      if (!itemToRegen) return;
      if (featureMode === 'model' && !background.trim()) {
          alert("Vui lòng nhập bối cảnh");
          return;
      }

      // Update status to processing
      setSessionItems(prev => prev.map(i => i.id === id ? { ...i, status: 'PROCESSING', error: undefined } : i));

      // Process
      const result = await processItem(itemToRegen);

      // Update result
      setSessionItems(prev => prev.map(i => i.id === id ? result : i));
  };

  const triggerFileInput = () => {
    fileInputRef.current?.click();
  };

  const handleCopyToClipboard = (textToCopy: string, id: string) => {
    navigator.clipboard.writeText(textToCopy);
    setCopiedPromptIndex(id);
    setTimeout(() => setCopiedPromptIndex(null), 2000);
  };

  const isGenerateButtonDisabled = () => {
    if (isGlobalProcessing || sessionItems.length === 0) return true;
    if (featureMode === 'model' && !background.trim()) return true;
    return false;
  }

  return (
    <div className="flex flex-col h-screen overflow-hidden bg-slate-900 text-slate-200">
      {/* Zoom Modal */}
      {zoomImage && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/90 backdrop-blur-sm p-4 animate-fade-in" onClick={() => setZoomImage(null)}>
            <button className="absolute top-4 right-4 text-white hover:text-gray-300 p-2 bg-white/10 rounded-full" onClick={() => setZoomImage(null)}>
                <XIcon className="w-8 h-8" />
            </button>
            <img src={zoomImage} alt="Zoom" className="max-w-full max-h-[90vh] object-contain rounded-lg shadow-2xl" onClick={(e) => e.stopPropagation()} />
        </div>
      )}

      {/* Header */}
      <header className="flex-none h-16 border-b border-slate-700 bg-slate-800/50 backdrop-blur-md flex items-center px-6 justify-between z-20">
        <div className="flex items-center">
            <button onClick={onGoBack} className="flex items-center text-slate-400 hover:text-white transition-colors mr-4">
                <ArrowLeftIcon className="w-5 h-5 mr-2"/>
                <span className="font-medium">Trang chủ</span>
            </button>
            <div className="h-6 w-px bg-slate-700 mx-4"></div>
            <h1 className="text-lg font-bold text-white tracking-tight">Studio Sản phẩm AI (Batch Mode)</h1>
        </div>
        <div className="flex items-center space-x-2">
            <span className={`text-xs font-mono px-2 py-1 rounded border ${modelLevel === 'pro' ? 'bg-purple-500/20 border-purple-500/30 text-purple-300' : 'bg-indigo-500/10 border-indigo-500/20 text-indigo-400'}`}>
                {modelLevel === 'pro' ? 'GEMINI 3 PRO' : 'GEMINI 2.5 FLASH'}
            </span>
        </div>
      </header>

      {/* Main Layout */}
      <div className="flex-1 flex overflow-hidden">

        {/* Left Sidebar: Controls */}
        <div className="w-full md:w-[400px] lg:w-[450px] flex-none border-r border-slate-700 bg-slate-800/50 overflow-y-auto custom-scrollbar">
            <div className="p-6 space-y-8">

                {/* 1. Image Upload (Multiple) */}
                <div className="space-y-3">
                    <div className="flex justify-between items-center">
                        <h2 className="text-sm font-bold text-slate-400 uppercase tracking-wider">1. Ảnh gốc ({sessionItems.length})</h2>
                        {sessionItems.length > 0 && (
                            <button onClick={handleClearAll} className="text-xs text-red-400 hover:text-red-300 underline">Xóa hết</button>
                        )}
                    </div>

                    <input type="file" ref={fileInputRef} onChange={handleFileChange} accept="image/*" multiple className="hidden" />

                    {sessionItems.length === 0 ? (
                        <div 
                            onClick={triggerFileInput}
