                    <div className="grid grid-cols-3 gap-2 p-1 bg-slate-900 rounded-xl">
                        {[
                            { id: 'product', icon: HangerIcon, label: 'Sản phẩm' },
                            { id: 'model', icon: UserIcon, label: 'Mẫu ảo' },
                            { id: 'selfie', icon: CameraIcon, label: 'Selfie' }
