export const generateStyledImage = async (base64Image: string, mimeType: string, clothingType: string, aspectRatio: AspectRatio, displayMode: ProductDisplayMode, count: number, modelLevel: ModelLevel, rugOptions?: RugOptions): Promise<string[]> => {
    const results: string[] = [];
    const model = getImageModel(modelLevel);

    for(let i=0; i<count; i++) {
        try {
            let prompt = `Generate a high-end professional product photo of this ${clothingType}. `;

            if (displayMode === 'flatlay') {
                // Construct logic for Rug styling
                let rugStylePrompt = "";
                let rugColorPrompt = "";
                let rugPatternPrompt = "";

                // Style Logic
                if (!rugOptions || rugOptions.style === 'Tự động') {
                    rugStylePrompt = "soft plush faux fur";
                } else {
                    const styleMap: Record<string, string> = {
                        'Lông mềm (Fur)': 'soft plush faux fur',
                        'Thảm Ba Tư (Vintage)': 'vintage Persian intricate',
                        'Dệt Boho': 'Bohemian woven texture',
                        'Tối giản (Minimalist)': 'minimalist clean fabric',
                        'Lụa sang trọng': 'luxurious silk-like'
                    };
                    rugStylePrompt = styleMap[rugOptions.style] || rugOptions.style;
                }

                // Color Logic
                if (!rugOptions || rugOptions.color === 'Tự động') {
                    rugColorPrompt = "creamy white or warm beige";
                } else {
                    const colorMap: Record<string, string> = {
                        'Trắng/Kem': 'creamy white',
                        'Be (Beige)': 'warm beige',
                        'Xám': 'neutral grey',
                        'Pastel': 'soft pastel',
                        'Tối màu': 'dark elegant charcoal'
                    };
                    rugColorPrompt = colorMap[rugOptions.color] || rugOptions.color;
                }

                // Pattern Logic
                if (!rugOptions || rugOptions.pattern === 'Tự động') {
                    rugPatternPrompt = "subtle fluffy texture";
                } else {
                     const patternMap: Record<string, string> = {
                        'Trơn (Solid)': 'solid color with natural texture',
                        'Hình học (Geometric)': 'modern geometric lines pattern',
                        'Vân sóng': 'gentle wavy curves pattern',
                        'Trừu tượng': 'artistic abstract shapes'
                    };
                    rugPatternPrompt = patternMap[rugOptions.pattern] || rugOptions.pattern;
                }

                prompt += `
                Composition: Top-down flatlay shot. The ${clothingType} MUST be placed DEAD CENTER of the frame, perfectly aligned and symmetrical.
                Placement: The ${clothingType} is laid out neatly and centered on a ${rugColorPrompt} ${rugStylePrompt} rug.
                Environment: The rug is placed on a beautiful dark polished wooden floor, right next to a large, bright window with elegant translucent white curtains.
                Lighting: Soft, natural morning sunlight streaming in through the sheer curtains, creating gentle cinematic highlights and soft-edged shadows.
                Details: The rug has ${rugPatternPrompt}. Every detail and texture of the ${clothingType} must be ultra-sharp and prominent.
                Style: High-end lifestyle fashion catalog, minimal, clean, aesthetic.`;
            } else {
                prompt += `Display mode: Hanging on a minimalist rack. Background: Clean boutique interior. Aspect Ratio: ${aspectRatio}. Bright natural indoor lighting.`;
            }

            // Quality enhancement keywords
            prompt += ` Quality: 4k resolution, ultra-sharp focus, highly detailed fabric texture, realistic colors, professional white balance, no blur, high fidelity.`;

            const response = await ai.models.generateContent({
                model,
                contents: {
                    parts: [
                        fileToPart(base64Image, mimeType),
                        { text: prompt }
                    ]
                }
            });

            if(response.candidates?.[0]?.content?.parts) {
                for (const part of response.candidates[0].content.parts) {
                    if (part.inlineData && part.inlineData.data) {
                        results.push(part.inlineData.data);
                        break; 
                    }
                }
            }
        } catch (e) {
            console.error(`Error generating image ${i+1}:`, e);
        }
    }

    if (results.length === 0) {
        throw new Error("Không thể tạo ảnh. Vui lòng thử lại sau.");
    }
    return results;
}

export const generateModelImage = async (base64Image: string, mimeType: string, options: ModelImageOptions, modelLevel: ModelLevel): Promise<{imageUrl: string, videoPrompt: string}[]> => {
