    let ethnicityPrompt = "";
    const beautyTerms = options.gender === 'Nam' ? 'handsome, attractive face' : 'beautiful, pretty face';

    if (options.ethnicity === 'Hàn Quốc') {
        ethnicityPrompt = "Korean (K-pop idol aesthetic, pale white skin, trendy hairstyle)";
    } else {
        ethnicityPrompt = "Vietnamese (distinctive Vietnamese Asian features, fair white skin, glowing skin)";
    }

    // Define variations to ensure background diversity in batch mode
    const backgroundVariations = [
        "Wide angle view showing the depth of the environment.",
        "Close-up background texture/architecture with shallow depth of field (bokeh).",
        "Angled perspective showing a different side of the location.",
        "High contrast lighting area of the setting.",
