                                    <button key={ratio} onClick={() => setAspectRatio(ratio)} className={`flex-1 py-1.5 rounded text-xs font-medium transition-all ${aspectRatio === ratio ? 'bg-slate-700 text-white shadow' : 'text-slate-500 hover:text-slate-300'}`}>
