import React, { useState, useRef, useEffect } from 'react';
import { XIcon, DownloadIcon } from './Icons';

interface ImageCropperProps {
  imageSrc: string;
  onCropComplete: (croppedImage: string) => void;
  onCancel: () => void;
  initialAspectRatio?: number; // width / height
}

const ImageCropper: React.FC<ImageCropperProps> = ({ imageSrc, onCropComplete, onCancel, initialAspectRatio = 9/16 }) => {
  const [aspectRatio, setAspectRatio] = useState<number | null>(initialAspectRatio);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const imageRef = useRef<HTMLImageElement>(null);
  const [crop, setCrop] = useState({ x: 10, y: 10, width: 80, height: 80 });
  const [isDragging, setIsDragging] = useState(false);
  const [dragType, setDragType] = useState<'move' | 'resize' | null>(null);
  const [startPos, setStartPos] = useState({ x: 0, y: 0 });

  const ratios = [
    { label: '9:16', value: 9/16 },
    { label: '2:3', value: 2/3 },
    { label: '3:4', value: 3/4 },
    { label: '1:1', value: 1 },
    { label: 'Custom', value: null },
  ];

  useEffect(() => {
    // Tự động căn giữa khung cắt khi thay đổi tỉ lệ
    if (aspectRatio) {
      const newWidth = 60;
      const newHeight = (newWidth / aspectRatio);
      setCrop(prev => ({
        ...prev,
        width: newWidth,
        height: newHeight > 90 ? 90 : newHeight,
        x: (100 - newWidth) / 2,
        y: (100 - (newHeight > 90 ? 90 : newHeight)) / 2,
      }));
    }
  }, [aspectRatio]);

  const handleMouseDown = (e: React.MouseEvent, type: 'move' | 'resize') => {
    setIsDragging(true);
    setDragType(type);
    setStartPos({ x: e.clientX, y: e.clientY });
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    if (!isDragging) return;

    const dx = ((e.clientX - startPos.x) / window.innerWidth) * 100;
    const dy = ((e.clientY - startPos.y) / window.innerHeight) * 100;

    if (dragType === 'move') {
      setCrop(prev => ({
        ...prev,
        x: Math.max(0, Math.min(100 - prev.width, prev.x + dx)),
        y: Math.max(0, Math.min(100 - prev.height, prev.y + dy)),
      }));
    } else if (dragType === 'resize') {
      const newWidth = Math.max(10, Math.min(100 - crop.x, crop.width + dx));
      let newHeight = aspectRatio ? newWidth / aspectRatio : crop.height + dy;

      if (crop.y + newHeight > 100) {
        newHeight = 100 - crop.y;
      }

      setCrop(prev => ({
        ...prev,
        width: newWidth,
        height: newHeight,
      }));
    }
    setStartPos({ x: e.clientX, y: e.clientY });
  };

  const handleMouseUp = () => {
    setIsDragging(false);
    setDragType(null);
  };

  const handleConfirm = () => {
    const canvas = canvasRef.current;
    const img = imageRef.current;
    if (!canvas || !img) return;

    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const scaleX = img.naturalWidth / 100;
    const scaleY = img.naturalHeight / 100;

    const drawWidth = crop.width * scaleX;
    const drawHeight = crop.height * scaleY;

    canvas.width = drawWidth;
    canvas.height = drawHeight;

    ctx.drawImage(
      img,
      crop.x * scaleX,
      crop.y * scaleY,
      drawWidth,
      drawHeight,
      0,
      0,
      drawWidth,
      drawHeight
    );

    onCropComplete(canvas.toDataURL('image/jpeg', 0.9));
  };

  return (
    <div className="fixed inset-0 z-[100] bg-slate-950 flex flex-col animate-fade-in" onMouseMove={handleMouseMove} onMouseUp={handleMouseUp}>
      <header className="h-16 border-b border-slate-800 flex items-center justify-between px-6 bg-slate-900">
        <div className="flex items-center space-x-4">
          <button onClick={onCancel} className="p-2 text-slate-400 hover:text-white rounded-full bg-slate-800">
            <XIcon className="w-6 h-6" />
          </button>
          <h2 className="text-white font-bold">Cắt ảnh trang phục</h2>
        </div>
        <button 
          onClick={handleConfirm}
          className="px-6 py-2 bg-indigo-600 hover:bg-indigo-500 text-white font-bold rounded-lg shadow-lg transition-all"
        >
          Xác nhận cắt
        </button>
      </header>

      <div className="flex-1 relative flex items-center justify-center p-4 md:p-12 overflow-hidden bg-black/40">
        <div className="relative inline-block max-w-full max-h-full">
          <img 
            ref={imageRef}
            src={imageSrc} 
            alt="To crop" 
            className="max-w-full max-h-[70vh] object-contain select-none"
            onDragStart={(e) => e.preventDefault()}
          />

          {/* Overlay Vùng Cắt */}
          <div 
            className="absolute border-2 border-indigo-500 shadow-[0_0_0_9999px_rgba(0,0,0,0.6)] cursor-move touch-none"
            style={{
              left: `${crop.x}%`,
              top: `${crop.y}%`,
              width: `${crop.width}%`,
              height: `${crop.height}%`,
            }}
            onMouseDown={(e) => handleMouseDown(e, 'move')}
          >
            {/* Grid lines */}
            <div className="absolute inset-0 grid grid-cols-3 grid-rows-3 opacity-30">
               {[...Array(4)].map((_, i) => <div key={i} className="border-r border-white/50 border-b border-white/50"></div>)}
            </div>

            {/* Resize handle */}
            <div 
              className="absolute bottom-0 right-0 w-6 h-6 bg-indigo-500 cursor-nwse-resize flex items-center justify-center rounded-tl-sm"
              onMouseDown={(e) => { e.stopPropagation(); handleMouseDown(e, 'resize'); }}
            >
              <div className="w-1.5 h-1.5 bg-white rounded-full"></div>
            </div>
          </div>
        </div>
      </div>

      <footer className="bg-slate-900 border-t border-slate-800 p-6">
        <div className="max-w-2xl mx-auto">
          <p className="text-xs font-bold text-slate-500 uppercase tracking-widest mb-3 text-center">Chọn tỉ lệ khung hình</p>
          <div className="flex justify-center gap-2">
            {ratios.map((r) => (
              <button
                key={r.label}
                onClick={() => setAspectRatio(r.value)}
                className={`px-4 py-2 rounded-xl text-sm font-bold transition-all border
                  ${aspectRatio === r.value ? 'bg-indigo-600 border-indigo-500 text-white shadow-lg' : 'bg-slate-800 border-slate-700 text-slate-400 hover:border-slate-500'}
                `}
              >
                {r.label}
              </button>
            ))}
          </div>
          <p className="text-[10px] text-slate-500 mt-4 text-center">Mẹo: Căn trang phục vào giữa khung hình để AI nhận diện tốt nhất.</p>
        </div>
      </footer>
      <canvas ref={canvasRef} className="hidden" />
    </div>
  );
};

