            <div 
              className="absolute -bottom-1.5 -left-1.5 w-4 h-4 bg-white border-2 border-indigo-500 rounded-full cursor-sw-resize z-10"
              onMouseDown={(e) => { e.stopPropagation(); handleMouseDown(e, 'bl'); }}
